const fn sidebar_layout_width(sidebar_visible: bool) -> f32 {
    if sidebar_visible { SIDEBAR_WIDTH } else { 0.0 }
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum ShellWidthClass {
    Narrow,
    Compact,
    Wide,
}

fn shell_width_class(width: f32) -> ShellWidthClass {
    if width <= SIDEBAR_COLLAPSE_WIDTH {
        ShellWidthClass::Narrow
    } else if width <= RIGHT_PANEL_COLLAPSE_WIDTH {
        ShellWidthClass::Compact
    } else {
        ShellWidthClass::Wide
    }
}

fn modal_surface_width(viewport_width: f32, preferred_width: f32) -> f32 {
    preferred_width.min((viewport_width * MODAL_MAX_VIEWPORT_WIDTH_RATIO).max(0.0))
}

fn modal_surface_max_height(viewport_height: f32, preferred_height: f32) -> f32 {
    preferred_height.min((viewport_height - MODAL_VIEWPORT_VERTICAL_INSET).max(0.0))
}

