fn adjacent_task_id(
    tasks: &[TaskSummary],
    pinned_task_ids: &[String],
    selected_task_id: Option<&str>,
    next: bool,
) -> Option<String> {
    let ordered = visible_task_ids(tasks, pinned_task_ids);
    let selected_index = match selected_task_id {
        Some(selected_task_id) => ordered
            .iter()
            .position(|task_id| task_id == selected_task_id)?,
        None if next => return ordered.first().cloned(),
        None => return ordered.last().cloned(),
    };
    let adjacent_index = if next {
        selected_index.checked_add(1)?
    } else {
        selected_index.checked_sub(1)?
    };
    ordered.get(adjacent_index).cloned()
}

fn visible_task_ids(tasks: &[TaskSummary], pinned_task_ids: &[String]) -> Vec<String> {
    let mut ordered = pinned_task_ids
        .iter()
        .filter_map(|task_id| tasks.iter().find(|task| task.id == *task_id))
        .collect::<Vec<_>>();
    let recent = tasks
        .iter()
        .filter(|task| !pinned_task_ids.iter().any(|task_id| task_id == &task.id))
        .collect::<Vec<_>>();
    let mut project_cwds = Vec::<&Path>::new();
    for task in &recent {
        if !project_cwds.contains(&task.cwd.as_path()) {
            project_cwds.push(task.cwd.as_path());
        }
    }
    for cwd in project_cwds {
        ordered.extend(
            recent
                .iter()
                .copied()
                .filter(|task| task.cwd.as_path() == cwd),
        );
    }
    ordered.into_iter().map(|task| task.id.clone()).collect()
}

fn task_slot_id(
    tasks: &[TaskSummary],
    pinned_task_ids: &[String],
    one_based_slot: usize,
) -> Option<String> {
    visible_task_ids(tasks, pinned_task_ids)
        .get(one_based_slot.checked_sub(1)?)
        .cloned()
}

fn command_task_slot(command_id: &str) -> Option<usize> {
    command_id
        .strip_prefix("thread")?
        .parse::<usize>()
        .ok()
        .filter(|slot| (1..=9).contains(slot))
}

fn app_mention_prompt(app_id: &str, app_name: &str) -> String {
    let destination = format!("app://{app_id}")
        .replace('\\', "\\\\")
        .replace(')', "\\)");
    format!("[@{app_name}]({destination})")
}

fn app_chatgpt_url(install_url: &str, app_id: &str, connect: bool) -> Option<String> {
    if !is_supported_external_url(install_url) {
        return None;
    }
    let install_url = install_url
        .split_once('#')
        .map_or(install_url, |(base, _)| base);
    let mut encoded_id = String::with_capacity(app_id.len());
    const HEX: &[u8; 16] = b"0123456789ABCDEF";
    for byte in app_id.bytes() {
        if byte.is_ascii_alphanumeric() || matches!(byte, b'-' | b'.' | b'_' | b'~') {
            encoded_id.push(char::from(byte));
        } else {
            encoded_id.push('%');
            encoded_id.push(char::from(HEX[usize::from(byte >> 4)]));
            encoded_id.push(char::from(HEX[usize::from(byte & 0x0f)]));
        }
    }
    let connect_param = if connect {
        "&add-connector-link=true"
    } else {
        ""
    };
    let url = format!(
        "{install_url}#settings/Connectors?connector={encoded_id}{connect_param}&product-sku=CODEX&referrer=codex"
    );
    (url.len() <= 8 * 1024).then_some(url)
}

fn plugin_logo_format(content_type: Option<&str>, bytes: &[u8]) -> Option<ImageFormat> {
    let declared = content_type.and_then(ImageFormat::from_mime_type);
    declared.or_else(|| {
        if bytes.starts_with(b"\x89PNG\r\n\x1a\n") {
            Some(ImageFormat::Png)
        } else if bytes.starts_with(b"\xff\xd8\xff") {
            Some(ImageFormat::Jpeg)
        } else if bytes.starts_with(b"RIFF") && bytes.get(8..12) == Some(b"WEBP") {
            Some(ImageFormat::Webp)
        } else if bytes.starts_with(b"BM") {
            Some(ImageFormat::Bmp)
        } else if bytes.starts_with(b"II*\0") || bytes.starts_with(b"MM\0*") {
            Some(ImageFormat::Tiff)
        } else {
            None
        }
    })
}

fn validate_plugin_logo_dimensions(
    format: ImageFormat,
    bytes: &[u8],
) -> Result<(), ImageCacheError> {
    let raster_format = match format {
        ImageFormat::Png => image::ImageFormat::Png,
        ImageFormat::Jpeg => image::ImageFormat::Jpeg,
        ImageFormat::Webp => {
            if bytes
                .windows(4)
                .any(|chunk| chunk == b"ANIM" || chunk == b"ANMF")
            {
                return Err(plugin_logo_error("animated plugin logos are unsupported"));
            }
            image::ImageFormat::WebP
        }
        ImageFormat::Bmp => image::ImageFormat::Bmp,
        ImageFormat::Tiff => image::ImageFormat::Tiff,
        ImageFormat::Gif | ImageFormat::Svg => {
            return Err(plugin_logo_error(
                "animated or vector plugin logos are unsupported",
            ));
        }
    };
    let (width, height) = image::ImageReader::with_format(Cursor::new(bytes), raster_format)
        .into_dimensions()
        .map_err(|error| {
            plugin_logo_error(format!("plugin logo dimensions are invalid: {error}"))
        })?;
    if u64::from(width) * u64::from(height) > MAX_PLUGIN_LOGO_PIXELS {
        return Err(plugin_logo_error("plugin logo exceeds the pixel limit"));
    }
    Ok(())
}

