#[derive(Debug, Clone, PartialEq, Eq)]
struct HookSourceGroup {
    id: String,
    source: HookSource,
    cwd: Option<PathBuf>,
    plugin_id: Option<String>,
    hooks: Vec<HookCard>,
    warnings: Vec<String>,
    errors: Vec<HookIssue>,
}

fn hook_source_groups(entries: &[HookProjectEntry]) -> Vec<HookSourceGroup> {
    let mut groups = Vec::<HookSourceGroup>::new();
    let mut positions = HashMap::<String, usize>::new();

    for entry in entries {
        for hook in &entry.hooks {
            let (id, cwd, plugin_id) = match hook.source {
                HookSource::Project => (
                    format!("project:{}", entry.cwd.display()),
                    Some(entry.cwd.clone()),
                    None,
                ),
                HookSource::Plugin => (
                    format!(
                        "plugin:{}",
                        hook.plugin_id.as_deref().unwrap_or("unknown-plugin")
                    ),
                    None,
                    hook.plugin_id.clone(),
                ),
                HookSource::User => ("user".to_owned(), None, None),
                HookSource::Admin => ("admin".to_owned(), None, None),
                HookSource::SessionFlags => ("session-flags".to_owned(), None, None),
                HookSource::Unknown => ("unknown".to_owned(), None, None),
            };
            let index = ensure_hook_source_group(
                &mut groups,
                &mut positions,
                id,
                hook.source,
                cwd,
                plugin_id,
            );
            if !groups[index]
                .hooks
                .iter()
                .any(|existing| existing.key == hook.key)
            {
                groups[index].hooks.push(hook.clone());
            }
        }
        if !entry.warnings.is_empty() || !entry.errors.is_empty() {
            let index = ensure_hook_source_group(
                &mut groups,
                &mut positions,
                format!("project:{}", entry.cwd.display()),
                HookSource::Project,
                Some(entry.cwd.clone()),
                None,
            );
            for warning in &entry.warnings {
                if !groups[index].warnings.contains(warning) {
                    groups[index].warnings.push(warning.clone());
                }
            }
            for error in &entry.errors {
                if !groups[index].errors.contains(error) {
                    groups[index].errors.push(error.clone());
                }
            }
        }
    }

    for group in &mut groups {
        group.hooks.sort_by(|left, right| {
            hook_event_order(left.event_name)
                .cmp(&hook_event_order(right.event_name))
                .then_with(|| left.display_order.cmp(&right.display_order))
                .then_with(|| left.key.cmp(&right.key))
        });
    }
    groups.sort_by(|left, right| {
        hook_source_order(left.source)
            .cmp(&hook_source_order(right.source))
            .then_with(|| left.id.cmp(&right.id))
    });
    groups
}

fn ensure_hook_source_group(
    groups: &mut Vec<HookSourceGroup>,
    positions: &mut HashMap<String, usize>,
    id: String,
    source: HookSource,
    cwd: Option<PathBuf>,
    plugin_id: Option<String>,
) -> usize {
    if let Some(index) = positions.get(&id).copied() {
        return index;
    }
    let index = groups.len();
    positions.insert(id.clone(), index);
    groups.push(HookSourceGroup {
        id,
        source,
        cwd,
        plugin_id,
        hooks: Vec::new(),
        warnings: Vec::new(),
        errors: Vec::new(),
    });
    index
}

const fn hook_source_order(source: HookSource) -> u8 {
    match source {
        HookSource::User => 0,
        HookSource::Admin => 1,
        HookSource::Plugin => 2,
        HookSource::Project => 3,
        HookSource::SessionFlags => 4,
        HookSource::Unknown => 5,
    }
}

const fn hook_event_order(event: HookEventName) -> u8 {
    match event {
        HookEventName::PreToolUse => 0,
        HookEventName::PermissionRequest => 1,
        HookEventName::PostToolUse => 2,
        HookEventName::PreCompact => 3,
        HookEventName::PostCompact => 4,
        HookEventName::SessionStart => 5,
        HookEventName::SessionEnd => 6,
        HookEventName::UserPromptSubmit => 7,
        HookEventName::SubagentStart => 8,
        HookEventName::SubagentStop => 9,
        HookEventName::Stop => 10,
    }
}

const fn hook_source_category(source: HookSource) -> &'static str {
    match source {
        HookSource::User | HookSource::Admin => "From Config",
        HookSource::Plugin => "From Plugins",
        HookSource::Project => "From Projects",
        HookSource::SessionFlags | HookSource::Unknown => "Other sources",
    }
}

const fn hook_event_label(event: HookEventName) -> &'static str {
    match event {
        HookEventName::PreToolUse => "PreToolUse",
        HookEventName::PermissionRequest => "PermissionRequest",
        HookEventName::PostToolUse => "PostToolUse",
        HookEventName::PreCompact => "PreCompact",
        HookEventName::PostCompact => "PostCompact",
        HookEventName::SessionStart => "SessionStart",
        HookEventName::SessionEnd => "SessionEnd",
        HookEventName::UserPromptSubmit => "UserPromptSubmit",
        HookEventName::SubagentStart => "SubagentStart",
        HookEventName::SubagentStop => "SubagentStop",
        HookEventName::Stop => "Stop",
    }
}

const fn hook_event_description(event: HookEventName) -> &'static str {
    match event {
        HookEventName::PreToolUse => "Before a tool executes",
        HookEventName::PermissionRequest => "When permission is requested",
        HookEventName::PostToolUse => "After a tool executes",
        HookEventName::PreCompact => "Before ChatGPT compacts the conversation",
        HookEventName::PostCompact => "After ChatGPT compacts the conversation",
        HookEventName::SessionStart => "When a new session starts",
        HookEventName::SessionEnd => "When a session ends",
        HookEventName::UserPromptSubmit => "When the user submits a prompt",
        HookEventName::SubagentStart => "When a subagent starts",
        HookEventName::SubagentStop => "When a subagent stops",
        HookEventName::Stop => "Right before ChatGPT ends its turn",
    }
}

