fn browser_navigation_url(value: &str) -> Option<String> {
    let value = value.trim();
    if value.is_empty() || value.chars().any(char::is_control) {
        return None;
    }
    if value.eq_ignore_ascii_case("about:blank") {
        return Some("about:blank".to_owned());
    }
    let lower = value.to_ascii_lowercase();
    if lower.starts_with("http://") || lower.starts_with("https://") {
        return (value.len() <= codex_core::MAX_BROWSER_URL_BYTES).then(|| value.to_owned());
    }

    let authority = value
        .split(['/', '?', '#'])
        .next()
        .unwrap_or_default()
        .to_ascii_lowercase();
    let local = authority == "localhost"
        || authority.ends_with(".localhost")
        || authority.starts_with("localhost:")
        || authority == "127.0.0.1"
        || authority.starts_with("127.0.0.1:")
        || authority == "[::1]"
        || authority.starts_with("[::1]:");
    let looks_like_address = !value.chars().any(char::is_whitespace)
        && (local
            || authority.starts_with("www.")
            || authority.contains('.')
            || authority.rsplit_once(':').is_some_and(|(_, port)| {
                !port.is_empty() && port.chars().all(|ch| ch.is_ascii_digit())
            }));
    let normalized = if looks_like_address {
        format!("{}://{value}", if local { "http" } else { "https" })
    } else {
        format!(
            "https://www.google.com/search?q={}",
            browser_form_urlencode(value)
        )
    };
    (normalized.len() <= codex_core::MAX_BROWSER_URL_BYTES).then_some(normalized)
}

fn browser_form_urlencode(value: &str) -> String {
    let mut encoded = String::with_capacity(value.len());
    for byte in value.as_bytes() {
        match *byte {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'*' | b'-' | b'.' | b'_' => {
                encoded.push(char::from(*byte))
            }
            b' ' => encoded.push('+'),
            byte => {
                const HEX: &[u8; 16] = b"0123456789ABCDEF";
                encoded.push('%');
                encoded.push(char::from(HEX[(byte >> 4) as usize]));
                encoded.push(char::from(HEX[(byte & 0x0f) as usize]));
            }
        }
    }
    encoded
}

fn browser_display_url(value: &str) -> String {
    let value = value.trim();
    if value.is_empty() || value.eq_ignore_ascii_case("about:blank") {
        return String::new();
    }
    let without_scheme = value
        .strip_prefix("https://")
        .or_else(|| value.strip_prefix("http://"))
        .unwrap_or(value);
    let without_scheme = without_scheme
        .strip_prefix("www.")
        .unwrap_or(without_scheme);
    without_scheme
        .strip_suffix('/')
        .unwrap_or(without_scheme)
        .to_owned()
}

fn browser_site_permission_summary(site: &BrowserSitePermission) -> &'static str {
    if !matches!(
        (site.download, site.upload, site.full_cdp,),
        (
            BrowserPermissionValue::Default,
            BrowserPermissionValue::Default,
            BrowserPermissionValue::Default
        )
    ) {
        return "Custom";
    }
    match site.browse {
        BrowserPermissionValue::Allow => "Allow browsing",
        BrowserPermissionValue::Block => "Block browsing",
        BrowserPermissionValue::Default => "Custom",
    }
}

fn browser_surface_coordinates(
    bounds: Bounds<gpui::Pixels>,
    position: gpui::Point<gpui::Pixels>,
    frame_width: u32,
    frame_height: u32,
) -> Option<(u32, u32)> {
    if frame_width == 0 || frame_height == 0 {
        return None;
    }
    let local = bounds.localize(&position)?;
    let bounds_width = f32::from(bounds.size.width);
    let bounds_height = f32::from(bounds.size.height);
    let scale = (bounds_width / frame_width as f32).min(bounds_height / frame_height as f32);
    if !scale.is_finite() || scale <= 0.0 {
        return None;
    }
    let rendered_width = frame_width as f32 * scale;
    let rendered_height = frame_height as f32 * scale;
    let inset_x = (bounds_width - rendered_width) * 0.5;
    let inset_y = (bounds_height - rendered_height) * 0.5;
    let x = f32::from(local.x) - inset_x;
    let y = f32::from(local.y) - inset_y;
    if x < 0.0 || y < 0.0 || x >= rendered_width || y >= rendered_height {
        return None;
    }
    Some(((x / scale).floor() as u32, (y / scale).floor() as u32))
}

