#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum UserInputAutoResolutionState {
    WaitingForInactivity,
    Scheduled { deadline: Instant },
    Snoozed,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct ComposerFileQuery {
    range: Range<usize>,
    query: String,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct ComposerServiceTierCommand {
    tier_id: String,
    title: String,
    description: String,
    selected: bool,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct ComposerSkillCommand {
    path: PathBuf,
    title: String,
    description: String,
    scope: SkillScope,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum ComposerCatalogMentionKind {
    Plugin,
    DesktopApp,
    App,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct ComposerCatalogMention {
    id: String,
    title: String,
    description: String,
    kind: ComposerCatalogMentionKind,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct NavigationLocation {
    route: MainRoute,
    selected_task_id: Option<String>,
}

impl NavigationLocation {
    fn from_state(state: &AppState) -> Self {
        Self {
            route: state.route,
            selected_task_id: state.selected_task_id.clone(),
        }
    }
}

#[derive(Debug)]
struct NavigationHistory {
    entries: Vec<NavigationLocation>,
    index: usize,
}

impl NavigationHistory {
    fn new(initial: NavigationLocation) -> Self {
        Self {
            entries: vec![initial],
            index: 0,
        }
    }

    fn record(&mut self, location: NavigationLocation) {
        if self.entries.get(self.index) == Some(&location) {
            return;
        }
        self.entries.truncate(self.index.saturating_add(1));
        self.entries.push(location);
        if self.entries.len() > MAX_NAVIGATION_HISTORY_ENTRIES {
            let overflow = self.entries.len() - MAX_NAVIGATION_HISTORY_ENTRIES;
            self.entries.drain(..overflow);
        }
        self.index = self.entries.len().saturating_sub(1);
    }
}

