    fn select_composer_project(
        &mut self,
        path: PathBuf,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        self.composer_project_picker_open = false;
        let restored_draft = self.composer_project_picker_restore.take();
        let composer_value = restored_draft.clone().unwrap_or_default();
        let position = input_position_for_offset(&composer_value, composer_value.len());
        self.composer.update(cx, |input, cx| {
            input.set_value(composer_value.clone(), window, cx);
            input.set_cursor_position(position, window, cx);
            input.focus(window, cx);
        });
        if restored_draft.is_some() {
            self.dispatch(Action::ComposerChanged(composer_value), cx);
            self.dispatch(Action::SelectComposerWorkspace(path), cx);
        } else {
            self.dispatch(Action::SelectWorkspace(path), cx);
        }
        self.close_narrow_sidebar();
        self.sync_composer_placeholder(window, cx);
    }

