    fn copy_status_session_id(&mut self, session_id: String, cx: &mut Context<Self>) {
        cx.write_to_clipboard(ClipboardItem::new_string(session_id));
        self.composer_status_session_copied = true;
        cx.spawn(async move |view, cx| {
            Timer::after(Duration::from_secs(2)).await;
            let _ = view.update(cx, |this, cx| {
                this.composer_status_session_copied = false;
                cx.notify();
            });
        })
        .detach();
        cx.notify();
    }

    fn begin_message_edit(
        &mut self,
        task_id: String,
        turn_id: String,
        text: String,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        let draft = self
            .state
            .timelines
            .get(&task_id)
            .and_then(|timeline| timeline.message_edit.as_ref())
            .filter(|edit| edit.turn_id == turn_id)
            .map_or(text, |edit| edit.draft.clone());
        self.editing_message = Some((task_id, turn_id));
        self.message_edit.update(cx, |input, cx| {
            input.set_value(draft, window, cx);
            input.focus(window, cx);
        });
        cx.notify();
    }

    fn finish_message_edit(&mut self, cx: &mut Context<Self>) {
        let Some((task_id, turn_id)) = self.editing_message.clone() else {
            return;
        };
        let text = self.message_edit.read(cx).value().to_string();
        self.dispatch(
            Action::EditLastUserMessage {
                task_id,
                turn_id,
                text,
            },
            cx,
        );
    }

    fn cancel_message_edit(&mut self, cx: &mut Context<Self>) {
        let Some((task_id, turn_id)) = self.editing_message.take() else {
            return;
        };
        self.dispatch(Action::CancelLastUserMessageEdit { task_id, turn_id }, cx);
    }

