    fn toggle_composer_fast_mode(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        if !self.composer_shortcuts_available() {
            return;
        }
        let Some(next_service_tier) = self
            .state
            .composer_controls
            .selected_model
            .as_deref()
            .and_then(|model_id| {
                self.state
                    .composer_controls
                    .models
                    .iter()
                    .find(|model| model.id == model_id)
            })
            .and_then(|model| {
                model
                    .service_tiers
                    .iter()
                    .find(|tier| service_tier_label(&tier.id, &tier.name) == "Fast")
            })
            .map(|fast| {
                if self
                    .state
                    .composer_controls
                    .selected_service_tier
                    .as_deref()
                    == Some(fast.id.as_str())
                {
                    STANDARD_SERVICE_TIER_ID.to_owned()
                } else {
                    fast.id.clone()
                }
            })
        else {
            return;
        };
        self.dispatch(Action::SelectServiceTier(next_service_tier.clone()), cx);
        self.service_tier_picker.update(cx, |picker, cx| {
            picker.set_selected_value(&next_service_tier, window, cx);
        });
    }

