    fn close_narrow_sidebar(&mut self) {
        if self.shell_width_class == Some(ShellWidthClass::Narrow) {
            self.sidebar_visible = false;
        }
    }

    fn hide_right_panels_for_resize(&mut self) {
        if self.responsive_inspector_restore.is_none()
            && self.state.inspector != InspectorPane::Hidden
        {
            self.responsive_inspector_restore = Some(self.state.inspector);
            self.state.inspector = InspectorPane::Hidden;
            self.state.side_panel_full_width = false;
        }
        if !self.responsive_terminal_restore
            && self.state.terminal_dock_open
            && self.state.terminal.location == TerminalDockLocation::Right
        {
            self.responsive_terminal_restore = true;
            self.state.terminal_dock_open = false;
        }
    }

    fn restore_right_panels_after_resize(&mut self) {
        if let Some(pane) = self.responsive_inspector_restore.take()
            && self.state.inspector == InspectorPane::Hidden
        {
            self.state.inspector = pane;
        }
        if self.responsive_terminal_restore {
            self.responsive_terminal_restore = false;
            if !self.state.terminal_dock_open
                && self.state.terminal.location == TerminalDockLocation::Right
            {
                self.state.terminal_dock_open = true;
            }
        }
    }

    fn sync_responsive_shell(&mut self, current: ShellWidthClass) {
        let previous = self.shell_width_class.replace(current);
        if previous == Some(current) {
            return;
        }

        if self.sidebar_responsive {
            match (previous, current) {
                (
                    Some(ShellWidthClass::Narrow),
                    ShellWidthClass::Compact | ShellWidthClass::Wide,
                ) => {
                    self.sidebar_visible = true;
                }
                (
                    None | Some(ShellWidthClass::Compact | ShellWidthClass::Wide),
                    ShellWidthClass::Narrow,
                ) => {
                    self.sidebar_visible = false;
                }
                _ => {}
            }
        }

        match current {
            ShellWidthClass::Narrow => self.hide_right_panels_for_resize(),
            ShellWidthClass::Compact => match previous {
                None | Some(ShellWidthClass::Wide) if self.sidebar_visible => {
                    self.hide_right_panels_for_resize();
                }
                Some(ShellWidthClass::Narrow) if !self.sidebar_visible => {
                    self.restore_right_panels_after_resize();
                }
                _ => {}
            },
            ShellWidthClass::Wide => self.restore_right_panels_after_resize(),
        }
    }

