    fn enqueue_browser_download_save_request(
        &mut self,
        request: BrowserDownloadSaveRequest,
        cx: &mut Context<Self>,
    ) {
        if self
            .browser_download_save_requests
            .iter()
            .any(|pending| pending.id == request.id)
        {
            return;
        }
        if self.browser_download_save_requests.len() >= MAX_BROWSER_DOWNLOAD_SAVE_REQUESTS {
            self.dispatch(
                Action::SetBrowserDownloadDestination {
                    id: request.id,
                    path: None,
                },
                cx,
            );
            self.dispatch(
                Action::SetStatus("Too many Browser save dialogs are pending.".to_owned()),
                cx,
            );
            return;
        }
        self.browser_download_save_requests.push_back(request);
        self.prompt_for_next_browser_download_path(cx);
    }

    fn prompt_for_next_browser_download_path(&mut self, cx: &mut Context<Self>) {
        if self.browser_download_save_prompt_active {
            return;
        }
        let Some(request) = self.browser_download_save_requests.pop_front() else {
            return;
        };
        self.browser_download_save_prompt_active = true;
        let receiver = cx.prompt_for_new_path(&request.directory, Some(request.filename.as_str()));
        cx.spawn(async move |view, cx| {
            let selection = receiver.await;
            let _ = cx.update(|cx| {
                let Some(view) = view.upgrade() else {
                    return;
                };
                view.update(cx, |this, cx| {
                    this.browser_download_save_prompt_active = false;
                    match selection {
                        Ok(Ok(path)) => {
                            this.dispatch(
                                Action::SetBrowserDownloadDestination {
                                    id: request.id,
                                    path,
                                },
                                cx,
                            );
                        }
                        Ok(Err(_)) => {
                            this.dispatch(
                                Action::SetBrowserDownloadDestination {
                                    id: request.id,
                                    path: None,
                                },
                                cx,
                            );
                            this.dispatch(
                                Action::SetStatus(
                                    "Unable to choose where to save the Browser download."
                                        .to_owned(),
                                ),
                                cx,
                            );
                        }
                        Err(_) => {
                            this.dispatch(
                                Action::SetBrowserDownloadDestination {
                                    id: request.id,
                                    path: None,
                                },
                                cx,
                            );
                        }
                    }
                    this.prompt_for_next_browser_download_path(cx);
                });
            });
        })
        .detach();
    }

