    fn open_process_manager(&mut self, cx: &mut Context<Self>) {
        if self.state.selected_task_id.is_none() {
            self.dispatch(
                Action::SetStatus("Open a chat before opening Process Manager.".to_owned()),
                cx,
            );
            return;
        }
        self.workspace_modal = Some(WorkspaceModal::ProcessManager);
        cx.notify();
        self.dispatch(Action::RefreshBackgroundTerminals, cx);
        self.start_process_manager_auto_refresh(cx);
    }

    fn start_process_manager_auto_refresh(&mut self, cx: &mut Context<Self>) {
        self.process_manager_refresh_generation =
            self.process_manager_refresh_generation.wrapping_add(1);
        let generation = self.process_manager_refresh_generation;
        cx.spawn(async move |view, cx| {
            loop {
                Timer::after(PROCESS_MANAGER_REFRESH_INTERVAL).await;
                let keep_running = cx
                    .update(|cx| {
                        let Some(view) = view.upgrade() else {
                            return false;
                        };
                        let mut keep_running = false;
                        view.update(cx, |this, cx| {
                            let is_open = matches!(
                                this.workspace_modal,
                                Some(WorkspaceModal::ProcessManager)
                            );
                            if this.process_manager_refresh_generation != generation || !is_open {
                                return;
                            }
                            keep_running = true;
                            if process_manager_auto_refresh_allowed(
                                is_open,
                                &this.state.process_manager,
                            ) {
                                this.dispatch(Action::RefreshBackgroundTerminals, cx);
                            }
                        });
                        keep_running
                    })
                    .unwrap_or(false);
                if !keep_running {
                    break;
                }
            }
        })
        .detach();
    }

    fn copy_task_as_markdown(&mut self, task_id: String, cx: &mut Context<Self>) {
        if self.state.selected_task_id.as_deref() != Some(task_id.as_str()) {
            self.dispatch(
                Action::SetStatus("Failed to copy conversation as Markdown".to_owned()),
                cx,
            );
            return;
        }
        self.pending_conversation_markdown_copy = Some(PendingConversationMarkdownCopy {
            task_id: task_id.clone(),
            requested_cursors: HashSet::new(),
        });
        if self
            .state
            .timelines
            .get(&task_id)
            .is_none_or(|timeline| matches!(timeline.status, LoadStatus::Idle | LoadStatus::Failed))
        {
            self.dispatch(Action::SelectTask(task_id), cx);
        }
        self.continue_conversation_markdown_copy(cx);
    }

    fn copy_selected_conversation_as_markdown(&mut self, cx: &mut Context<Self>) {
        let Some(task_id) = self.state.selected_task_id.clone() else {
            return;
        };
        self.copy_task_as_markdown(task_id, cx);
    }

    fn copy_selected_task_value(&mut self, kind: TaskCopyKind, cx: &mut Context<Self>) {
        let Some(value) = selected_task_copy_value(&self.state, kind) else {
            return;
        };
        cx.write_to_clipboard(ClipboardItem::new_string(value));
        if kind == TaskCopyKind::WorkingDirectory {
            self.dispatch(Action::SetStatus("Copied working directory".to_owned()), cx);
        }
    }

    fn continue_conversation_markdown_copy(&mut self, cx: &mut Context<Self>) {
        let Some(task_id) = self
            .pending_conversation_markdown_copy
            .as_ref()
            .map(|pending| pending.task_id.clone())
        else {
            return;
        };
        if self.state.selected_task_id.as_deref() != Some(task_id.as_str()) {
            self.fail_conversation_markdown_copy(cx);
            return;
        }
        let Some(timeline) = self.state.timelines.get(&task_id) else {
            return;
        };
        match timeline.status {
            LoadStatus::Idle | LoadStatus::Loading => return,
            LoadStatus::Failed => {
                self.fail_conversation_markdown_copy(cx);
                return;
            }
            LoadStatus::Ready => {}
        }

        let mut history_truncated = false;
        if let Some(cursor) = timeline.next_cursor.clone() {
            let can_request_more = timeline.items.len() < MAX_TIMELINE_ITEMS
                && matches!(self.state.connection, ConnectionStatus::Online)
                && self
                    .pending_conversation_markdown_copy
                    .as_mut()
                    .is_some_and(|pending| {
                        pending.requested_cursors.len() < MAX_CONVERSATION_MARKDOWN_HISTORY_PAGES
                            && pending.requested_cursors.insert(cursor)
                    });
            if can_request_more {
                self.dispatch(Action::LoadMoreTimeline, cx);
                return;
            }
            history_truncated = true;
        }

        let markdown = self
            .state
            .tasks
            .iter()
            .find(|task| task.id == task_id)
            .and_then(|task| {
                render_conversation_markdown(&task.title, &timeline.items, history_truncated)
            });
        self.pending_conversation_markdown_copy = None;
        if let Some(markdown) = markdown {
            cx.write_to_clipboard(ClipboardItem::new_string(markdown));
            self.dispatch(
                Action::SetStatus("Copied conversation as Markdown".to_owned()),
                cx,
            );
        }
    }

    fn fail_conversation_markdown_copy(&mut self, cx: &mut Context<Self>) {
        self.pending_conversation_markdown_copy = None;
        self.dispatch(
            Action::SetStatus("Failed to copy conversation as Markdown".to_owned()),
            cx,
        );
    }

    fn toggle_keyboard_shortcuts(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        if matches!(
            self.workspace_modal,
            Some(WorkspaceModal::KeyboardShortcuts)
        ) {
            self.close_workspace_modal(cx);
            return;
        }
        if self.workspace_modal.is_some() {
            return;
        }
        if self.command_palette.is_some() {
            self.close_command_palette(cx);
        }
        self.keyboard_shortcuts_search.update(cx, |input, cx| {
            input.set_value("", window, cx);
        });
        self.workspace_modal = Some(WorkspaceModal::KeyboardShortcuts);
        cx.notify();
        let search = self.keyboard_shortcuts_search.clone();
        window.defer(cx, move |window, cx| {
            search.update(cx, |input, cx| input.focus(window, cx));
        });
    }

    fn handle_keyboard_shortcuts_escape(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        cx.stop_propagation();
        if self.keyboard_shortcuts_search.read(cx).value().is_empty() {
            self.close_workspace_modal(cx);
        } else {
            self.keyboard_shortcuts_search.update(cx, |input, cx| {
                input.set_value("", window, cx);
                input.focus(window, cx);
            });
        }
    }

    fn effective_keyboard_shortcuts(&self, item: &KeyboardShortcutItem) -> Vec<String> {
        self.state
            .keyboard_shortcut_preferences
            .bindings_for(item.id)
            .map(<[String]>::to_vec)
            .unwrap_or_else(|| {
                item.shortcuts
                    .iter()
                    .map(|shortcut| keyboard_shortcut_label(shortcut))
                    .collect()
            })
    }

    fn begin_keyboard_shortcut_capture(
        &mut self,
        command_id: &'static str,
        mode: KeyboardShortcutCaptureMode,
        previous_accelerator: Option<String>,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        self.keyboard_shortcut_capture = Some(KeyboardShortcutCapture {
            command_id,
            mode,
            previous_accelerator,
            candidate: None,
            conflicting_command_title: None,
        });
        cx.notify();
        let focus = self.keyboard_shortcut_capture_focus.clone();
        window.defer(cx, move |window, _| {
            focus.focus(window);
        });
    }

    fn cancel_keyboard_shortcut_capture(&mut self, cx: &mut Context<Self>) {
        if self.keyboard_shortcut_capture.take().is_some() {
            cx.notify();
        }
    }

    fn apply_keyboard_shortcut_capture(
        &mut self,
        capture: KeyboardShortcutCapture,
        accelerator: String,
        cx: &mut Context<Self>,
    ) {
        let Some(item) = ACTIVE_KEYBOARD_SHORTCUTS
            .iter()
            .find(|item| item.id == capture.command_id)
        else {
            self.keyboard_shortcut_capture = None;
            return;
        };
        let mut bindings = self.effective_keyboard_shortcuts(item);
        match capture.mode {
            KeyboardShortcutCaptureMode::Set => {
                bindings.clear();
                bindings.push(accelerator);
            }
            KeyboardShortcutCaptureMode::Append => {
                if bindings.len() < MAX_KEYBOARD_SHORTCUTS_PER_COMMAND
                    && !bindings.iter().any(|binding| {
                        normalized_accelerator(binding) == normalized_accelerator(&accelerator)
                    })
                {
                    bindings.push(accelerator);
                }
            }
            KeyboardShortcutCaptureMode::Replace => {
                let previous = capture.previous_accelerator.as_deref();
                if let Some(index) = previous.and_then(|previous| {
                    bindings.iter().position(|binding| {
                        normalized_accelerator(binding) == normalized_accelerator(previous)
                    })
                }) {
                    bindings[index] = accelerator;
                } else if let Some(first) = bindings.first_mut() {
                    *first = accelerator;
                } else {
                    bindings.push(accelerator);
                }
            }
        }
        let mut preferences = self.state.keyboard_shortcut_preferences.clone();
        preferences
            .overrides
            .insert(capture.command_id.to_owned(), bindings);
        self.keyboard_shortcut_capture = None;
        self.keyboard_shortcut_errors.remove(capture.command_id);
        self.dispatch(
            Action::SetKeyboardShortcutPreferences {
                preferences,
                target: KeyboardShortcutUpdateTarget::Command(capture.command_id.to_owned()),
            },
            cx,
        );
    }

    fn clear_keyboard_shortcut(
        &mut self,
        command_id: &'static str,
        accelerator: &str,
        cx: &mut Context<Self>,
    ) {
        let Some(item) = ACTIVE_KEYBOARD_SHORTCUTS
            .iter()
            .find(|item| item.id == command_id)
        else {
            return;
        };
        let target = normalized_accelerator(accelerator);
        let bindings = self
            .effective_keyboard_shortcuts(item)
            .into_iter()
            .filter(|binding| normalized_accelerator(binding) != target)
            .collect();
        let mut preferences = self.state.keyboard_shortcut_preferences.clone();
        preferences
            .overrides
            .insert(command_id.to_owned(), bindings);
        self.keyboard_shortcut_errors.remove(command_id);
        self.dispatch(
            Action::SetKeyboardShortcutPreferences {
                preferences,
                target: KeyboardShortcutUpdateTarget::Command(command_id.to_owned()),
            },
            cx,
        );
    }

    fn reset_keyboard_shortcut(&mut self, command_id: &'static str, cx: &mut Context<Self>) {
        let mut preferences = self.state.keyboard_shortcut_preferences.clone();
        if preferences.overrides.remove(command_id).is_some() {
            self.keyboard_shortcut_capture = None;
            self.keyboard_shortcut_errors.remove(command_id);
            self.dispatch(
                Action::SetKeyboardShortcutPreferences {
                    preferences,
                    target: KeyboardShortcutUpdateTarget::Command(command_id.to_owned()),
                },
                cx,
            );
        }
    }

    fn reset_all_keyboard_shortcuts(&mut self, cx: &mut Context<Self>) {
        self.keyboard_shortcut_capture = None;
        self.keyboard_shortcut_search_by_keys = false;
        self.keyboard_shortcut_reset_all_error = None;
        self.keyboard_shortcut_reset_all_pending = true;
        self.dispatch(
            Action::SetKeyboardShortcutPreferences {
                preferences: KeyboardShortcutPreferences::default(),
                target: KeyboardShortcutUpdateTarget::ResetAll,
            },
            cx,
        );
    }

    fn keyboard_shortcut_conflict(
        &self,
        command_id: &str,
        previous_accelerator: Option<&str>,
        candidate: &str,
    ) -> Option<&'static str> {
        for item in ACTIVE_KEYBOARD_SHORTCUTS {
            for binding in self.effective_keyboard_shortcuts(item) {
                if item.id == command_id
                    && previous_accelerator.is_some_and(|previous| {
                        normalized_accelerator(previous) == normalized_accelerator(&binding)
                    })
                {
                    continue;
                }
                if accelerators_conflict(&binding, candidate) {
                    return Some(item.title);
                }
            }
        }
        FIXED_KEYBOARD_SHORTCUTS
            .iter()
            .find_map(|(title, accelerator)| {
                accelerators_conflict(accelerator, candidate).then_some(*title)
            })
    }

    fn schedule_pending_keyboard_shortcut(&mut self, accelerator: String, cx: &mut Context<Self>) {
        self.keyboard_shortcut_sequence_generation =
            self.keyboard_shortcut_sequence_generation.wrapping_add(1);
        let generation = self.keyboard_shortcut_sequence_generation;
        self.pending_keyboard_shortcut = Some(PendingKeyboardShortcut {
            accelerator,
            generation,
        });
        cx.spawn(async move |view, cx| {
            Timer::after(KEYBOARD_SHORTCUT_SEQUENCE_TIMEOUT).await;
            let _ = view.update(cx, |this, _| {
                if this
                    .pending_keyboard_shortcut
                    .as_ref()
                    .is_some_and(|pending| pending.generation == generation)
                {
                    this.pending_keyboard_shortcut = None;
                }
            });
        })
        .detach();
    }

    fn handle_keyboard_shortcut_keystroke(
        &mut self,
        keystroke: &gpui::Keystroke,
        context_stack: &[KeyContext],
        window: &mut Window,
        cx: &mut Context<Self>,
    ) -> bool {
        if self.keyboard_shortcut_capture.is_some() {
            if keystroke.key.eq_ignore_ascii_case("escape") {
                self.cancel_keyboard_shortcut_capture(cx);
                return true;
            }
            let Some(accelerator) = accelerator_from_keystroke(keystroke) else {
                return false;
            };
            let Some(capture) = self.keyboard_shortcut_capture.clone() else {
                return true;
            };
            if let Some(title) = self.keyboard_shortcut_conflict(
                capture.command_id,
                capture.previous_accelerator.as_deref(),
                &accelerator,
            ) {
                if let Some(active) = self.keyboard_shortcut_capture.as_mut() {
                    active.candidate = Some(accelerator);
                    active.conflicting_command_title = Some(title.to_owned());
                }
                cx.notify();
            } else {
                self.apply_keyboard_shortcut_capture(capture, accelerator, cx);
            }
            return true;
        }

        if self.state.route == MainRoute::Settings
            && self.settings_section == SettingsSection::Git
            && keystroke.key.eq_ignore_ascii_case("s")
            && keystroke.modifiers.secondary()
            && !keystroke.modifiers.alt
            && !keystroke.modifiers.shift
        {
            return self.save_dirty_git_settings(window, cx);
        }

        if self.state.route == MainRoute::Settings
            && self.settings_section == SettingsSection::KeyboardShortcuts
            && self.keyboard_shortcut_search_by_keys
        {
            if keystroke.key.eq_ignore_ascii_case("escape") {
                self.keyboard_shortcut_search_by_keys = false;
                self.keyboard_shortcut_settings_search
                    .update(cx, |input, cx| {
                        input.set_value("", window, cx);
                        input.set_placeholder("Search shortcuts", window, cx);
                        input.focus(window, cx);
                    });
                cx.notify();
                return true;
            }
            let Some(accelerator) = accelerator_from_keystroke(keystroke) else {
                return false;
            };
            self.keyboard_shortcut_settings_search
                .update(cx, |input, cx| {
                    input.set_value(accelerator, window, cx);
                });
            return true;
        }

        let Some(accelerator) = accelerator_from_keystroke(keystroke) else {
            return false;
        };
        let accelerator = if let Some(pending) = self.pending_keyboard_shortcut.take() {
            format!("{} {accelerator}", pending.accelerator)
        } else {
            accelerator
        };
        let exact_command = ACTIVE_KEYBOARD_SHORTCUTS.iter().find_map(|item| {
            if !self.keyboard_shortcut_command_enabled(item.id, context_stack) {
                return None;
            }
            self.effective_keyboard_shortcuts(item)
                .iter()
                .any(|binding| {
                    normalized_accelerator(binding) == normalized_accelerator(&accelerator)
                })
                .then_some(item.id)
        });
        let is_prefix = ACTIVE_KEYBOARD_SHORTCUTS.iter().any(|item| {
            self.keyboard_shortcut_command_enabled(item.id, context_stack)
                && self
                    .effective_keyboard_shortcuts(item)
                    .iter()
                    .any(|binding| accelerator_is_strict_prefix(&accelerator, binding))
        });
        if is_prefix {
            self.schedule_pending_keyboard_shortcut(accelerator, cx);
            return true;
        }
        if let Some(command_id) = exact_command {
            self.execute_keyboard_shortcut_command(command_id, window, cx);
            return true;
        }
        ACTIVE_KEYBOARD_SHORTCUTS.iter().any(|item| {
            self.keyboard_shortcut_command_enabled(item.id, context_stack)
                && item.shortcuts.iter().any(|binding| {
                    normalized_accelerator(binding) == normalized_accelerator(&accelerator)
                        || accelerator_is_strict_prefix(&accelerator, binding)
                })
        })
    }

    fn keyboard_shortcut_command_enabled(
        &self,
        command_id: &str,
        context_stack: &[KeyContext],
    ) -> bool {
        match command_id {
            "approval.approve" | "approval.decline" => {
                self.approval_shortcuts_available()
                    && !approval_keyboard_context_is_blocking(context_stack)
            }
            "copyDeeplink" => {
                selected_task_copy_value(&self.state, TaskCopyKind::Deeplink).is_some()
            }
            "copySessionId" => {
                selected_task_copy_value(&self.state, TaskCopyKind::SessionId).is_some()
            }
            "copyWorkingDirectory" => {
                selected_task_copy_value(&self.state, TaskCopyKind::WorkingDirectory).is_some()
            }
            "forkThread" => self.state.selected_task_id.is_some(),
            "openReviewTab" | "toggleReviewTab" => {
                self.state.route == MainRoute::Tasks
                    && self.state.selected_task_id.is_some()
                    && self.state.git.repository_root.is_some()
            }
            "openBrowserTab" | "toggleBrowserPanel" => {
                self.state.route == MainRoute::Tasks && self.state.selected_task_id.is_some()
            }
            "focusBrowserAddressBar" => {
                self.state.route == MainRoute::Tasks
                    && self.state.selected_task_id.is_some()
                    && self.state.inspector == InspectorPane::Browser
            }
            "navigateBrowserBack" => {
                self.state.route == MainRoute::Tasks
                    && self.state.inspector == InspectorPane::Browser
                    && self
                        .state
                        .selected_task_id
                        .as_deref()
                        .and_then(|task_id| self.state.browser.get(task_id))
                        .and_then(|browser| {
                            browser.active_tab_id.as_deref().and_then(|active_id| {
                                browser.tabs.iter().find(|tab| tab.id == active_id)
                            })
                        })
                        .is_some_and(|tab| tab.can_go_back)
            }
            "navigateBrowserForward" => {
                self.state.route == MainRoute::Tasks
                    && self.state.inspector == InspectorPane::Browser
                    && self
                        .state
                        .selected_task_id
                        .as_deref()
                        .and_then(|task_id| self.state.browser.get(task_id))
                        .and_then(|browser| {
                            browser.active_tab_id.as_deref().and_then(|active_id| {
                                browser.tabs.iter().find(|tab| tab.id == active_id)
                            })
                        })
                        .is_some_and(|tab| tab.can_go_forward)
            }
            "toggleMaximizeSidePanel" => {
                self.state.route == MainRoute::Tasks
                    && self.state.selected_task_id.is_some()
                    && !matches!(
                        self.state.inspector,
                        InspectorPane::Hidden | InspectorPane::Terminal
                    )
            }
            "logOut" => {
                self.state.account.profile.is_some()
                    && self.state.account.auth_operation == AccountAuthOperation::Idle
            }
            "composer.openProjectPicker" => {
                self.composer_shortcuts_available() && self.state.selected_task_id.is_none()
            }
            _ => true,
        }
    }

    fn approval_shortcuts_available(&self) -> bool {
        self.state.route == MainRoute::Tasks
            && self.workspace_modal.is_none()
            && self.command_palette.is_none()
            && selected_approval_request(&self.state).is_some()
    }

    fn resolve_active_approval(&mut self, decision: ApprovalDecision, cx: &mut Context<Self>) {
        let Some(request_id) =
            selected_approval_request(&self.state).map(|approval| approval.request_id.clone())
        else {
            return;
        };
        self.dispatch(
            Action::ResolveApproval {
                request_id,
                decision,
            },
            cx,
        );
    }

    fn execute_keyboard_shortcut_command(
        &mut self,
        command_id: &str,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        match command_id {
            "newTask" => self.begin_new_chat(window, cx),
            "newProjectlessTask" => self.begin_projectless_chat(window, cx),
            "archiveThread" => self.archive_selected_chat(cx),
            "toggleThreadPin" => self.toggle_selected_chat_pin(cx),
            "copyConversationMarkdown" => self.copy_selected_conversation_as_markdown(cx),
            "copyDeeplink" => self.copy_selected_task_value(TaskCopyKind::Deeplink, cx),
            "copySessionId" => self.copy_selected_task_value(TaskCopyKind::SessionId, cx),
            "copyWorkingDirectory" => {
                self.copy_selected_task_value(TaskCopyKind::WorkingDirectory, cx);
            }
            "forkThread" => self.dispatch(Action::ForkSelectedTask, cx),
            "searchChats" => {
                if self.thread_find_open {
                    self.navigate_thread_find(true, cx);
                } else {
                    self.open_command_palette(PaletteMode::Chats, window, cx);
                }
            }
            "navigateBack" => self.navigate_history(false, cx),
            "navigateForward" => self.navigate_history(true, cx),
            "previousThread" => self.navigate_adjacent_chat(false, cx),
            "nextThread" => self.navigate_adjacent_chat(true, cx),
            "thread1" | "thread2" | "thread3" | "thread4" | "thread5" | "thread6" | "thread7"
            | "thread8" | "thread9" => {
                if let Some(slot) = command_task_slot(command_id) {
                    self.navigate_chat_slot(slot, cx);
                }
            }
            "findInThread" => {
                if self.state.route == MainRoute::Settings {
                    self.settings_search
                        .update(cx, |input, cx| input.focus(window, cx));
                } else {
                    self.open_thread_find(window, cx);
                }
            }
            "focusBrowserAddressBar" => self.focus_browser_address(window, cx),
            "navigateBrowserBack" => self.dispatch(Action::NavigateBrowserBack, cx),
            "navigateBrowserForward" => self.dispatch(Action::NavigateBrowserForward, cx),
            "toggleSidebar" => self.toggle_sidebar(cx),
            "toggleBottomPanel" => self.dispatch(Action::ToggleBottomPanel, cx),
            "openReviewTab" => {
                if self.keyboard_shortcut_command_enabled("openReviewTab", &[]) {
                    self.dispatch(Action::ShowInspector(InspectorPane::Changes), cx);
                }
            }
            "toggleReviewTab" => self.dispatch(Action::ToggleReviewTab, cx),
            "toggleSidePanel" => self.dispatch(Action::ToggleReviewPanel, cx),
            "toggleMaximizeSidePanel" => {
                self.dispatch(Action::ToggleMaximizeSidePanel, cx);
            }
            "toggleTerminal" => {
                if self.state.selected_task_id.is_some() {
                    self.dispatch(Action::ToggleTerminalDock, cx);
                }
            }
            "openBrowserTab" => self.dispatch(Action::OpenBrowserTab, cx),
            "toggleBrowserPanel" => self.dispatch(Action::ToggleBrowserPanel, cx),
            "openFolder" => self.prompt_for_workspace(cx),
            "forceReloadSkills" => self.dispatch(Action::RefreshSkills, cx),
            "openSkills" => self.open_skills(window, cx),
            "keyboardShortcuts" => {
                self.open_settings_section(SettingsSection::KeyboardShortcuts, cx);
            }
            "mcpSettings" => self.open_mcp_settings(window, cx),
            "personalitySettings" => {
                self.open_settings_section(SettingsSection::Personalization, cx);
            }
            "settings" => self.open_settings_section(SettingsSection::General, cx),
            "openProcessManager" => self.open_process_manager(cx),
            "logOut" => self.confirm_account_logout(cx),
            "feedback" => self.open_feedback_modal(window, cx),
            "showKeyboardShortcuts" => self.toggle_keyboard_shortcuts(window, cx),
            "openCommandMenu" => {
                self.open_command_palette(PaletteMode::Unified, window, cx);
            }
            "searchFiles" => self.open_command_palette(PaletteMode::Files, window, cx),
            "composer.openModelPicker" => self.open_model_picker(window, cx),
            "composer.openProjectPicker" => {
                self.open_composer_project_picker_shortcut(window, cx);
            }
            "composer.submit" => self.submit_composer_shortcut(window, cx),
            "composer.addPhotos" => self.add_composer_photos_shortcut(cx),
            "composer.addFiles" => self.attach_composer_files_shortcut(cx),
            "composer.toggleFastMode" => self.toggle_composer_fast_mode(window, cx),
            "composer.increaseReasoningEffort" => {
                self.change_composer_reasoning_effort(ReasoningEffortStep::Increase, window, cx);
            }
            "composer.decreaseReasoningEffort" => {
                self.change_composer_reasoning_effort(ReasoningEffortStep::Decrease, window, cx);
            }
            "composer.cycleReasoningEffort" => {
                self.change_composer_reasoning_effort(ReasoningEffortStep::Cycle, window, cx);
            }
            "composer.togglePlanMode" => self.toggle_composer_plan_mode(window, cx),
            "approval.approve" => self.resolve_active_approval(ApprovalDecision::Accept, cx),
            "approval.decline" => self.resolve_active_approval(ApprovalDecision::Decline, cx),
            "git.commit" => self.open_commit_modal(window, cx),
            "git.createPullRequest" => {
                self.open_create_pull_request_modal(false, window, cx);
            }
            "git.createDraftPullRequest" => {
                self.open_create_pull_request_modal(true, window, cx);
            }
            "git.createBranch" => self.open_create_branch_modal(window, cx),
            "git.mergePullRequest" => self.open_linked_pull_request_merge(window, cx),
            "git.openPullRequest" => self.open_linked_pull_request(cx),
            "renameThread" => self.rename_selected_chat(window, cx),
            "closeWindow" | "quit" => window.remove_window(),
            "toggleFullScreen" => window.toggle_fullscreen(),
            _ => {}
        }
    }

    fn open_commit_modal(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        if self.state.git.pending_pull_request.is_some() {
            return;
        }
        if self.state.git.repository_root.is_none() {
            self.dispatch(
                Action::SetStatus("Select a task backed by a Git repository.".to_owned()),
                cx,
            );
            return;
        }
        if self.state.git.changed_files == 0 && self.state.git.ahead == 0 {
            self.dispatch(
                Action::SetStatus("No changes or commits to push.".to_owned()),
                cx,
            );
            return;
        }
        self.commit_message.update(cx, |input, cx| {
            input.set_value("", window, cx);
        });
        self.dispatch(Action::ClearGitCommitError, cx);
        self.workspace_modal = Some(WorkspaceModal::Commit);
        cx.notify();
        if self.state.git.changed_files > 0 {
            let commit_message = self.commit_message.clone();
            window.defer(cx, move |window, cx| {
                commit_message.update(cx, |input, cx| input.focus(window, cx));
            });
        }
    }

    fn submit_git_action(&mut self, next_step: GitCommitNextStep, cx: &mut Context<Self>) {
        if self.state.git.pending_commit.is_some() {
            return;
        }
        let message = self.commit_message.read(cx).value().to_string();
        self.dispatch(
            Action::CommitGit {
                message,
                include_unstaged: self.state.git_include_unstaged,
                next_step,
            },
            cx,
        );
    }

    fn open_pull_request_action(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        if self.state.git.pull_request.is_some() {
            self.open_linked_pull_request(cx);
            return;
        }
        self.open_create_pull_request_modal(false, window, cx);
    }

    fn open_linked_pull_request(&mut self, cx: &mut Context<Self>) {
        let Some(url) = self
            .state
            .git
            .pull_request
            .as_ref()
            .map(|pull_request| pull_request.url.clone())
        else {
            return;
        };
        if is_supported_external_url(&url) {
            cx.open_url(&url);
        } else {
            self.dispatch(
                Action::SetStatus("Pull request URL is unsupported.".to_owned()),
                cx,
            );
        }
    }

    fn open_linked_pull_request_merge(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        if !linked_pull_request_merge_command_enabled(&self.state) {
            return;
        }
        self.open_pull_request_action_modal(PullRequestActionKind::Merge, window, cx);
    }

    fn open_create_pull_request_modal(
        &mut self,
        default_to_draft: bool,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        if self.state.git.repository_root.is_none() {
            self.dispatch(Action::SetStatus("No Git repository found.".to_owned()), cx);
            return;
        }
        let Some(branch) = self.state.git.branch.as_deref() else {
            self.dispatch(
                Action::SetStatus("Git has no current branch.".to_owned()),
                cx,
            );
            return;
        };
        let Some(base_branch) = self.state.git.default_branch.as_deref() else {
            self.dispatch(
                Action::SetStatus("Default branch is unavailable.".to_owned()),
                cx,
            );
            return;
        };
        if branch == base_branch {
            self.dispatch(
                Action::SetStatus("Switch to a branch before creating a pull request.".to_owned()),
                cx,
            );
            return;
        }
        self.pull_request_title.update(cx, |input, cx| {
            input.set_value("", window, cx);
        });
        self.pull_request_description.update(cx, |input, cx| {
            input.set_value("", window, cx);
        });
        self.pull_request_include_local_changes = true;
        self.pull_request_default_to_draft =
            default_to_draft || self.state.git_preferences.create_pull_request_as_draft;
        self.dispatch(Action::ClearGitPullRequestError, cx);
        self.workspace_modal = Some(WorkspaceModal::CreatePullRequest);
        cx.notify();
        let title = self.pull_request_title.clone();
        window.defer(cx, move |window, cx| {
            title.update(cx, |input, cx| input.focus(window, cx));
        });
    }

    fn submit_create_pull_request(
        &mut self,
        is_draft: bool,
        open_in_browser: bool,
        cx: &mut Context<Self>,
    ) {
        if self.state.git.pending_pull_request.is_some() {
            return;
        }
        self.dispatch(
            Action::CreateGitPullRequest {
                title: self.pull_request_title.read(cx).value().to_string(),
                body: self.pull_request_description.read(cx).value().to_string(),
                include_local_changes: self.pull_request_include_local_changes,
                is_draft,
                open_in_browser,
            },
            cx,
        );
        if self.state.git.pending_pull_request.is_some() {
            self.workspace_modal = None;
            cx.notify();
        }
    }

    fn open_pull_request_edit(
        &mut self,
        kind: PullRequestEditKind,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        let Some(detail) = self.state.pull_requests.detail.as_ref() else {
            return;
        };
        if self.state.pull_requests.pending_mutation.is_some()
            || !detail.summary.is_author
            || detail.summary.state != PullRequestState::Open
        {
            return;
        }
        let (input, value, placeholder) = match kind {
            PullRequestEditKind::Title => (
                self.pull_request_title.clone(),
                detail.summary.title.clone(),
                "Pull request title",
            ),
            PullRequestEditKind::Description => (
                self.pull_request_description.clone(),
                detail.body.clone(),
                "Pull request description",
            ),
        };
        input.update(cx, |input, cx| {
            input.set_value(value, window, cx);
            input.set_placeholder(placeholder, window, cx);
        });
        self.dispatch(Action::ClearPullRequestMutationError, cx);
        self.workspace_modal = Some(WorkspaceModal::EditPullRequest(kind));
        cx.notify();
        window.defer(cx, move |window, cx| {
            input.update(cx, |input, cx| input.focus(window, cx));
        });
    }

    fn submit_pull_request_edit(&mut self, kind: PullRequestEditKind, cx: &mut Context<Self>) {
        if self.state.pull_requests.pending_mutation.is_some() {
            return;
        }
        let mutation = match kind {
            PullRequestEditKind::Title => PullRequestMutation::EditTitle {
                title: self.pull_request_title.read(cx).value().to_string(),
            },
            PullRequestEditKind::Description => PullRequestMutation::EditDescription {
                body: self.pull_request_description.read(cx).value().to_string(),
            },
        };
        self.dispatch(Action::SubmitPullRequestMutation(mutation), cx);
        if self.state.pull_requests.pending_mutation.is_some() {
            self.workspace_modal = None;
            cx.notify();
        }
    }

    fn set_pull_request_review_state(
        &mut self,
        state: PullRequestReviewState,
        cx: &mut Context<Self>,
    ) {
        if self.state.pull_requests.pending_mutation.is_some() {
            return;
        }
        self.dispatch(
            Action::SubmitPullRequestMutation(PullRequestMutation::SetReviewState { state }),
            cx,
        );
    }

    fn open_pull_request_action_modal(
        &mut self,
        kind: PullRequestActionKind,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        if self.state.pull_requests.pending_mutation.is_some()
            || self.state.pull_requests.detail.is_none()
        {
            return;
        }
        let placeholder = match kind {
            PullRequestActionKind::Comment => "Write a pull request comment",
            PullRequestActionKind::Approve => "Approval note (optional)",
            PullRequestActionKind::ReviewComment => "Write a review comment",
            PullRequestActionKind::RequestChanges => "Explain the requested changes",
            PullRequestActionKind::Merge => "",
        };
        self.pull_request_action_body.update(cx, |input, cx| {
            input.set_value("", window, cx);
            input.set_placeholder(placeholder, window, cx);
        });
        self.dispatch(Action::ClearPullRequestMutationError, cx);
        self.workspace_modal = Some(WorkspaceModal::PullRequestAction(kind));
        cx.notify();
        if kind != PullRequestActionKind::Merge {
            let input = self.pull_request_action_body.clone();
            window.defer(cx, move |window, cx| {
                input.update(cx, |input, cx| input.focus(window, cx));
            });
        }
    }

    fn submit_pull_request_text_action(
        &mut self,
        kind: PullRequestActionKind,
        cx: &mut Context<Self>,
    ) {
        if self.state.pull_requests.pending_mutation.is_some() {
            return;
        }
        let body = self.pull_request_action_body.read(cx).value().to_string();
        let mutation = match kind {
            PullRequestActionKind::Comment => PullRequestMutation::Comment { body },
            PullRequestActionKind::Approve => PullRequestMutation::Review {
                event: PullRequestReviewEvent::Approve,
                body,
            },
            PullRequestActionKind::ReviewComment => PullRequestMutation::Review {
                event: PullRequestReviewEvent::Comment,
                body,
            },
            PullRequestActionKind::RequestChanges => PullRequestMutation::Review {
                event: PullRequestReviewEvent::RequestChanges,
                body,
            },
            PullRequestActionKind::Merge => return,
        };
        self.dispatch(Action::SubmitPullRequestMutation(mutation), cx);
        if self.state.pull_requests.pending_mutation.is_some() {
            self.workspace_modal = None;
            cx.notify();
        }
    }

    fn submit_pull_request_merge(
        &mut self,
        method: PullRequestMergeMethod,
        cx: &mut Context<Self>,
    ) {
        if self.state.pull_requests.pending_mutation.is_some() {
            return;
        }
        self.dispatch(
            Action::SubmitPullRequestMutation(PullRequestMutation::Merge { method }),
            cx,
        );
        if self.state.pull_requests.pending_mutation.is_some() {
            self.workspace_modal = None;
            cx.notify();
        }
    }

    fn render_pull_request_button(
        &mut self,
        id: &'static str,
        compact: bool,
        cx: &mut Context<Self>,
    ) -> Option<AnyElement> {
        let branch = self.state.git.branch.as_deref()?;
        let base_branch = self.state.git.default_branch.as_deref()?;
        if self.state.git.repository_root.is_none() || branch == base_branch {
            return None;
        }
        let existing = self.state.git.pull_request.is_some();
        let pending = self.state.git.pending_pull_request;
        let provider_reason = match self.state.git.pull_request_provider {
            GitPullRequestProvider::Available => None,
            GitPullRequestProvider::Loading | GitPullRequestProvider::Unknown => {
                Some("Loading pull request provider…")
            }
            GitPullRequestProvider::CliMissing => Some("Install GitHub CLI (gh) to create PRs"),
            GitPullRequestProvider::AuthenticationRequired => {
                Some("Authenticate GitHub CLI: run `gh auth login`")
            }
            GitPullRequestProvider::Unavailable => Some("Pull request creation unavailable"),
        };
        let disabled = pending.is_some()
            || self.state.git.pending_commit.is_some()
            || (!existing && provider_reason.is_some());
        let label = if existing {
            "View PR"
        } else {
            git_pull_request_action_label(pending)
        };
        let tooltip = if existing {
            "Open PR in browser"
        } else if self.state.git.pending_commit.is_some() {
            "A Git workflow is already running"
        } else {
            provider_reason.unwrap_or("Create a pull request")
        };
        let button = Button::new(id)
            .label(label)
            .tooltip(tooltip)
            .loading(pending.is_some())
            .disabled(disabled)
            .on_click(cx.listener(|this, _, window, cx| {
                this.open_pull_request_action(window, cx);
            }));
        Some(if compact {
            button.xsmall().into_any_element()
        } else {
            button.small().into_any_element()
        })
    }

    fn open_create_branch_modal(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        if self.state.git.repository_root.is_none() {
            self.dispatch(
                Action::SetStatus("Select a task backed by a Git repository.".to_owned()),
                cx,
            );
            return;
        }
        let title = self
            .state
            .selected_task_id
            .as_deref()
            .and_then(|task_id| self.state.tasks.iter().find(|task| task.id == task_id))
            .map_or("new-branch", |task| task.title.as_str());
        let branch = default_branch_name(title, &self.state.git_preferences.branch_prefix);
        self.branch_name.update(cx, |input, cx| {
            input.set_value(branch, window, cx);
        });
        self.dispatch(Action::ClearGitBranchMutationError, cx);
        self.workspace_modal = Some(WorkspaceModal::CreateGitBranch);
        cx.notify();
        let branch_name = self.branch_name.clone();
        window.defer(cx, move |window, cx| {
            branch_name.update(cx, |input, cx| input.focus(window, cx));
        });
    }

    fn submit_create_branch(&mut self, cx: &mut Context<Self>) {
        let branch = self.branch_name.read(cx).value().trim().to_owned();
        self.dispatch(Action::CreateGitBranch(branch), cx);
    }

    fn close_workspace_modal(&mut self, cx: &mut Context<Self>) {
        if matches!(
            self.workspace_modal,
            Some(WorkspaceModal::PendingWorktreeFork)
        ) {
            let Some(pending) = self.state.pending_worktree_fork.as_ref() else {
                self.workspace_modal = None;
                cx.notify();
                return;
            };
            if !pending.phase.failed() {
                return;
            }
            self.dispatch(Action::DismissPendingWorktreeFork, cx);
            return;
        }
        if matches!(self.workspace_modal, Some(WorkspaceModal::Commit))
            && self.state.git.pending_commit.is_some()
        {
            return;
        }
        if matches!(
            self.workspace_modal,
            Some(WorkspaceModal::CreatePullRequest)
        ) && self.state.git.pending_pull_request.is_some()
        {
            return;
        }
        if matches!(
            self.workspace_modal,
            Some(WorkspaceModal::PullRequestAction(_) | WorkspaceModal::EditPullRequest(_))
        ) && self.state.pull_requests.pending_mutation.is_some()
        {
            return;
        }
        if matches!(self.workspace_modal, Some(WorkspaceModal::AddMarketplace))
            && self.state.marketplace.marketplace_add_pending
        {
            return;
        }
        if matches!(
            self.workspace_modal,
            Some(WorkspaceModal::RemoveMarketplace { .. })
        ) && self.state.marketplace.pending_marketplace_remove.is_some()
        {
            return;
        }
        if matches!(
            self.workspace_modal,
            Some(WorkspaceModal::EditMcpServer { .. })
        ) && self.state.marketplace.pending_mcp_key.is_some()
        {
            return;
        }
        if matches!(
            self.workspace_modal,
            Some(WorkspaceModal::RemoveComputerUseAllowedApp { .. })
        ) && self
            .state
            .computer_use_settings
            .pending_removal_app_id
            .is_some()
        {
            return;
        }
        if matches!(self.workspace_modal, Some(WorkspaceModal::LogOutAccount))
            && self.state.account.auth_operation == AccountAuthOperation::LoggingOut
        {
            return;
        }
        if matches!(self.workspace_modal, Some(WorkspaceModal::Feedback))
            && self.state.feedback.pending
        {
            return;
        }
        if matches!(self.workspace_modal, Some(WorkspaceModal::CreateGitBranch))
            && self.state.git.pending_branch_operation.is_some()
        {
            return;
        }
        if matches!(
            self.workspace_modal,
            Some(WorkspaceModal::GitBranchConflict)
        ) {
            self.dispatch(Action::DismissGitBranchConflict, cx);
        }
        if matches!(self.workspace_modal, Some(WorkspaceModal::ProcessManager)) {
            self.process_manager_refresh_generation =
                self.process_manager_refresh_generation.wrapping_add(1);
        }
        if matches!(self.workspace_modal, Some(WorkspaceModal::Feedback)) {
            self.feedback_classification = None;
            self.feedback_include_logs = true;
            self.dispatch(Action::ClearFeedbackError, cx);
        }
        self.workspace_modal = None;
        self.browser_site_error = None;
        self.appearance_import_error = None;
        self.mcp_editor_error = None;
        cx.notify();
    }

    fn confirm_account_logout(&mut self, cx: &mut Context<Self>) {
        if self.state.account.profile.is_none()
            || self.state.account.auth_operation != AccountAuthOperation::Idle
        {
            return;
        }
        self.workspace_modal = Some(WorkspaceModal::LogOutAccount);
        cx.notify();
    }

    fn confirm_remove_computer_use_allowed_app(&mut self, app_id: String, cx: &mut Context<Self>) {
        self.workspace_modal = Some(WorkspaceModal::RemoveComputerUseAllowedApp { app_id });
        cx.notify();
    }

    fn open_add_marketplace_modal(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        self.dispatch(Action::ClearMarketplaceAddError, cx);
        for input in [
            &self.marketplace_source,
            &self.marketplace_ref,
            &self.marketplace_sparse_paths,
        ] {
            input.update(cx, |input, cx| input.set_value("", window, cx));
        }
        self.workspace_modal = Some(WorkspaceModal::AddMarketplace);
        cx.notify();
        let source = self.marketplace_source.clone();
        window.defer(cx, move |window, cx| {
            source.update(cx, |input, cx| input.focus(window, cx));
        });
    }

    fn submit_marketplace(&mut self, cx: &mut Context<Self>) {
        let source = self.marketplace_source.read(cx).value().to_string();
        let ref_name = self.marketplace_ref.read(cx).value().trim().to_owned();
        let sparse_paths = self
            .marketplace_sparse_paths
            .read(cx)
            .value()
            .split(['\n', ','])
            .map(str::trim)
            .filter(|path| !path.is_empty())
            .map(str::to_owned)
            .collect::<Vec<_>>();
        self.dispatch(
            Action::AddMarketplace {
                source,
                ref_name: (!ref_name.is_empty()).then_some(ref_name),
                sparse_paths,
            },
            cx,
        );
    }

    fn open_add_mcp_server_modal(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        self.dispatch(Action::ClearMcpServerMutationError, cx);
        self.mcp_editor_error = None;
        self.set_mcp_editor_values(["", "", "", "", "", "", "", "", "", ""], window, cx);
        self.workspace_modal = Some(WorkspaceModal::EditMcpServer {
            key: None,
            transport: McpTransportKind::Stdio,
        });
        cx.notify();
        let name = self.mcp_name.clone();
        window.defer(cx, move |window, cx| {
            name.update(cx, |input, cx| input.focus(window, cx));
        });
    }

    fn open_edit_mcp_server_modal(
        &mut self,
        server: McpServerCard,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        if server.read_only {
            return;
        }
        self.dispatch(Action::ClearMcpServerMutationError, cx);
        self.mcp_editor_error = None;
        let transport = server.transport.unwrap_or(McpTransportKind::Stdio);
        let args = server.args.join("\n");
        let env = format_mcp_record(&server.env);
        let env_vars = server.env_vars.join("\n");
        let http_headers = format_mcp_record(&server.http_headers);
        let env_http_headers = format_mcp_record(&server.env_http_headers);
        self.set_mcp_editor_values(
            [
                server.name.as_str(),
                server.command.as_str(),
                args.as_str(),
                env.as_str(),
                env_vars.as_str(),
                server.cwd.as_str(),
                server.url.as_str(),
                server.bearer_token_env_var.as_str(),
                http_headers.as_str(),
                env_http_headers.as_str(),
            ],
            window,
            cx,
        );
        self.workspace_modal = Some(WorkspaceModal::EditMcpServer {
            key: Some(server.key),
            transport,
        });
        cx.notify();
    }

    fn set_mcp_editor_values(
        &self,
        values: [&str; 10],
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        for (input, value) in [
            &self.mcp_name,
            &self.mcp_command,
            &self.mcp_args,
            &self.mcp_env,
            &self.mcp_env_vars,
            &self.mcp_cwd,
            &self.mcp_url,
            &self.mcp_bearer_token_env_var,
            &self.mcp_http_headers,
            &self.mcp_env_http_headers,
        ]
        .into_iter()
        .zip(values)
        {
            let value = value.to_owned();
            input.update(cx, |input, cx| input.set_value(value, window, cx));
        }
    }

    fn set_new_mcp_transport(&mut self, transport: McpTransportKind, cx: &mut Context<Self>) {
        if matches!(
            &self.workspace_modal,
            Some(WorkspaceModal::EditMcpServer { key: None, .. })
        ) {
            self.workspace_modal = Some(WorkspaceModal::EditMcpServer {
                key: None,
                transport,
            });
            self.mcp_editor_error = None;
            cx.notify();
        }
    }

    fn submit_mcp_server(
        &mut self,
        existing_key: Option<String>,
        transport: McpTransportKind,
        cx: &mut Context<Self>,
    ) {
        let env = match parse_mcp_record(&self.mcp_env.read(cx).value(), "Environment variables") {
            Ok(env) => env,
            Err(error) => {
                self.mcp_editor_error = Some(error);
                cx.notify();
                return;
            }
        };
        let http_headers =
            match parse_mcp_record(&self.mcp_http_headers.read(cx).value(), "Headers") {
                Ok(headers) => headers,
                Err(error) => {
                    self.mcp_editor_error = Some(error);
                    cx.notify();
                    return;
                }
            };
        let env_http_headers = match parse_mcp_record(
            &self.mcp_env_http_headers.read(cx).value(),
            "Headers from environment variables",
        ) {
            Ok(headers) => headers,
            Err(error) => {
                self.mcp_editor_error = Some(error);
                cx.notify();
                return;
            }
        };
        self.mcp_editor_error = None;
        self.dispatch(
            Action::SaveMcpServer {
                existing_key,
                draft: McpServerDraft {
                    name: self.mcp_name.read(cx).value().to_string(),
                    transport,
                    command: self.mcp_command.read(cx).value().to_string(),
                    args: parse_mcp_list(&self.mcp_args.read(cx).value()),
                    env,
                    env_vars: parse_mcp_list(&self.mcp_env_vars.read(cx).value()),
                    cwd: self.mcp_cwd.read(cx).value().to_string(),
                    url: self.mcp_url.read(cx).value().to_string(),
                    bearer_token_env_var: self
                        .mcp_bearer_token_env_var
                        .read(cx)
                        .value()
                        .to_string(),
                    http_headers,
                    env_http_headers,
                },
            },
            cx,
        );
    }

