    fn composer_add_menu(
        menu: PopupMenu,
        view: WeakEntity<Self>,
        plan_mode: bool,
        goal_mode: bool,
    ) -> PopupMenu {
        let attach_view = view.clone();
        let goal_view = view.clone();
        menu.item(
            PopupMenuItem::new("Files and folders")
                .icon(IconName::FolderOpen)
                .on_click(move |_, _, cx| {
                    let _ = attach_view.update(cx, |this, cx| {
                        this.prompt_for_composer_paths(cx);
                    });
                }),
        )
        .item(
            PopupMenuItem::new("Goal")
                .icon(IconName::Asterisk)
                .checked(goal_mode)
                .on_click(move |_, window, cx| {
                    let _ = goal_view.update(cx, |this, cx| {
                        this.dispatch(Action::ToggleGoalMode, cx);
                        this.sync_composer_placeholder(window, cx);
                    });
                }),
        )
        .item(
            PopupMenuItem::new("Plan mode")
                .icon(IconName::Map)
                .checked(plan_mode)
                .on_click(move |_, window, cx| {
                    let _ = view.update(cx, |this, cx| {
                        this.dispatch(Action::TogglePlanMode, cx);
                        this.sync_composer_placeholder(window, cx);
                    });
                }),
        )
    }

    fn task_copy_menu_items(
        mut menu: PopupMenu,
        view: WeakEntity<Self>,
        task_id: String,
        cwd: PathBuf,
        include_markdown: bool,
    ) -> PopupMenu {
        let working_directory = display_path(&cwd);
        let working_directory_missing = working_directory.is_empty();
        let directory_to_copy = working_directory.clone();
        let directory_view = view.clone();
        menu = menu
            .item(
                PopupMenuItem::new("Copy working directory")
                    .icon(IconName::Copy)
                    .disabled(working_directory_missing)
                    .on_click(move |_, _, cx| {
                        cx.write_to_clipboard(ClipboardItem::new_string(directory_to_copy.clone()));
                        let _ = directory_view.update(cx, |this, cx| {
                            this.dispatch(
                                Action::SetStatus("Copied working directory".to_owned()),
                                cx,
                            );
                        });
                    }),
            )
            .item(
                PopupMenuItem::new("Copy session ID")
                    .icon(IconName::Copy)
                    .on_click({
                        let session_id = task_id.clone();
                        move |_, _, cx| {
                            cx.write_to_clipboard(ClipboardItem::new_string(session_id.clone()));
                        }
                    }),
            )
            .item(
                PopupMenuItem::new("Copy deeplink")
                    .icon(IconName::Copy)
                    .on_click({
                        let conversation_id = task_id.clone();
                        move |_, _, cx| {
                            cx.write_to_clipboard(ClipboardItem::new_string(format!(
                                "codex://threads/{conversation_id}"
                            )));
                        }
                    }),
            );
        if include_markdown {
            let copy_view = view;
            menu = menu.item(
                PopupMenuItem::new("Copy as Markdown")
                    .icon(IconName::Copy)
                    .on_click(move |_, _, cx| {
                        let task_id = task_id.clone();
                        let _ = copy_view.update(cx, |this, cx| {
                            this.copy_task_as_markdown(task_id, cx);
                        });
                    }),
            );
        }
        menu
    }

    fn local_project_actions_menu(
        menu: PopupMenu,
        view: WeakEntity<Self>,
        target: LocalProjectActionMenuTarget,
        _window: &mut Window,
        _cx: &mut Context<PopupMenu>,
    ) -> PopupMenu {
        let LocalProjectActionMenuTarget {
            path,
            name,
            pinned,
            available,
        } = target;
        let new_chat_view = view.clone();
        let new_chat_path = path.clone();
        let rename_view = view.clone();
        let rename_path = path.clone();
        let rename_name = name.clone();
        let open_view = view.clone();
        let open_path = path.clone();
        let pin_view = view.clone();
        let pin_path = path.clone();
        let remove_view = view;
        menu.item(
            PopupMenuItem::new("New chat")
                .icon(IconName::Plus)
                .disabled(!available)
                .on_click(move |_, _, cx| {
                    let path = new_chat_path.clone();
                    let _ = new_chat_view.update(cx, |this, cx| {
                        this.dispatch(Action::SelectWorkspace(path), cx);
                        this.close_narrow_sidebar();
                    });
                }),
        )
        .item(
            PopupMenuItem::new("Rename project").on_click(move |_, window, cx| {
                let path = rename_path.clone();
                let name = rename_name.clone();
                let _ = rename_view.update(cx, |this, cx| {
                    this.begin_local_project_rename(path, name, window, cx);
                });
            }),
        )
        .item(
            PopupMenuItem::new(local_project_open_label())
                .icon(IconName::FolderOpen)
                .disabled(!available)
                .on_click(move |_, _, cx| {
                    let path = open_path.clone();
                    let _ = open_view.update(cx, |this, cx| {
                        this.dispatch(Action::OpenLocalProject(path), cx);
                    });
                }),
        )
        .item(
            PopupMenuItem::new(if pinned {
                "Unpin project"
            } else {
                "Pin project"
            })
            .on_click(move |_, _, cx| {
                let path = pin_path.clone();
                let _ = pin_view.update(cx, |this, cx| {
                    this.dispatch(Action::ToggleLocalProjectPinned(path), cx);
                });
            }),
        )
        .separator()
        .item(
            PopupMenuItem::new("Remove")
                .icon(IconName::Delete)
                .on_click(move |_, _, cx| {
                    let path = path.clone();
                    let name = name.clone();
                    let _ = remove_view.update(cx, |this, cx| {
                        this.confirm_remove_local_project(path, name, cx);
                    });
                }),
        )
    }

    fn task_actions_menu(
        menu: PopupMenu,
        view: WeakEntity<Self>,
        target: TaskActionMenuTarget,
        header_overflow: bool,
        window: &mut Window,
        cx: &mut Context<PopupMenu>,
    ) -> PopupMenu {
        let TaskActionMenuTarget {
            task_id,
            title,
            cwd,
            is_pinned,
        } = target;
        let pin_view = view.clone();
        let pin_task_id = task_id.clone();
        let rename_view = view.clone();
        let rename_task_id = task_id.clone();
        let copy_view = view.clone();
        let copy_task_id = task_id.clone();
        let copy_cwd = cwd.clone();
        let current_workspace_view = view.clone();
        let current_workspace_task_id = task_id.clone();
        let worktree_view = view.clone();
        let worktree_task_id = task_id.clone();
        let worktree_available = cwd.is_absolute();
        let menu = menu
            .item(
                PopupMenuItem::new(if is_pinned { "Unpin chat" } else { "Pin chat" }).on_click(
                    move |_, _, cx| {
                        let task_id = pin_task_id.clone();
                        let _ = pin_view.update(cx, |this, cx| {
                            this.dispatch(Action::ToggleTaskPinned(task_id), cx);
                        });
                    },
                ),
            )
            .item(
                PopupMenuItem::new("Rename chat").on_click(move |_, window, cx| {
                    let task_id = rename_task_id.clone();
                    let title = title.clone();
                    let _ = rename_view.update(cx, |this, cx| {
                        this.begin_task_rename(task_id, title, window, cx);
                    });
                }),
            )
            .item(
                PopupMenuItem::new("Archive chat").on_click(move |_, _, cx| {
                    let task_id = task_id.clone();
                    let _ = view.update(cx, |this, cx| {
                        this.dispatch(Action::ArchiveTask(task_id), cx);
                    });
                }),
            )
            .separator()
            .item(
                PopupMenuItem::new("Continue in new chat")
                    .icon(IconName::Redo2)
                    .on_click(move |_, _, cx| {
                        let task_id = current_workspace_task_id.clone();
                        let _ = current_workspace_view.update(cx, |this, cx| {
                            this.dispatch(Action::ForkTaskInCurrentWorkspace(task_id), cx);
                        });
                    }),
            )
            .item(
                PopupMenuItem::new("Continue in new worktree")
                    .icon(IconName::FolderOpen)
                    .disabled(!worktree_available)
                    .on_click(move |_, _, cx| {
                        let task_id = worktree_task_id.clone();
                        let _ = worktree_view.update(cx, |this, cx| {
                            this.dispatch(Action::ForkTaskIntoWorktree(task_id), cx);
                        });
                    }),
            )
            .separator();
        if header_overflow {
            menu.submenu_with_icon(
                Some(Icon::new(IconName::Copy)),
                "Copy",
                window,
                cx,
                move |menu, _, _| {
                    Self::task_copy_menu_items(
                        menu,
                        copy_view.clone(),
                        copy_task_id.clone(),
                        copy_cwd.clone(),
                        true,
                    )
                },
            )
        } else {
            Self::task_copy_menu_items(menu, copy_view, copy_task_id, copy_cwd, false)
        }
    }

