    fn archived_chat_project_menu(
        mut menu: PopupMenu,
        view: WeakEntity<Self>,
        projects: Vec<PathBuf>,
        selected: ArchivedChatProjectFilter,
    ) -> PopupMenu {
        let all_view = view.clone();
        menu = menu.item(
            PopupMenuItem::new("All projects")
                .checked(selected == ArchivedChatProjectFilter::All)
                .on_click(move |_, _, cx| {
                    let _ = all_view.update(cx, |this, cx| {
                        this.archived_chat_project_filter = ArchivedChatProjectFilter::All;
                        cx.notify();
                    });
                }),
        );
        if !projects.is_empty() {
            menu = menu.separator();
        }
        for project in projects {
            let item_view = view.clone();
            let selected_project = project.clone();
            let checked = selected == ArchivedChatProjectFilter::Project(selected_project.clone());
            menu = menu.item(
                PopupMenuItem::new(archived_project_label(&project))
                    .checked(checked)
                    .on_click(move |_, _, cx| {
                        let project = selected_project.clone();
                        let _ = item_view.update(cx, |this, cx| {
                            this.archived_chat_project_filter =
                                ArchivedChatProjectFilter::Project(project);
                            cx.notify();
                        });
                    }),
            );
        }
        let chats_view = view;
        menu.separator().item(
            PopupMenuItem::new("Chats")
                .checked(selected == ArchivedChatProjectFilter::Chats)
                .on_click(move |_, _, cx| {
                    let _ = chats_view.update(cx, |this, cx| {
                        this.archived_chat_project_filter = ArchivedChatProjectFilter::Chats;
                        cx.notify();
                    });
                }),
        )
    }

