    fn navigate(&mut self, route: MainRoute, cx: &mut Context<Self>) {
        self.dispatch(Action::Navigate(route), cx);
        self.close_narrow_sidebar();
    }

    fn navigation_location_available(&self, location: &NavigationLocation) -> bool {
        location
            .selected_task_id
            .as_ref()
            .is_none_or(|task_id| self.state.tasks.iter().any(|task| task.id == *task_id))
    }

    fn navigation_target_index(&self, forward: bool) -> Option<usize> {
        let mut index = self.navigation_history.index;
        loop {
            if forward {
                index = index.checked_add(1)?;
                if index >= self.navigation_history.entries.len() {
                    return None;
                }
            } else {
                index = index.checked_sub(1)?;
            }
            if self.navigation_location_available(&self.navigation_history.entries[index]) {
                return Some(index);
            }
        }
    }

    fn can_navigate_history(&self, forward: bool) -> bool {
        self.navigation_target_index(forward).is_some()
    }

    fn navigate_history(&mut self, forward: bool, cx: &mut Context<Self>) {
        let Some(index) = self.navigation_target_index(forward) else {
            return;
        };
        let target = self.navigation_history.entries[index].clone();
        self.navigation_history_replaying = true;
        match target.selected_task_id.clone() {
            Some(task_id) => {
                if self.state.route != target.route {
                    self.dispatch(Action::Navigate(target.route), cx);
                }
                if self.state.selected_task_id.as_deref() != Some(task_id.as_str()) {
                    self.dispatch(Action::SelectTask(task_id), cx);
                }
            }
            None => {
                if self.state.selected_task_id.is_some() {
                    self.dispatch(Action::BeginNewChat, cx);
                }
                if self.state.route != target.route {
                    self.dispatch(Action::Navigate(target.route), cx);
                }
            }
        }
        self.navigation_history_replaying = false;
        self.navigation_history.index = index;
        cx.notify();
    }

    fn thread_find_matches(&self, cx: &App) -> ThreadFindMatches {
        let query = self.thread_find_input.read(cx).value().to_string();
        let Some(task_id) = self.state.selected_task_id.as_deref() else {
            return ThreadFindMatches::default();
        };
        let Some(timeline) = self.state.timelines.get(task_id) else {
            return ThreadFindMatches::default();
        };
        find_timeline_matches(&timeline.items, &query)
    }

    fn refresh_thread_find_active(&mut self, cx: &mut Context<Self>) {
        let matches = self.thread_find_matches(cx);
        let active_index = matches.item_indices.first().copied();
        self.thread_find_active_item_id = active_index.and_then(|index| {
            let task_id = self.state.selected_task_id.as_deref()?;
            self.state
                .timelines
                .get(task_id)?
                .items
                .get(index)
                .map(|item| item.id.clone())
        });
        if self.thread_find_open
            && let Some(index) = active_index
        {
            self.timeline_list.scroll_to_reveal_item(index);
        }
        cx.notify();
    }

    fn open_thread_find(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        if self.state.route != MainRoute::Tasks || self.state.selected_task_id.is_none() {
            return;
        }
        self.command_palette = None;
        self.thread_find_open = true;
        self.refresh_thread_find_active(cx);
        self.thread_find_input
            .update(cx, |input, cx| input.focus(window, cx));
    }

    fn close_thread_find(&mut self, cx: &mut Context<Self>) {
        self.thread_find_open = false;
        self.thread_find_active_item_id = None;
        cx.notify();
    }

    fn navigate_thread_find(&mut self, next: bool, cx: &mut Context<Self>) {
        let matches = self.thread_find_matches(cx);
        if matches.item_indices.is_empty() {
            self.thread_find_active_item_id = None;
            cx.notify();
            return;
        }
        let Some(task_id) = self.state.selected_task_id.as_deref() else {
            return;
        };
        let Some(timeline) = self.state.timelines.get(task_id) else {
            return;
        };
        let active_position = self
            .thread_find_active_item_id
            .as_deref()
            .and_then(|active_id| {
                matches.item_indices.iter().position(|index| {
                    timeline
                        .items
                        .get(*index)
                        .is_some_and(|item| item.id == active_id)
                })
            });
        let position = match (active_position, next) {
            (Some(position), true) => (position + 1) % matches.item_indices.len(),
            (Some(0), false) | (None, false) => matches.item_indices.len() - 1,
            (Some(position), false) => position - 1,
            (None, true) => 0,
        };
        let index = matches.item_indices[position];
        self.thread_find_active_item_id = timeline.items.get(index).map(|item| item.id.clone());
        self.timeline_list.scroll_to_reveal_item(index);
        cx.notify();
    }

    fn handle_thread_find_key_down(&mut self, event: &KeyDownEvent, cx: &mut Context<Self>) {
        let key = event.keystroke.key.as_str();
        if key.eq_ignore_ascii_case("escape") {
            cx.stop_propagation();
            self.close_thread_find(cx);
        } else if key.eq_ignore_ascii_case("enter") {
            cx.stop_propagation();
            self.navigate_thread_find(!event.keystroke.modifiers.shift, cx);
        }
    }

    fn thread_find_right_offset(&self) -> f32 {
        if self.state.terminal_dock_open
            && self.state.terminal.location == TerminalDockLocation::Right
        {
            return self.terminal_right_width + 16.0;
        }
        let inspector_width = match self.state.inspector {
            InspectorPane::Changes => CHANGES_INSPECTOR_WIDTH,
            InspectorPane::Outputs | InspectorPane::Files
                if self.state.artifacts.selected_path.is_some() =>
            {
                OUTPUT_VIEWER_WIDTH
            }
            InspectorPane::Hidden | InspectorPane::Terminal => 0.0,
            InspectorPane::Browser => BROWSER_INSPECTOR_WIDTH,
            InspectorPane::Outputs | InspectorPane::Files | InspectorPane::ComputerUse => {
                INSPECTOR_WIDTH
            }
        };
        inspector_width + 16.0
    }

    fn render_thread_find_bar(&self, window: &Window, cx: &mut Context<Self>) -> AnyElement {
        let matches = self.thread_find_matches(cx);
        let query = self.thread_find_input.read(cx).value().trim().to_owned();
        let has_query = !query.is_empty();
        let active_position = self
            .thread_find_active_item_id
            .as_deref()
            .and_then(|active_id| {
                let task_id = self.state.selected_task_id.as_deref()?;
                let timeline = self.state.timelines.get(task_id)?;
                matches.item_indices.iter().position(|index| {
                    timeline
                        .items
                        .get(*index)
                        .is_some_and(|item| item.id == active_id)
                })
            });
        let result_label = if !has_query {
            None
        } else if matches.item_indices.is_empty() {
            Some("0 results".to_owned())
        } else {
            let suffix = if matches.is_capped { "+" } else { "" };
            Some(format!(
                "{} / {}{suffix} results",
                active_position.unwrap_or(0) + 1,
                matches.item_indices.len()
            ))
        };
        let right = self.thread_find_right_offset();
        let available_width = f32::from(window.viewport_size().width) - right - 16.0;
        let width = available_width.clamp(280.0, 520.0);

        h_flex()
            .absolute()
            .top(px(8.0))
            .right(px(right))
            .w(px(width))
            .h(px(44.0))
            .px_1()
            .gap_1()
            .items_center()
            .rounded_lg()
            .border_1()
            .border_color(cx.theme().border)
            .bg(cx.theme().popover)
            .shadow_lg()
            .occlude()
            .on_key_down(cx.listener(|this, event, _, cx| {
                this.handle_thread_find_key_down(event, cx);
            }))
            .child(Icon::new(IconName::Search).xsmall())
            .child(
                div().flex_1().min_w_0().child(
                    Input::new(&self.thread_find_input)
                        .small()
                        .appearance(false),
                ),
            )
            .when_some(result_label, |bar, label| {
                bar.child(
                    div()
                        .flex_shrink_0()
                        .text_xs()
                        .text_color(cx.theme().muted_foreground)
                        .child(label),
                )
            })
            .child(
                Button::new("thread-find-previous")
                    .icon(IconName::ChevronUp)
                    .tooltip("Previous result · Shift+F3")
                    .xsmall()
                    .ghost()
                    .disabled(matches.item_indices.is_empty())
                    .on_click(cx.listener(|this, _, _, cx| {
                        this.navigate_thread_find(false, cx);
                    })),
            )
            .child(
                Button::new("thread-find-next")
                    .icon(IconName::ChevronDown)
                    .tooltip("Next result · Ctrl+G")
                    .xsmall()
                    .ghost()
                    .disabled(matches.item_indices.is_empty())
                    .on_click(cx.listener(|this, _, _, cx| {
                        this.navigate_thread_find(true, cx);
                    })),
            )
            .child(
                Button::new("thread-find-close")
                    .icon(IconName::Close)
                    .tooltip("Close find")
                    .xsmall()
                    .ghost()
                    .on_click(cx.listener(|this, _, _, cx| {
                        this.close_thread_find(cx);
                    })),
            )
            .into_any_element()
    }

    fn sync_composer_pickers(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        let model_items = self
            .state
            .composer_controls
            .models
            .iter()
            .map(|model| PickerItem::new(model.id.clone(), model.display_name.clone()))
            .collect::<Vec<_>>();
        if model_items != self.synced_model_items {
            let selected = self.state.composer_controls.selected_model.clone();
            let picker_items = model_items.clone();
            self.model_picker.update(cx, |picker, cx| {
                picker.set_items(SearchableVec::new(picker_items), window, cx);
                if let Some(selected) = selected.as_ref() {
                    picker.set_selected_value(selected, window, cx);
                } else {
                    picker.set_selected_index(None, window, cx);
                }
            });
            self.synced_model_items = model_items;
        }

        let effort_items = self
            .state
            .composer_controls
            .selected_model
            .as_deref()
            .and_then(|selected| {
                self.state
                    .composer_controls
                    .models
                    .iter()
                    .find(|model| model.id == selected)
            })
            .map(|model| {
                model
                    .supported_efforts
                    .iter()
                    .map(|effort| PickerItem::new(effort.id.clone(), effort_label(&effort.id)))
                    .collect::<Vec<_>>()
            })
            .unwrap_or_default();
        if effort_items != self.synced_effort_items {
            let selected = self.state.composer_controls.selected_effort.clone();
            let picker_items = effort_items.clone();
            self.effort_picker.update(cx, |picker, cx| {
                picker.set_items(SearchableVec::new(picker_items), window, cx);
                if let Some(selected) = selected.as_ref() {
                    picker.set_selected_value(selected, window, cx);
                } else {
                    picker.set_selected_index(None, window, cx);
                }
            });
            self.synced_effort_items = effort_items;
        }

        let service_tier_items = self
            .state
            .composer_controls
            .selected_model
            .as_deref()
            .and_then(|selected| {
                self.state
                    .composer_controls
                    .models
                    .iter()
                    .find(|model| model.id == selected)
            })
            .filter(|model| !model.service_tiers.is_empty())
            .map(|model| {
                std::iter::once(PickerItem::new(STANDARD_SERVICE_TIER_ID, "Standard"))
                    .chain(model.service_tiers.iter().map(|tier| {
                        PickerItem::new(tier.id.clone(), service_tier_label(&tier.id, &tier.name))
                    }))
                    .collect::<Vec<_>>()
            })
            .unwrap_or_default();
        if service_tier_items != self.synced_service_tier_items {
            let selected = self
                .state
                .composer_controls
                .selected_service_tier
                .clone()
                .unwrap_or_else(|| STANDARD_SERVICE_TIER_ID.to_owned());
            let picker_items = service_tier_items.clone();
            self.service_tier_picker.update(cx, |picker, cx| {
                picker.set_items(SearchableVec::new(picker_items), window, cx);
                picker.set_selected_value(&selected, window, cx);
            });
            self.synced_service_tier_items = service_tier_items;
        }

        let permission_items = self
            .state
            .composer_controls
            .permission_modes
            .iter()
            .filter(|mode| mode.allowed)
            .map(|mode| PickerItem::new(mode.id.clone(), mode.label.clone()))
            .collect::<Vec<_>>();
        if permission_items != self.synced_permission_items {
            let selected = self
                .state
                .composer_controls
                .selected_permission_mode
                .clone();
            let picker_items = permission_items.clone();
            self.permission_picker.update(cx, |picker, cx| {
                picker.set_items(SearchableVec::new(picker_items), window, cx);
                if let Some(selected) = selected.as_ref() {
                    picker.set_selected_value(selected, window, cx);
                } else {
                    picker.set_selected_index(None, window, cx);
                }
            });
            self.synced_permission_items = permission_items;
        }
    }

    fn sync_review_base_picker(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        let mut seen = HashSet::new();
        let mut values = Vec::with_capacity(self.state.git.review_branches.len() + 2);
        if let Some(selected) = self.state.git.selected_review_base.as_ref()
            && seen.insert(selected.clone())
        {
            values.push(selected.clone());
        }
        if let Some(default) = self.state.git.review_default_base.as_ref()
            && seen.insert(default.clone())
        {
            values.push(default.clone());
        }
        for branch in &self.state.git.review_branches {
            if self.state.git.branch.as_ref() != Some(branch) && seen.insert(branch.clone()) {
                values.push(branch.clone());
            }
        }
        let items = values
            .into_iter()
            .map(ReviewBasePickerItem::branch)
            .collect::<Vec<_>>();
        if items == self.synced_review_base_items {
            return;
        }

        let selected = self
            .state
            .git
            .selected_review_base
            .as_ref()
            .or(self.state.git.review_default_base.as_ref())
            .cloned();
        let picker_items = items.clone();
        let picker_query = Rc::clone(&self.review_base_query);
        self.review_base_picker.update(cx, |picker, cx| {
            picker.set_items(
                ReviewBasePickerDelegate::new(picker_items, picker_query),
                window,
                cx,
            );
            if let Some(selected) = selected.as_ref() {
                picker.set_selected_value(selected, window, cx);
            } else {
                picker.set_selected_index(None, window, cx);
            }
        });
        self.synced_review_base_items = items;
    }

    fn render_sidebar_toggle(&self, cx: &mut Context<Self>) -> AnyElement {
        Button::new("toggle-sidebar")
            .icon(if self.sidebar_visible {
                IconName::PanelLeftClose
            } else {
                IconName::PanelLeftOpen
            })
            .tooltip("Toggle sidebar · Ctrl+B")
            .xsmall()
            .w(px(28.0))
            .h(px(28.0))
            .ghost()
            .on_click(cx.listener(|this, _, _, cx| {
                this.toggle_sidebar(cx);
            }))
            .into_any_element()
    }

    fn render_navigation_controls(&self, cx: &mut Context<Self>) -> AnyElement {
        h_flex()
            .gap_1()
            .items_center()
            .child(self.render_sidebar_toggle(cx))
            .child(
                Button::new("navigate-back")
                    .icon(IconName::ArrowLeft)
                    .tooltip("Back · Ctrl+[")
                    .xsmall()
                    .w(px(28.0))
                    .h(px(28.0))
                    .ghost()
                    .disabled(!self.can_navigate_history(false))
                    .on_click(cx.listener(|this, _, _, cx| {
                        this.navigate_history(false, cx);
                    })),
            )
            .child(
                Button::new("navigate-forward")
                    .icon(IconName::ArrowRight)
                    .tooltip("Forward · Ctrl+]")
                    .xsmall()
                    .w(px(28.0))
                    .h(px(28.0))
                    .ghost()
                    .disabled(!self.can_navigate_history(true))
                    .on_click(cx.listener(|this, _, _, cx| {
                        this.navigate_history(true, cx);
                    })),
            )
            .into_any_element()
    }

    fn shortcut_popup_menu_item(
        label: &'static str,
        command_id: &'static str,
        shortcuts: &HashMap<&'static str, String>,
    ) -> PopupMenuItem {
        let shortcut = shortcuts.get(command_id).cloned();
        PopupMenuItem::element(move |_, _| {
            h_flex()
                .w_full()
                .gap_3()
                .items_center()
                .justify_between()
                .child(label)
                .when_some(shortcut.clone(), |item, shortcut| item.child(shortcut))
        })
    }

    fn file_menu(
        mut menu: PopupMenu,
        view: WeakEntity<Self>,
        shortcuts: Arc<HashMap<&'static str, String>>,
        account_available: bool,
        account_idle: bool,
    ) -> PopupMenu {
        let new_chat_view = view.clone();
        menu = menu.item(
            Self::shortcut_popup_menu_item("New Chat", "newTask", &shortcuts)
                .action(Box::new(NewChatShortcut))
                .on_click(move |_, window, cx| {
                    let _ = new_chat_view.update(cx, |this, cx| {
                        this.begin_new_chat(window, cx);
                    });
                }),
        );
        let open_folder_view = view.clone();
        menu = menu
            .item(
                Self::shortcut_popup_menu_item("Open Folder…", "openFolder", &shortcuts)
                    .action(Box::new(OpenFolderShortcut))
                    .on_click(move |_, _, cx| {
                        let _ = open_folder_view.update(cx, |this, cx| {
                            this.prompt_for_workspace(cx);
                        });
                    }),
            )
            .item(PopupMenuItem::separator())
            .item(
                Self::shortcut_popup_menu_item("Close", "closeWindow", &shortcuts)
                    .action(Box::new(CloseWindowShortcut))
                    .on_click(|_, window, _| {
                        window.remove_window();
                    }),
            )
            .item(PopupMenuItem::separator());
        let logout_view = view;
        menu.item(
            PopupMenuItem::new("Log Out")
                .disabled(!account_available || !account_idle)
                .on_click(move |_, _, cx| {
                    let _ = logout_view.update(cx, |this, cx| {
                        this.confirm_account_logout(cx);
                    });
                }),
        )
        .item(PopupMenuItem::separator())
        .item(
            Self::shortcut_popup_menu_item("Quit", "quit", &shortcuts)
                .action(Box::new(QuitShortcut))
                .on_click(|_, window, _| {
                    window.remove_window();
                }),
        )
    }

    fn edit_menu(
        mut menu: PopupMenu,
        view: WeakEntity<Self>,
        shortcuts: Arc<HashMap<&'static str, String>>,
    ) -> PopupMenu {
        menu = menu
            .item(PopupMenuItem::new("Undo").action(Box::new(InputUndo)))
            .item(PopupMenuItem::new("Redo").action(Box::new(InputRedo)))
            .item(PopupMenuItem::separator())
            .item(PopupMenuItem::new("Cut").action(Box::new(InputCut)))
            .item(PopupMenuItem::new("Copy").action(Box::new(InputCopy)))
            .item(PopupMenuItem::new("Paste").action(Box::new(InputPaste)))
            .item(PopupMenuItem::new("Select All").action(Box::new(InputSelectAll)))
            .item(PopupMenuItem::separator());
        menu.item(
            Self::shortcut_popup_menu_item("Settings…", "settings", &shortcuts)
                .action(Box::new(OpenSettingsShortcut))
                .on_click(move |_, _, cx| {
                    let _ = view.update(cx, |this, cx| {
                        this.open_settings_section(SettingsSection::General, cx);
                    });
                }),
        )
    }

