    fn render_local_project(
        &mut self,
        project: LocalProjectSummary,
        task_indices: Vec<usize>,
        cx: &mut Context<Self>,
    ) -> AnyElement {
        let available = project.path.is_dir();
        let has_chats = self.state.tasks.iter().any(|task| task.cwd == project.path);
        let selected = self
            .state
            .selected_task_id
            .as_deref()
            .and_then(|task_id| self.state.tasks.iter().find(|task| task.id == task_id))
            .map_or_else(
                || self.state.new_chat_cwd.as_ref() == Some(&project.path),
                |task| task.cwd == project.path,
            );
        let key = local_project_element_key(&project.path);
        let target = LocalProjectActionMenuTarget {
            path: project.path.clone(),
            name: project.name.clone(),
            pinned: project.pinned,
            available,
        };
        let context_target = target.clone();
        let dropdown_target = target.clone();
        let context_view = cx.entity().downgrade();
        let dropdown_view = context_view.clone();
        let new_chat_path = project.path.clone();
        let select_path = project.path.clone();
        let name = project.name;
        let pinned = project.pinned;

        v_flex()
            .child(
                h_flex()
                    .id(SharedString::from(format!("local-project-{key:016x}")))
                    .h(px(34.0))
                    .px_2()
                    .gap_2()
                    .items_center()
                    .rounded_md()
                    .when(selected, |row| row.bg(cx.theme().sidebar_accent))
                    .when(!selected, |row| {
                        row.hover(|style| style.bg(cx.theme().list_hover))
                    })
                    .child(
                        h_flex()
                            .id(SharedString::from(format!("select-project-{key:016x}")))
                            .flex_1()
                            .min_w_0()
                            .gap_2()
                            .items_center()
                            .when(pointer_cursors_enabled(cx), |element| {
                                element.cursor_pointer()
                            })
                            .child(
                                Icon::new(if available {
                                    IconName::FolderClosed
                                } else {
                                    IconName::TriangleAlert
                                })
                                .xsmall()
                                .text_color(if available {
                                    cx.theme().muted_foreground
                                } else {
                                    cx.theme().warning
                                }),
                            )
                            .child(
                                div()
                                    .flex_1()
                                    .min_w_0()
                                    .text_sm()
                                    .font_weight(gpui::FontWeight::MEDIUM)
                                    .truncate()
                                    .child(name),
                            )
                            .when(pinned, |label| {
                                label.child(
                                    Icon::new(IconName::Star)
                                        .xsmall()
                                        .text_color(cx.theme().muted_foreground),
                                )
                            })
                            .on_click(cx.listener(move |this, _, _, cx| {
                                if available {
                                    this.dispatch(Action::SelectWorkspace(select_path.clone()), cx);
                                    this.close_narrow_sidebar();
                                } else {
                                    this.dispatch(
                                        Action::SetStatus(
                                            "This project folder was deleted or moved".to_owned(),
                                        ),
                                        cx,
                                    );
                                }
                            })),
                    )
                    .child(
                        Button::new(SharedString::from(format!("new-chat-project-{key:016x}")))
                            .icon(IconName::Plus)
                            .tooltip("New chat")
                            .xsmall()
                            .ghost()
                            .disabled(!available)
                            .on_click(cx.listener(move |this, _, _, cx| {
                                this.dispatch(Action::SelectWorkspace(new_chat_path.clone()), cx);
                                this.close_narrow_sidebar();
                            })),
                    )
                    .child(
                        Button::new(SharedString::from(format!("project-menu-{key:016x}")))
                            .icon(IconName::Ellipsis)
                            .tooltip("Project actions")
                            .xsmall()
                            .ghost()
                            .dropdown_menu(move |menu, window, cx| {
                                Self::local_project_actions_menu(
                                    menu,
                                    dropdown_view.clone(),
                                    dropdown_target.clone(),
                                    window,
                                    cx,
                                )
                            }),
                    )
                    .context_menu(move |menu, window, cx| {
                        Self::local_project_actions_menu(
                            menu,
                            context_view.clone(),
                            context_target.clone(),
                            window,
                            cx,
                        )
                    }),
            )
            .when(!available, |group| {
                group.child(
                    div()
                        .px_8()
                        .pb_1()
                        .text_xs()
                        .text_color(cx.theme().warning)
                        .child("This project folder was deleted or moved"),
                )
            })
            .when(available && !has_chats, |group| {
                group.child(
                    div()
                        .px_8()
                        .pb_1()
                        .text_xs()
                        .text_color(cx.theme().muted_foreground)
                        .child("No chats"),
                )
            })
            .children(
                task_indices
                    .into_iter()
                    .map(|index| self.render_task(index, cx)),
            )
            .into_any_element()
    }

    fn render_task(&mut self, index: usize, cx: &mut Context<Self>) -> AnyElement {
        let Some(task) = self.state.tasks.get(index).cloned() else {
            return div().into_any_element();
        };
        self.render_task_row(task, cx)
    }

    fn render_task_row(&mut self, task: TaskSummary, cx: &mut Context<Self>) -> AnyElement {
        let selected = self.state.selected_task_id.as_deref() == Some(task.id.as_str());
        let task_id = task.id.clone();
        let title = task.title.clone();
        let menu_task_id = task_id.clone();
        let menu_title = title.clone();
        let menu_cwd = task.cwd.clone();
        let menu_view = cx.entity().downgrade();
        let is_pinned = self
            .state
            .pinned_task_ids
            .iter()
            .any(|pinned_task_id| pinned_task_id == &task.id);
        let (status_icon, status_color) = task_status_icon(task.status, cx);
        let updated_at = relative_time(task.updated_at);
        let forked = task.forked_from_id.is_some();

        h_flex()
            .id(SharedString::from(format!("task-{}", task.id)))
            .h(px(38.0))
            .px_2()
            .gap_2()
            .items_center()
            .rounded_md()
            .when(pointer_cursors_enabled(cx), |element| {
                element.cursor_pointer()
            })
            .when(selected, |item| item.bg(cx.theme().sidebar_accent))
            .when(!selected, |item| {
                item.hover(|style| style.bg(cx.theme().list_hover))
            })
            .on_click(cx.listener(move |this, _, _, cx| {
                this.dispatch(Action::SelectTask(task_id.clone()), cx);
                this.close_narrow_sidebar();
            }))
            .child(Icon::new(status_icon).xsmall().text_color(status_color))
            .child(div().flex_1().min_w_0().text_sm().truncate().child(title))
            .when(forked, |row| {
                row.child(
                    Icon::new(IconName::ExternalLink)
                        .xsmall()
                        .text_color(cx.theme().muted_foreground),
                )
            })
            .when(!updated_at.is_empty(), |row| {
                row.child(
                    div()
                        .flex_none()
                        .text_xs()
                        .text_color(cx.theme().muted_foreground)
                        .child(updated_at),
                )
            })
            .context_menu(move |menu, window, cx| {
                Self::task_actions_menu(
                    menu,
                    menu_view.clone(),
                    TaskActionMenuTarget {
                        task_id: menu_task_id.clone(),
                        title: menu_title.clone(),
                        cwd: menu_cwd.clone(),
                        is_pinned,
                    },
                    false,
                    window,
                    cx,
                )
            })
            .into_any_element()
    }

    fn render_sidebar_footer(&self, cx: &mut Context<Self>) -> AnyElement {
        let (label, color, tooltip, retryable) = match &self.state.connection {
            ConnectionStatus::Offline => (
                "Offline".to_owned(),
                cx.theme().muted_foreground,
                None,
                false,
            ),
            ConnectionStatus::Connecting => {
                ("Connecting…".to_owned(), cx.theme().info, None, false)
            }
            ConnectionStatus::Online => (
                "App-server online".to_owned(),
                cx.theme().success,
                None,
                false,
            ),
            ConnectionStatus::Recovering {
                attempt,
                retry_in_ms,
                last_error,
            } => {
                let label = match (*attempt, retry_in_ms) {
                    (0, _) => "Reconnecting…".to_owned(),
                    (attempt, Some(retry_in_ms)) => {
                        format!("Retry {attempt} in {}s", retry_in_ms.div_ceil(1_000))
                    }
                    (attempt, None) => format!("Reconnecting · attempt {attempt}"),
                };
                let tooltip = last_error.as_ref().map_or_else(
                    || "The Codex app-server stopped. codexRS will retry automatically.".to_owned(),
                    |error| format!("{error}\ncodexRS will retry automatically."),
                );
                (label, cx.theme().warning, Some(tooltip), false)
            }
            ConnectionStatus::Failed(error) => (
                "Connection failed".to_owned(),
                cx.theme().danger,
                Some(format!("{error}\nClick to retry.")),
                true,
            ),
        };
        v_flex()
            .px_2()
            .py_2()
            .gap_1()
            .border_t_1()
            .border_color(cx.theme().sidebar_border)
            .child(
                h_flex()
                    .id("nav-settings")
                    .h(px(34.0))
                    .px_2()
                    .gap_2()
                    .items_center()
                    .rounded_md()
                    .when(pointer_cursors_enabled(cx), |element| {
                        element.cursor_pointer()
                    })
                    .when(self.state.route == MainRoute::Settings, |item| {
                        item.bg(cx.theme().sidebar_accent)
                    })
                    .when(self.state.route != MainRoute::Settings, |item| {
                        item.hover(|style| style.bg(cx.theme().list_hover))
                    })
                    .child(Icon::new(IconName::Settings).xsmall())
                    .child(div().text_sm().child("Settings"))
                    .on_click(cx.listener(|this, _, _, cx| {
                        this.open_settings_section(SettingsSection::General, cx);
                    })),
            )
            .child(
                h_flex()
                    .id("app-server-connection-status")
                    .h(px(24.0))
                    .px_2()
                    .gap_2()
                    .items_center()
                    .when(retryable, |row| {
                        row.when(pointer_cursors_enabled(cx), |row| row.cursor_pointer())
                            .on_click(cx.listener(|this, _, _, cx| {
                                this.dispatch(Action::RetryConnection, cx);
                            }))
                    })
                    .when_some(tooltip, |row, tooltip| {
                        row.tooltip(move |window, cx| {
                            Tooltip::new(tooltip.clone()).build(window, cx)
                        })
                    })
                    .child(div().size(px(7.0)).rounded_full().bg(color))
                    .child(
                        div()
                            .min_w_0()
                            .truncate()
                            .text_xs()
                            .text_color(cx.theme().muted_foreground)
                            .child(label),
                    ),
            )
            .into_any_element()
    }

    fn render_main(&mut self, window: &mut Window, cx: &mut Context<Self>) -> AnyElement {
        match self.state.route {
            MainRoute::Tasks => self.render_task_workspace(cx),
            MainRoute::Repository => self.render_repository(cx),
            MainRoute::PullRequests => self.render_pull_requests(window, cx),
            MainRoute::Marketplace => self.render_marketplace(cx),
            MainRoute::Settings => self.render_settings(cx),
        }
    }

