    fn render_pull_request_row(
        &self,
        index: usize,
        pull_request: PullRequestSummary,
        cx: &mut Context<Self>,
    ) -> AnyElement {
        let selected = self.state.pull_requests.selected.as_ref() == Some(&pull_request.identity);
        let identity = pull_request.identity.clone();
        let state_label = if pull_request.is_draft {
            "Draft"
        } else {
            match pull_request.state {
                PullRequestState::Open => "Open",
                PullRequestState::Closed => "Closed",
                PullRequestState::Merged => "Merged",
            }
        };
        let state_color = match pull_request.state {
            PullRequestState::Open => cx.theme().success,
            PullRequestState::Closed => cx.theme().danger,
            PullRequestState::Merged => cx.theme().info,
        };
        let (ci_icon, ci_label, ci_color) = match pull_request.ci_status {
            PullRequestCiStatus::None => (IconName::Dash, "No checks", cx.theme().muted_foreground),
            PullRequestCiStatus::Pending => {
                (IconName::LoaderCircle, "Checks pending", cx.theme().warning)
            }
            PullRequestCiStatus::Passing => {
                (IconName::CircleCheck, "Checks passing", cx.theme().success)
            }
            PullRequestCiStatus::Failing => {
                (IconName::CircleX, "Checks failing", cx.theme().danger)
            }
        };
        let author = pull_request
            .author_login
            .as_deref()
            .unwrap_or("ghost")
            .to_owned();

        v_flex()
            .id(("pull-request-row", index))
            .w_full()
            .min_w_0()
            .px_3()
            .py_3()
            .gap_1()
            .border_b_1()
            .border_color(cx.theme().border)
            .when(pointer_cursors_enabled(cx), |element| {
                element.cursor_pointer()
            })
            .when(selected, |row| row.bg(cx.theme().list_active))
            .when(!selected, |row| {
                row.hover(|style| style.bg(cx.theme().list_hover))
            })
            .child(
                h_flex()
                    .min_w_0()
                    .gap_2()
                    .items_center()
                    .child(Icon::new(IconName::GitHub).xsmall())
                    .child(
                        div()
                            .flex_1()
                            .min_w_0()
                            .truncate()
                            .text_xs()
                            .text_color(cx.theme().muted_foreground)
                            .child(format!(
                                "{}/{} #{}",
                                pull_request.identity.owner,
                                pull_request.identity.repository,
                                pull_request.identity.number
                            )),
                    )
                    .child(
                        div()
                            .text_xs()
                            .font_weight(gpui::FontWeight::MEDIUM)
                            .text_color(state_color)
                            .child(state_label),
                    ),
            )
            .child(
                div()
                    .min_w_0()
                    .text_sm()
                    .font_weight(gpui::FontWeight::SEMIBOLD)
                    .line_clamp(2)
                    .child(pull_request.title),
            )
            .child(
                h_flex()
                    .min_w_0()
                    .gap_2()
                    .items_center()
                    .text_xs()
                    .text_color(cx.theme().muted_foreground)
                    .child(div().flex_1().min_w_0().truncate().child(format!(
                        "{author} · {} → {}",
                        pull_request.head_branch, pull_request.base_branch
                    )))
                    .child(
                        h_flex()
                            .gap_1()
                            .items_center()
                            .text_color(ci_color)
                            .child(Icon::new(ci_icon).xsmall())
                            .child(ci_label),
                    ),
            )
            .child(
                h_flex()
                    .gap_2()
                    .text_xs()
                    .child(
                        div()
                            .text_color(cx.theme().success)
                            .child(format!("+{}", pull_request.additions)),
                    )
                    .child(
                        div()
                            .text_color(cx.theme().danger)
                            .child(format!("-{}", pull_request.deletions)),
                    )
                    .child(
                        div()
                            .text_color(cx.theme().muted_foreground)
                            .child(format!("Updated {}", pull_request.updated_at)),
                    ),
            )
            .on_click(cx.listener(move |this, _, _, cx| {
                this.dispatch(Action::SelectPullRequest(identity.clone()), cx);
            }))
            .into_any_element()
    }

