    fn render_allow_all_browser_sites_modal(
        &mut self,
        request_id: String,
        source_name: String,
        cx: &mut Context<Self>,
    ) -> AnyElement {
        let title = if source_name == "Browser" {
            "Allow ChatGPT to interact with any website without asking?".to_owned()
        } else {
            format!(
                "Allow ChatGPT to use {source_name} to interact with any website without asking?"
            )
        };
        v_flex()
            .w(px(modal_surface_width(self.shell_viewport_width, 520.0)))
            .p_5()
            .gap_4()
            .rounded(px(16.0))
            .bg(cx.theme().popover)
            .shadow_xl()
            .occlude()
            .on_any_mouse_down(|_, _, cx| cx.stop_propagation())
            .child(
                div()
                    .text_lg()
                    .font_weight(gpui::FontWeight::SEMIBOLD)
                    .child(title),
            )
            .child(
                h_flex()
                    .items_start()
                    .gap_2()
                    .text_sm()
                    .text_color(cx.theme().muted_foreground)
                    .child(
                        Icon::new(IconName::TriangleAlert)
                            .xsmall()
                            .text_color(cx.theme().warning),
                    )
                    .child("This setting has elevated risks for your data."),
            )
            .child(
                h_flex()
                    .justify_end()
                    .gap_2()
                    .child(
                        Button::new("cancel-allow-all-browser-sites")
                            .label("Cancel")
                            .ghost()
                            .on_click(cx.listener(|this, _, _, cx| {
                                this.close_workspace_modal(cx);
                            })),
                    )
                    .child(
                        Button::new("confirm-allow-all-browser-sites")
                            .label("Allow any website")
                            .primary()
                            .on_click(cx.listener(move |this, _, _, cx| {
                                this.workspace_modal = None;
                                this.dispatch(
                                    Action::ResolveBrowserOriginElicitation {
                                        request_id: request_id.clone(),
                                        decision: BrowserOriginElicitationDecision::AllowAll,
                                    },
                                    cx,
                                );
                            })),
                    ),
            )
            .into_any_element()
    }

    fn render_browser_download_row(
        &mut self,
        index: usize,
        download: BrowserDownloadState,
        cx: &mut Context<Self>,
    ) -> AnyElement {
        let active = download.status.active();
        let progress = (download.total_bytes > 0).then(|| {
            (download.received_bytes as f64 / download.total_bytes as f64).clamp(0.0, 1.0) as f32
        });
        let timestamp = relative_time((download.updated_at_ms / 1_000) as i64);
        let status = match download.status {
            BrowserDownloadStatus::Started => "Starting…".to_owned(),
            BrowserDownloadStatus::InProgress if download.total_bytes > 0 => format!(
                "{} of {}",
                format_file_size(download.received_bytes),
                format_file_size(download.total_bytes)
            ),
            BrowserDownloadStatus::InProgress => {
                format!("{} downloaded", format_file_size(download.received_bytes))
            }
            BrowserDownloadStatus::Paused => "Paused".to_owned(),
            BrowserDownloadStatus::Failed => "Download failed".to_owned(),
            BrowserDownloadStatus::Canceled => "Stopped".to_owned(),
            BrowserDownloadStatus::Complete if download.file_exists => "Downloaded".to_owned(),
            BrowserDownloadStatus::Complete => "File moved or deleted".to_owned(),
        };
        let metadata = if timestamp.is_empty() || active {
            status
        } else {
            format!("{status} · {timestamp}")
        };
        let id = download.id.clone();
        let cancel_id = id.clone();
        let pause_id = id.clone();
        let resume_id = id.clone();
        let open_id = id.clone();
        let reveal_id = id.clone();
        let remove_id = id;

        v_flex()
            .id(SharedString::from(format!("browser-download-{index}")))
            .px_5()
            .py_3()
            .gap_2()
            .border_b_1()
            .border_color(cx.theme().border.opacity(0.75))
            .child(
                h_flex()
                    .items_start()
                    .gap_3()
                    .child(
                        div()
                            .size(px(34.0))
                            .flex_none()
                            .items_center()
                            .justify_center()
                            .rounded_md()
                            .bg(cx.theme().muted.opacity(0.55))
                            .child(Icon::new(IconName::File).xsmall()),
                    )
                    .child(
                        v_flex()
                            .flex_1()
                            .min_w_0()
                            .gap_1()
                            .child(
                                div()
                                    .truncate()
                                    .text_sm()
                                    .font_weight(gpui::FontWeight::MEDIUM)
                                    .child(download.filename),
                            )
                            .child(
                                div()
                                    .truncate()
                                    .text_xs()
                                    .text_color(cx.theme().muted_foreground)
                                    .child(metadata),
                            ),
                    )
                    .child(
                        h_flex()
                            .gap_1()
                            .when(download.can_pause, |actions| {
                                actions.child(
                                    Button::new(SharedString::from(format!(
                                        "pause-browser-download-{index}"
                                    )))
                                    .label("Pause")
                                    .small()
                                    .ghost()
                                    .on_click(cx.listener(move |this, _, _, cx| {
                                        this.dispatch(
                                            Action::PauseBrowserDownload(pause_id.clone()),
                                            cx,
                                        );
                                    })),
                                )
                            })
                            .when(download.can_resume, |actions| {
                                actions.child(
                                    Button::new(SharedString::from(format!(
                                        "resume-browser-download-{index}"
                                    )))
                                    .label("Resume")
                                    .small()
                                    .ghost()
                                    .on_click(cx.listener(move |this, _, _, cx| {
                                        this.dispatch(
                                            Action::ResumeBrowserDownload(resume_id.clone()),
                                            cx,
                                        );
                                    })),
                                )
                            })
                            .when(download.can_cancel, |actions| {
                                actions.child(
                                    Button::new(SharedString::from(format!(
                                        "cancel-browser-download-{index}"
                                    )))
                                    .label("Cancel")
                                    .small()
                                    .ghost()
                                    .on_click(cx.listener(move |this, _, _, cx| {
                                        this.dispatch(
                                            Action::CancelBrowserDownload(cancel_id.clone()),
                                            cx,
                                        );
                                    })),
                                )
                            })
                            .when(
                                download.status == BrowserDownloadStatus::Complete
                                    && download.file_exists,
                                |actions| {
                                    actions
                                        .child(
                                            Button::new(SharedString::from(format!(
                                                "show-browser-download-{index}"
                                            )))
                                            .label("Show in folder")
                                            .small()
                                            .ghost()
                                            .on_click(cx.listener(move |this, _, _, cx| {
                                                this.dispatch(
                                                    Action::ShowBrowserDownloadInFolder(
                                                        reveal_id.clone(),
                                                    ),
                                                    cx,
                                                );
                                            })),
                                        )
                                        .child(
                                            Button::new(SharedString::from(format!(
                                                "open-browser-download-{index}"
                                            )))
                                            .label("Open")
                                            .small()
                                            .on_click(cx.listener(move |this, _, _, cx| {
                                                this.dispatch(
                                                    Action::OpenBrowserDownload(open_id.clone()),
                                                    cx,
                                                );
                                            })),
                                        )
                                },
                            )
                            .when(!active, |actions| {
                                actions.child(
                                    Button::new(SharedString::from(format!(
                                        "remove-browser-download-{index}"
                                    )))
                                    .icon(IconName::Delete)
                                    .tooltip("Remove from download history")
                                    .small()
                                    .ghost()
                                    .on_click(cx.listener(move |this, _, _, cx| {
                                        this.dispatch(
                                            Action::RemoveBrowserDownload(remove_id.clone()),
                                            cx,
                                        );
                                    })),
                                )
                            }),
                    ),
            )
            .when_some(progress, |row, progress| {
                row.child(
                    div()
                        .h(px(3.0))
                        .overflow_hidden()
                        .rounded_full()
                        .bg(cx.theme().muted)
                        .child(
                            div()
                                .h_full()
                                .w(relative(progress))
                                .rounded_full()
                                .bg(cx.theme().progress_bar),
                        ),
                )
            })
            .into_any_element()
    }

    fn render_computer_use(&mut self, cx: &mut Context<Self>) -> AnyElement {
        let Some(task_id) = self.state.selected_task_id.clone() else {
            return v_flex()
                .flex_1()
                .p_4()
                .child("Select a task to configure Computer Use.")
                .into_any_element();
        };
        let state = self
            .state
            .computer_use
            .get(&task_id)
            .cloned()
            .unwrap_or_default();
        let selected_app_always_allowed =
            state
                .selected_application_id
                .as_ref()
                .is_some_and(|app_id| {
                    self.state
                        .computer_use_settings
                        .always_allowed_app_ids
                        .contains(app_id)
                });
        if !state.available_for_task {
            return v_flex()
                .flex_1()
                .min_h_0()
                .p_4()
                .gap_4()
                .child(section_label("COMPUTER USE", cx))
                .child(
                    div()
                        .p_3()
                        .rounded_lg()
                        .bg(cx.theme().warning.opacity(0.08))
                        .border_1()
                        .border_color(cx.theme().warning.opacity(0.45))
                        .text_xs()
                        .text_color(cx.theme().muted_foreground)
                        .child(
                            "The official app-server accepts dynamic tools when a chat starts. Begin a new chat in codexRS to use Computer Use.",
                        ),
                )
                .child(
                    Button::new("new-computer-task")
                        .label("Start a new chat")
                        .primary()
                        .on_click(cx.listener(|this, _, window, cx| {
                            this.begin_new_chat(window, cx);
                        })),
                )
                .into_any_element();
        }

        let enabled = state.enabled_for_task;
        let task_for_toggle = task_id.clone();
        let task_for_refresh = task_id.clone();
        let task_for_capture = task_id.clone();
        let task_for_auth = task_id.clone();
        let selected_window_id = state.selected_window_id.clone();
        let launching_application_id = state.launching_application_id.clone();
        let application_rows = state
            .applications
            .iter()
            .cloned()
            .enumerate()
            .map(|(index, application)| {
                let task_for_launch = task_id.clone();
                let application_id = application.id.clone();
                let launching =
                    launching_application_id.as_deref() == Some(application.id.as_str());
                let launch_blocked = launching_application_id.is_some() && !launching;
                let display_name = application
                    .display_name
                    .clone()
                    .unwrap_or_else(|| application.id.clone());
                let subtitle = if application.is_running {
                    format!(
                        "Running · {} open window{}",
                        application.window_count,
                        if application.window_count == 1 {
                            ""
                        } else {
                            "s"
                        }
                    )
                } else {
                    "Installed".to_owned()
                };
                h_flex()
                    .p_2()
                    .gap_2()
                    .rounded_md()
                    .border_1()
                    .border_color(cx.theme().border)
                    .child(
                        v_flex()
                            .min_w_0()
                            .flex_1()
                            .gap_1()
                            .child(
                                div()
                                    .truncate()
                                    .text_sm()
                                    .font_weight(gpui::FontWeight::MEDIUM)
                                    .child(display_name),
                            )
                            .child(
                                div()
                                    .truncate()
                                    .text_xs()
                                    .text_color(cx.theme().muted_foreground)
                                    .child(subtitle),
                            ),
                    )
                    .child(
                        Button::new(("launch-computer-app", index))
                            .label(if launching {
                                "Opening…"
                            } else if application.is_running {
                                "Open"
                            } else {
                                "Launch"
                            })
                            .small()
                            .disabled(launching || launch_blocked)
                            .on_click(cx.listener(move |this, _, _, cx| {
                                this.dispatch(
                                    Action::LaunchComputerApp {
                                        task_id: task_for_launch.clone(),
                                        application_id: application_id.clone(),
                                    },
                                    cx,
                                );
                            })),
                    )
                    .into_any_element()
            })
            .collect::<Vec<_>>();
        let window_rows = state
            .windows
            .iter()
            .cloned()
            .enumerate()
            .map(|(index, window)| {
                let selected = selected_window_id.as_deref() == Some(window.id.as_str());
                let task_for_select = task_id.clone();
                let window_id = window.id.clone();
                let window_title = window.title.clone();
                let application_id = window.application_id.clone();
                let subtitle = format!(
                    "{} · {}×{}{}{}",
                    window.application,
                    window.width,
                    window.height,
                    if window.focused { " · focused" } else { "" },
                    if window.minimized {
                        " · minimized"
                    } else {
                        ""
                    }
                );
                v_flex()
                    .p_2()
                    .gap_1()
                    .rounded_md()
                    .border_1()
                    .border_color(if selected {
                        cx.theme().primary
                    } else {
                        cx.theme().border
                    })
                    .child(
                        div()
                            .truncate()
                            .text_sm()
                            .font_weight(gpui::FontWeight::MEDIUM)
                            .child(window.title),
                    )
                    .child(
                        div()
                            .truncate()
                            .text_xs()
                            .text_color(cx.theme().muted_foreground)
                            .child(subtitle),
                    )
                    .child(
                        Button::new(("select-computer-window", index))
                            .label(if selected { "Selected" } else { "Select" })
                            .small()
                            .disabled(selected || window.minimized)
                            .on_click(cx.listener(move |this, _, _, cx| {
                                this.dispatch(
                                    Action::SelectComputerUseWindow {
                                        task_id: task_for_select.clone(),
                                        window_id: window_id.clone(),
                                        title: window_title.clone(),
                                        application_id: application_id.clone(),
                                    },
                                    cx,
                                );
                            })),
                    )
                    .into_any_element()
            })
            .collect::<Vec<_>>();

        v_flex()
            .flex_1()
            .min_h_0()
            .p_4()
            .gap_4()
            .child(section_label("COMPUTER USE", cx))
            .child(
                div()
                    .p_3()
                    .rounded_lg()
                    .bg(cx.theme().warning.opacity(0.08))
                    .border_1()
                    .border_color(cx.theme().warning.opacity(0.45))
                    .text_xs()
                    .text_color(cx.theme().muted_foreground)
                    .child(
                        "ChatGPT asks before it can see or control the selected app. Allow once applies to this task; Always allow also covers future Computer Use sessions.",
                    ),
            )
            .child(
                Button::new("toggle-computer-use")
                    .label(if enabled {
                        "Disable for task"
                    } else {
                        "Enable for task"
                    })
                    .when(enabled, ButtonVariants::danger)
                    .when(!enabled, ButtonVariants::primary)
                    .on_click(cx.listener(move |this, _, _, cx| {
                        this.dispatch(
                            Action::ToggleComputerUse {
                                task_id: task_for_toggle.clone(),
                                enabled: !enabled,
                            },
                            cx,
                        );
                    })),
            )
            .when(enabled, |view| {
                view.child(
                    Button::new("refresh-computer-windows")
                        .label(if state.windows_loading {
                            "Scanning apps…"
                        } else {
                            "Refresh apps and windows"
                        })
                        .small()
                        .disabled(state.windows_loading)
                        .on_click(cx.listener(move |this, _, _, cx| {
                            this.dispatch(
                                Action::RefreshComputerWindows {
                                    task_id: task_for_refresh.clone(),
                                },
                                cx,
                            );
                        })),
                )
            })
            .when(
                enabled
                    && state.windows_loading
                    && state.windows.is_empty()
                    && state.applications.is_empty(),
                |view| {
                view.child(
                    div()
                        .text_xs()
                        .text_color(cx.theme().muted_foreground)
                            .child("Reading the bounded installed-app and window catalog…"),
                )
                },
            )
            .when(enabled && !application_rows.is_empty(), |view| {
                view.child(section_label("INSTALLED APPS", cx)).child(
                    v_flex()
                        .max_h(px(230.0))
                        .overflow_y_scrollbar()
                        .gap_2()
                        .children(application_rows),
                )
            })
            .when(enabled && !window_rows.is_empty(), |view| {
                view.child(section_label("OPEN WINDOWS", cx))
            })
            .when(enabled && !window_rows.is_empty(), |view| {
                view.child(
                    v_flex()
                        .max_h(px(270.0))
                        .overflow_y_scrollbar()
                        .gap_2()
                        .children(window_rows),
                )
            })
            .when_some(state.error.clone(), |view, error| {
                view.child(
                    div()
                        .p_2()
                        .rounded_md()
                        .bg(cx.theme().danger.opacity(0.08))
                        .text_xs()
                        .text_color(cx.theme().danger)
                        .child(error),
                )
            })
            .child(detail_row(
                "Target",
                state
                    .selected_window_title
                    .as_deref()
                    .unwrap_or("No window selected"),
                cx,
            ))
            .when_some(state.last_capture_label.clone(), |view, label| {
                view.child(detail_row("Last capture", &label, cx))
            })
            .child(
                Button::new("test-computer-capture")
                    .label("Test selected-window capture")
                    .small()
                    .disabled(
                        !enabled
                            || state.selected_window_id.is_none()
                            || !state.input_authorized_for_session,
                    )
                    .on_click(cx.listener(move |this, _, _, cx| {
                        this.dispatch(
                            Action::CaptureComputerWindow {
                                task_id: task_for_capture.clone(),
                            },
                            cx,
                        );
                    })),
            )
            .when(
                enabled
                    && state.selected_window_id.is_some()
                    && !state.input_authorized_for_session,
                |view| {
                    view.child(
                        div()
                            .text_xs()
                            .text_color(cx.theme().muted_foreground)
                            .child(
                                "Permission will be requested when ChatGPT first uses this app.",
                            ),
                    )
                },
            )
            .when(
                state.input_authorized_for_session && !selected_app_always_allowed,
                |view| {
                    view.child(
                        Button::new("revoke-computer-input")
                            .label("Revoke task access")
                            .danger()
                            .small()
                            .on_click(cx.listener(move |this, _, _, cx| {
                                this.dispatch(
                                    Action::AuthorizeComputerInputForSession {
                                        task_id: task_for_auth.clone(),
                                        authorized: false,
                                    },
                                    cx,
                                );
                            })),
                    )
                },
            )
            .when(
                state.input_authorized_for_session && selected_app_always_allowed,
                |view| {
                    view.child(
                        v_flex()
                            .gap_2()
                            .child(
                                div()
                                    .text_xs()
                                    .text_color(cx.theme().muted_foreground)
                                    .child(
                                        "This app is always allowed. Remove it in Settings to require approval again.",
                                    ),
                            )
                            .child(
                                Button::new("open-computer-use-settings")
                                    .label("Open Computer use settings")
                                    .small()
                                    .on_click(cx.listener(|this, _, _, cx| {
                                        this.open_settings_section(
                                            SettingsSection::ComputerUse,
                                            cx,
                                        );
                                    })),
                            ),
                    )
                },
            )
            .into_any_element()
    }

    fn render_plugin_directory_tab(
        &self,
        id: &'static str,
        label: &'static str,
        tab: PluginDirectoryTab,
        selected: PluginDirectoryTab,
        cx: &mut Context<Self>,
    ) -> AnyElement {
        div()
            .id(id)
            .h(px(34.0))
            .px_3()
            .flex()
            .items_center()
            .rounded_lg()
            .text_sm()
            .when(pointer_cursors_enabled(cx), |element| {
                element.cursor_pointer()
            })
            .when(selected == tab, |item| {
                item.bg(cx.theme().secondary)
                    .font_weight(gpui::FontWeight::SEMIBOLD)
            })
            .when(selected != tab, |item| {
                item.text_color(cx.theme().muted_foreground)
                    .hover(|style| style.bg(cx.theme().list_hover))
            })
            .child(label)
            .on_click(cx.listener(move |this, _, _, cx| {
                this.dispatch(Action::SelectPluginDirectoryTab(tab), cx);
            }))
            .into_any_element()
    }

