    fn render_plugin_detail_actions(
        &mut self,
        plugin: &PluginCard,
        cx: &mut Context<Self>,
    ) -> AnyElement {
        let plugin_id = plugin.id.clone();
        let plugin_name = plugin.install_name.clone();
        let display_name = plugin.name.clone();
        let marketplace = plugin.marketplace.clone();
        let installed = plugin.installed;
        let enabled = plugin.enabled;
        let pending = self.state.marketplace.pending_plugin_id.as_deref() == Some(&plugin.id);
        let any_pending = self.state.marketplace.pending_plugin_id.is_some()
            || self.state.marketplace.pending_plugin_skill_name.is_some();
        if installed {
            let toggle_id = plugin_id.clone();
            h_flex()
                .w_full()
                .gap_2()
                .child(
                    Button::new(SharedString::from(format!(
                        "plugin-detail-toggle-{plugin_id}"
                    )))
                    .label(if pending {
                        "Updating…"
                    } else if enabled {
                        "Disable"
                    } else {
                        "Enable"
                    })
                    .flex_1()
                    .large()
                    .disabled(any_pending)
                    .on_click(cx.listener(move |this, _, _, cx| {
                        this.dispatch(
                            Action::SetPluginEnabled {
                                plugin_id: toggle_id.clone(),
                                enabled: !enabled,
                            },
                            cx,
                        );
                    })),
                )
                .child(
                    Button::new(SharedString::from(format!(
                        "plugin-detail-remove-{plugin_id}"
                    )))
                    .icon(IconName::Delete)
                    .large()
                    .flex_none()
                    .tooltip("Uninstall plugin")
                    .disabled(any_pending)
                    .danger()
                    .on_click(cx.listener(move |this, _, _, cx| {
                        this.dispatch(
                            Action::UninstallPlugin {
                                plugin_id: plugin_id.clone(),
                            },
                            cx,
                        );
                    })),
                )
                .into_any_element()
        } else {
            Button::new(SharedString::from(format!(
                "plugin-detail-install-{plugin_id}"
            )))
            .label(if pending {
                format!("Installing {display_name}…")
            } else if plugin.installable {
                format!("Install {display_name}")
            } else {
                "Unavailable".to_owned()
            })
            .w_full()
            .large()
            .disabled(any_pending || !plugin.installable)
            .when(plugin.installable, ButtonVariants::primary)
            .on_click(cx.listener(move |this, _, _, cx| {
                this.dispatch(
                    Action::InstallPlugin {
                        plugin_id: plugin_id.clone(),
                        plugin_name: plugin_name.clone(),
                        marketplace: marketplace.clone(),
                    },
                    cx,
                );
            }))
            .into_any_element()
        }
    }

    fn render_plugins_catalog(&mut self, cx: &mut Context<Self>) -> AnyElement {
        let manage_mode = self.state.marketplace.manage_mode;
        let mut sections = if manage_mode {
            let plugin_indices = self
                .state
                .marketplace
                .plugins
                .iter()
                .enumerate()
                .filter(|(_, plugin)| {
                    plugin.installed && plugin_matches_query(plugin, &self.state.marketplace.query)
                })
                .map(|(index, _)| index)
                .collect::<Vec<_>>();
            vec![PluginCatalogSection {
                filter: MarketplaceSectionFilter::Category("Installed".to_owned()),
                title: "Installed".to_owned(),
                plugin_indices,
            }]
        } else {
            build_plugin_catalog_sections(
                &self.state.marketplace.plugins,
                &self.state.marketplace.query,
            )
        };
        if !manage_mode
            && let Some(selected_section) = self.state.marketplace.selected_section.as_ref()
        {
            sections.retain(|section| &section.filter == selected_section);
        }
        let has_plugins = sections
            .iter()
            .any(|section| !section.plugin_indices.is_empty());
        let show_hero = !manage_mode
            && self.state.marketplace.selected_directory_tab == PluginDirectoryTab::CuratedByOpenAi
            && self.state.marketplace.query.trim().is_empty()
            && self.state.marketplace.selected_section.is_none();
        match self.state.marketplace.status {
            Some(LoadStatus::Loading) | None => self.render_catalog_message(
                if manage_mode {
                    "Loading installed plugins…"
                } else {
                    "Loading plugins…"
                },
                "Reading the official app-server catalog.",
                true,
                cx,
            ),
            Some(LoadStatus::Failed) => {
                let message = self
                    .state
                    .marketplace
                    .errors
                    .first()
                    .cloned()
                    .unwrap_or_else(|| "The plugin catalog could not be loaded.".to_owned());
                let (title, hint) = match self.state.marketplace.selected_directory_tab {
                    PluginDirectoryTab::SharedWithYou => (
                        "Shared plugins are unavailable",
                        Some(
                            "This catalog needs ChatGPT workspace plugin access. Sign in with \
                             ChatGPT or verify your workspace access, then retry.",
                        ),
                    ),
                    PluginDirectoryTab::CreatedByMe => (
                        "Created plugins are unavailable",
                        Some(
                            "This catalog needs ChatGPT workspace plugin access. Sign in with \
                             ChatGPT or verify your workspace access, then retry.",
                        ),
                    ),
                    _ => ("Failed to load plugins", None),
                };
                v_flex()
                    .flex_1()
                    .items_center()
                    .justify_center()
                    .gap_3()
                    .child(div().font_weight(gpui::FontWeight::SEMIBOLD).child(title))
                    .child(
                        div()
                            .max_w(px(560.0))
                            .text_sm()
                            .text_color(cx.theme().muted_foreground)
                            .child(message),
                    )
                    .when_some(hint, |error, hint| {
                        error.child(
                            div()
                                .max_w(px(560.0))
                                .text_sm()
                                .text_color(cx.theme().muted_foreground)
                                .child(hint),
                        )
                    })
                    .child(Button::new("retry-plugin-catalog").label("Retry").on_click(
                        cx.listener(|this, _, _, cx| {
                            this.dispatch(Action::RefreshMarketplace, cx);
                        }),
                    ))
                    .into_any_element()
            }
            Some(LoadStatus::Idle | LoadStatus::Ready) if !has_plugins => {
                let filtered = !self.state.marketplace.query.trim().is_empty()
                    || (!manage_mode && self.state.marketplace.selected_section.is_some());
                self.render_catalog_message(
                    if filtered {
                        "No plugins match your filters"
                    } else if manage_mode {
                        "No installed plugins"
                    } else {
                        "No plugins found"
                    },
                    if filtered {
                        "Try a different plugin name, category, or description."
                    } else if manage_mode {
                        "Install a plugin from the directory to manage it here."
                    } else {
                        "No plugin marketplaces returned entries for this host."
                    },
                    false,
                    cx,
                )
            }
            Some(LoadStatus::Idle | LoadStatus::Ready) => {
                let plugins_per_row = if manage_mode { 1 } else { 2 };
                let rendered_sections = sections
                    .into_iter()
                    .map(|section| {
                        let rows = section
                            .plugin_indices
                            .chunks(plugins_per_row)
                            .map(|indices| {
                                let left = indices.first().copied();
                                let right = indices.get(1).copied();
                                h_flex()
                                    .w_full()
                                    .gap_6()
                                    .when_some(left, |row, index| {
                                        row.child(self.render_plugin(index, cx))
                                    })
                                    .when_some(right, |row, index| {
                                        row.child(self.render_plugin(index, cx))
                                    })
                                    .when(!manage_mode && right.is_none(), |row| {
                                        row.child(div().flex_1().min_w_0())
                                    })
                            })
                            .collect::<Vec<_>>();
                        v_flex()
                            .w_full()
                            .when(!manage_mode, |catalog| {
                                catalog.child(
                                    h_flex()
                                        .h(px(42.0))
                                        .items_center()
                                        .border_b_1()
                                        .border_color(cx.theme().border)
                                        .child(
                                            div()
                                                .text_base()
                                                .font_weight(gpui::FontWeight::SEMIBOLD)
                                                .child(section.title),
                                        ),
                                )
                            })
                            .children(rows)
                    })
                    .collect::<Vec<_>>();
                h_flex()
                    .flex_1()
                    .min_h_0()
                    .w_full()
                    .justify_center()
                    .child(
                        v_flex()
                            .w_full()
                            .h_full()
                            .max_w(px(760.0))
                            .flex_1()
                            .min_h_0()
                            .gap_5()
                            .px_5()
                            .pb_8()
                            .overflow_y_scrollbar()
                            .when(show_hero, |catalog| {
                                catalog.child(self.render_plugin_directory_hero(cx))
                            })
                            .children(rendered_sections),
                    )
                    .into_any_element()
            }
        }
    }

