    fn render_mcp_resource_content(
        &self,
        index: usize,
        content: McpResourceContentCard,
        cx: &mut Context<Self>,
    ) -> AnyElement {
        let text = content
            .text
            .as_deref()
            .map(|text| bounded_render_text(text, MAX_RENDERED_MCP_RESOURCE_BYTES));
        let display_truncated = content.truncated
            || content
                .text
                .as_ref()
                .is_some_and(|text| text.len() > MAX_RENDERED_MCP_RESOURCE_BYTES);
        v_flex()
            .id(SharedString::from(format!(
                "mcp-inspector-resource-content-{index}"
            )))
            .p_3()
            .gap_2()
            .rounded_md()
            .bg(cx.theme().secondary)
            .child(
                h_flex()
                    .gap_2()
                    .items_center()
                    .child(
                        div()
                            .flex_1()
                            .min_w_0()
                            .truncate()
                            .font_family(cx.theme().mono_font_family.clone())
                            .text_xs()
                            .child(content.uri),
                    )
                    .when_some(content.mime_type, |row, mime_type| {
                        row.child(
                            div()
                                .text_xs()
                                .text_color(cx.theme().muted_foreground)
                                .child(mime_type),
                        )
                    }),
            )
            .when_some(text, |card, text| {
                card.child(
                    div()
                        .max_h(px(240.0))
                        .overflow_y_scrollbar()
                        .font_family(cx.theme().mono_font_family.clone())
                        .text_xs()
                        .child(text),
                )
            })
            .when_some(content.blob_bytes, |card, bytes| {
                card.child(
                    div()
                        .text_sm()
                        .text_color(cx.theme().muted_foreground)
                        .child(format!("Binary content · {bytes} bytes")),
                )
            })
            .when(
                content.text.is_none() && content.blob_bytes.is_none(),
                |card| {
                    card.child(
                        div()
                            .text_sm()
                            .text_color(cx.theme().muted_foreground)
                            .child("Empty resource content"),
                    )
                },
            )
            .when(display_truncated, |card| {
                card.child(
                    div()
                        .text_xs()
                        .text_color(cx.theme().warning)
                        .child("Content was truncated to the native display limit."),
                )
            })
            .into_any_element()
    }

    fn render_mcp_resource_inspection(
        &self,
        index: usize,
        server_key: String,
        resource: McpResourceCard,
        cx: &mut Context<Self>,
    ) -> AnyElement {
        let title = resource
            .title
            .clone()
            .filter(|title| !title.trim().is_empty())
            .unwrap_or_else(|| resource.name.clone());
        let uri = resource.uri.clone();
        let read_state = self.state.marketplace.mcp_resource_read.clone();
        let selected = read_state.server.as_deref() == Some(server_key.as_str())
            && read_state.uri.as_deref() == Some(uri.as_str());
        let loading = read_state.status == Some(LoadStatus::Loading);
        let selected_status = selected.then_some(read_state.status).flatten();
        let read_error = selected.then_some(read_state.error).flatten();
        let content_count = if selected {
            read_state.contents.len()
        } else {
            0
        };
        let hidden_content_count = content_count.saturating_sub(MAX_RENDERED_MCP_RESOURCE_CONTENTS);
        let contents = if selected {
            read_state
                .contents
                .into_iter()
                .take(MAX_RENDERED_MCP_RESOURCE_CONTENTS)
                .enumerate()
                .map(|(index, content)| self.render_mcp_resource_content(index, content, cx))
                .collect::<Vec<_>>()
        } else {
            Vec::new()
        };
        let action_server = server_key.clone();
        let action_uri = uri.clone();
        let metadata = [
            resource.mime_type,
            resource.size.map(|size| format!("{size} bytes")),
        ]
        .into_iter()
        .flatten()
        .collect::<Vec<_>>()
        .join(" · ");
        v_flex()
            .id(SharedString::from(format!(
                "mcp-inspector-resource-{index}"
            )))
            .p_3()
            .gap_1()
            .rounded_lg()
            .border_1()
            .border_color(cx.theme().border)
            .bg(cx.theme().background)
            .child(
                h_flex()
                    .gap_3()
                    .items_center()
                    .justify_between()
                    .child(
                        div()
                            .flex_1()
                            .min_w_0()
                            .font_weight(gpui::FontWeight::SEMIBOLD)
                            .child(title),
                    )
                    .child(
                        Button::new(SharedString::from(format!("mcp-read-resource-{index}")))
                            .label(match selected_status {
                                Some(LoadStatus::Loading) => "Reading…",
                                Some(LoadStatus::Ready | LoadStatus::Failed) => "Read again",
                                Some(LoadStatus::Idle) | None => "Read",
                            })
                            .small()
                            .disabled(loading)
                            .on_click(cx.listener(move |this, _, _, cx| {
                                this.dispatch(
                                    Action::ReadMcpResource {
                                        server: action_server.clone(),
                                        uri: action_uri.clone(),
                                    },
                                    cx,
                                );
                            })),
                    ),
            )
            .child(
                div()
                    .font_family(cx.theme().mono_font_family.clone())
                    .text_xs()
                    .text_color(cx.theme().muted_foreground)
                    .child(uri),
            )
            .when_some(resource.description, |card, description| {
                card.child(
                    div()
                        .text_sm()
                        .text_color(cx.theme().muted_foreground)
                        .child(description),
                )
            })
            .when(!metadata.is_empty(), |card| {
                card.child(
                    div()
                        .text_xs()
                        .text_color(cx.theme().muted_foreground)
                        .child(metadata),
                )
            })
            .when(selected_status == Some(LoadStatus::Loading), |card| {
                card.child(
                    h_flex()
                        .pt_2()
                        .gap_2()
                        .text_sm()
                        .text_color(cx.theme().muted_foreground)
                        .child(Icon::new(IconName::LoaderCircle).xsmall())
                        .child("Reading resource…"),
                )
            })
            .when_some(read_error, |card, error| {
                card.child(
                    div()
                        .pt_2()
                        .text_sm()
                        .text_color(cx.theme().danger)
                        .child(error),
                )
            })
            .when(
                selected_status == Some(LoadStatus::Ready) && contents.is_empty(),
                |card| {
                    card.child(
                        div()
                            .pt_2()
                            .text_sm()
                            .text_color(cx.theme().muted_foreground)
                            .child("The resource returned no content."),
                    )
                },
            )
            .when(!contents.is_empty(), |card| {
                card.child(v_flex().pt_2().gap_2().children(contents))
            })
            .when(hidden_content_count > 0, |card| {
                card.child(
                    div()
                        .text_xs()
                        .text_color(cx.theme().warning)
                        .child(format!(
                            "{hidden_content_count} additional content items are not rendered."
                        )),
                )
            })
            .into_any_element()
    }

