    fn render_process_manager_table(
        &mut self,
        manager: &ProcessManagerState,
        rows: Vec<AnyElement>,
        cx: &mut Context<Self>,
    ) -> AnyElement {
        let loading = manager.status == LoadStatus::Loading;
        let running_count = manager.terminals.len();
        let header = h_flex()
            .h(px(36.0))
            .px_3()
            .items_center()
            .bg(cx.theme().secondary)
            .text_xs()
            .font_weight(gpui::FontWeight::SEMIBOLD)
            .text_color(cx.theme().muted_foreground)
            .child(div().flex_1().min_w_0().pr_3().child("COMMAND"))
            .child(div().w(px(132.0)).flex_none().pr_3().child("CHAT"))
            .child(div().w(px(64.0)).flex_none().child("PID"))
            .child(div().w(px(68.0)).flex_none().child("CPU"))
            .child(div().w(px(86.0)).flex_none().child("MEMORY"))
            .child(div().w(px(72.0)).flex_none().child("RUNTIME"))
            .child(div().w(px(74.0)).flex_none().text_right().child("ACTIONS"))
            .into_any_element();
        let list = v_flex()
            .max_h(px(360.0))
            .overflow_y_scrollbar()
            .when(loading && running_count == 0, |list| {
                list.child(
                    div()
                        .h(px(204.0))
                        .flex()
                        .items_center()
                        .justify_center()
                        .text_sm()
                        .text_color(cx.theme().muted_foreground)
                        .child("Loading processes…"),
                )
            })
            .when(
                !loading && running_count == 0 && manager.error.is_none(),
                |list| {
                    list.child(
                        div()
                            .h(px(204.0))
                            .flex()
                            .items_center()
                            .justify_center()
                            .px_6()
                            .text_center()
                            .text_sm()
                            .text_color(cx.theme().muted_foreground)
                            .child("No processes started by Codex chats are running"),
                    )
                },
            )
            .children(rows)
            .into_any_element();
        let table = v_flex()
            .w_full()
            .min_w(px(PROCESS_MANAGER_TABLE_MIN_WIDTH))
            .child(header)
            .child(list);

        v_flex()
            .mx_4()
            .mt_3()
            .min_h(px(240.0))
            .rounded_lg()
            .border_1()
            .border_color(cx.theme().border)
            .overflow_x_scrollbar()
            .child(table)
            .into_any_element()
    }

    fn render_process_manager_footer(
        &mut self,
        manager: &ProcessManagerState,
        cx: &mut Context<Self>,
    ) -> AnyElement {
        let loading = manager.status == LoadStatus::Loading;
        let operation_pending = manager.cleaning || !manager.terminating_process_ids.is_empty();
        let running_count = manager.terminals.len();
        let compact = self.shell_width_class != Some(ShellWidthClass::Wide);
        let actions = h_flex()
            .gap_2()
            .when(compact, |actions| actions.flex_wrap())
            .child(
                Button::new("refresh-background-terminals")
                    .label(if loading { "Refreshing…" } else { "Refresh" })
                    .icon(IconName::Redo)
                    .small()
                    .disabled(loading || operation_pending)
                    .on_click(cx.listener(|this, _, _, cx| {
                        this.dispatch(Action::RefreshBackgroundTerminals, cx);
                    })),
            )
            .when(manager.next_cursor.is_some(), |actions| {
                actions.child(
                    Button::new("load-more-background-terminals")
                        .label(if loading { "Loading…" } else { "Load more" })
                        .small()
                        .disabled(loading || operation_pending)
                        .on_click(cx.listener(|this, _, _, cx| {
                            this.dispatch(Action::LoadMoreBackgroundTerminals, cx);
                        })),
                )
            })
            .child(
                Button::new("stop-all-background-terminals")
                    .label(if manager.cleaning {
                        "Stopping…"
                    } else {
                        "Stop all background terminals"
                    })
                    .danger()
                    .small()
                    .disabled(running_count == 0 || operation_pending)
                    .on_click(cx.listener(|this, _, _, cx| {
                        this.dispatch(Action::CleanBackgroundTerminals, cx);
                    })),
            )
            .into_any_element();

        h_flex()
            .px_4()
            .py_3()
            .gap_2()
            .items_center()
            .justify_between()
            .when(compact, |footer| footer.flex_wrap())
            .child(
                div()
                    .text_xs()
                    .text_color(cx.theme().muted_foreground)
                    .child(format!("{running_count} working")),
            )
            .child(actions)
            .into_any_element()
    }

    fn render_keyboard_shortcut_chord(&self, shortcut: &str, cx: &App) -> AnyElement {
        let label = keyboard_shortcut_label(shortcut);
        let mut sequence = h_flex().gap_2().items_center().flex_shrink_0();
        for (chord_index, chord_label) in label.split_whitespace().enumerate() {
            if chord_index > 0 {
                sequence = sequence.child(
                    div()
                        .text_xs()
                        .text_color(cx.theme().muted_foreground)
                        .child("then"),
                );
            }
            let mut chord = h_flex().gap_1().items_center().flex_shrink_0();
            for key in chord_label.split('+') {
                chord = chord.child(
                    div()
                        .min_w(px(24.0))
                        .h(px(24.0))
                        .px_1()
                        .flex()
                        .items_center()
                        .justify_center()
                        .rounded(px(5.0))
                        .border_1()
                        .border_color(cx.theme().border)
                        .bg(cx.theme().secondary)
                        .text_xs()
                        .text_color(cx.theme().muted_foreground)
                        .child(key.to_owned()),
                );
            }
            sequence = sequence.child(chord);
        }
        sequence.into_any_element()
    }

    fn render_keyboard_shortcut_row(
        &self,
        item: &KeyboardShortcutItem,
        row_index: usize,
        cx: &App,
    ) -> AnyElement {
        let mut shortcuts = h_flex().max_w(px(276.0)).gap_2().justify_end().flex_wrap();
        let effective = self.effective_keyboard_shortcuts(item);
        if effective.is_empty() {
            shortcuts = shortcuts.child(
                div()
                    .text_xs()
                    .text_color(cx.theme().muted_foreground)
                    .child("Unassigned"),
            );
        } else {
            for shortcut in effective {
                shortcuts = shortcuts.child(self.render_keyboard_shortcut_chord(&shortcut, cx));
            }
        }
        h_flex()
            .min_h(px(44.0))
            .px_3()
            .py_2()
            .gap_4()
            .items_center()
            .justify_between()
            .when(row_index > 0, |row| {
                row.border_t_1().border_color(cx.theme().border)
            })
            .child(div().flex_1().min_w_0().text_sm().child(item.title))
            .child(shortcuts)
            .into_any_element()
    }

    #[inline(never)]
    fn render_keyboard_shortcuts_modal(&mut self, cx: &mut Context<Self>) -> AnyElement {
        let query = self.keyboard_shortcuts_search.read(cx).value().to_string();
        let mut content = v_flex().gap_5();
        let mut visible_count = 0;
        for group in KeyboardShortcutGroup::ALL {
            let mut items = ACTIVE_KEYBOARD_SHORTCUTS
                .iter()
                .filter(|item| item.group == group)
                .filter(|item| !self.effective_keyboard_shortcuts(item).is_empty())
                .filter(|item| {
                    keyboard_shortcut_settings_matches(
                        item,
                        &self.effective_keyboard_shortcuts(item),
                        &query,
                        false,
                    )
                })
                .collect::<Vec<_>>();
            items.sort_by(|left, right| keyboard_shortcut_stable_order(left, right));
            if items.is_empty() {
                continue;
            }
            visible_count += items.len();
            let mut rows = v_flex()
                .rounded_lg()
                .border_1()
                .border_color(cx.theme().border)
                .overflow_hidden();
            for (row_index, item) in items.into_iter().enumerate() {
                rows = rows.child(self.render_keyboard_shortcut_row(item, row_index, cx));
            }
            content = content.child(
                v_flex()
                    .gap_2()
                    .child(
                        div()
                            .px_1()
                            .text_xs()
                            .font_weight(gpui::FontWeight::SEMIBOLD)
                            .text_color(cx.theme().muted_foreground)
                            .child(group.label()),
                    )
                    .child(rows),
            );
        }
        if visible_count == 0 {
            content = content.child(
                div()
                    .py_1()
                    .text_sm()
                    .text_color(cx.theme().muted_foreground)
                    .child(if query.trim().is_empty() {
                        "No active shortcuts"
                    } else {
                        "No matching shortcuts"
                    }),
            );
        }

        v_flex()
            .w(px(modal_surface_width(self.shell_viewport_width, 600.0)))
            .h(px(modal_surface_max_height(
                self.shell_viewport_height,
                720.0,
            )))
            .rounded(px(16.0))
            .bg(cx.theme().popover)
            .shadow_xl()
            .overflow_hidden()
            .occlude()
            .on_action(cx.listener(|this, _: &Escape, window, cx| {
                this.handle_keyboard_shortcuts_escape(window, cx);
            }))
            .on_any_mouse_down(|_, _, cx| cx.stop_propagation())
            .child(
                h_flex()
                    .px_5()
                    .pt_5()
                    .pb_3()
                    .justify_between()
                    .child(
                        div()
                            .text_lg()
                            .font_weight(gpui::FontWeight::SEMIBOLD)
                            .child("Keyboard shortcuts"),
                    )
                    .child(
                        Button::new("close-keyboard-shortcuts")
                            .icon(IconName::Close)
                            .ghost()
                            .small()
                            .on_click(cx.listener(|this, _, _, cx| {
                                this.close_workspace_modal(cx);
                            })),
                    ),
            )
            .child(
                div()
                    .px_5()
                    .pb_3()
                    .child(Input::new(&self.keyboard_shortcuts_search)),
            )
            .child(
                div()
                    .flex_1()
                    .min_h_0()
                    .overflow_y_scrollbar()
                    .px_5()
                    .pb_5()
                    .child(content),
            )
            .into_any_element()
    }

    fn render_process_manager_modal(&mut self, cx: &mut Context<Self>) -> AnyElement {
        let manager = self.state.process_manager.clone();
        let chat_title = manager
            .task_id
            .as_deref()
            .and_then(|task_id| self.state.tasks.iter().find(|task| task.id == task_id))
            .map_or_else(|| "-".to_owned(), |task| task.title.clone());
        let rows = manager
            .terminals
            .iter()
            .cloned()
            .enumerate()
            .map(|(index, terminal)| {
                let stopping = manager
                    .terminating_process_ids
                    .iter()
                    .any(|process_id| process_id == &terminal.process_id);
                self.render_process_manager_row(
                    index,
                    terminal,
                    &chat_title,
                    stopping,
                    manager.cleaning,
                    cx,
                )
            })
            .collect::<Vec<_>>();
        let header = self.render_process_manager_header(cx);
        let intro = self.render_process_manager_intro(cx);
        let table = self.render_process_manager_table(&manager, rows, cx);
        let error = manager.error.clone().map(|error| {
            div()
                .mx_4()
                .mt_3()
                .p_3()
                .rounded_lg()
                .bg(cx.theme().danger.opacity(0.08))
                .text_sm()
                .text_color(cx.theme().danger)
                .child(error)
                .into_any_element()
        });
        let footer = self.render_process_manager_footer(&manager, cx);

        v_flex()
            .w(px(modal_surface_width(self.shell_viewport_width, 920.0)))
            .max_h(px(modal_surface_max_height(
                self.shell_viewport_height,
                680.0,
            )))
            .rounded(px(16.0))
            .bg(cx.theme().popover)
            .shadow_xl()
            .overflow_hidden()
            .occlude()
            .on_any_mouse_down(|_, _, cx| cx.stop_propagation())
            .child(header)
            .child(intro)
            .child(table)
            .when_some(error, |panel, error| panel.child(error))
            .child(footer)
            .into_any_element()
    }

