    fn render_git_branch_conflict_modal(
        &mut self,
        branch_conflict: Option<codex_core::GitBranchConflictState>,
        cx: &mut Context<Self>,
    ) -> AnyElement {
        let conflict = branch_conflict.unwrap_or_else(|| codex_core::GitBranchConflictState {
            branch: "selected branch".to_owned(),
            create_branch: false,
            paths: Vec::new(),
            truncated: false,
        });
        let title = if conflict.create_branch {
            "Commit changes to create and checkout a new branch"
        } else {
            "Commit changes to switch branch"
        };
        let target = conflict.branch.clone();
        let paths = conflict.paths;
        let path_count = paths.len();
        v_flex()
            .w(px(modal_surface_width(self.shell_viewport_width, 560.0)))
            .p_5()
            .gap_4()
            .rounded(px(16.0))
            .bg(cx.theme().popover)
            .shadow_xl()
            .occlude()
            .on_any_mouse_down(|_, _, cx| cx.stop_propagation())
            .child(
                h_flex()
                    .justify_between()
                    .gap_3()
                    .child(
                        div()
                            .min_w_0()
                            .text_lg()
                            .font_weight(gpui::FontWeight::SEMIBOLD)
                            .child(title),
                    )
                    .child(
                        Button::new("close-branch-conflict-modal")
                            .icon(IconName::Close)
                            .ghost()
                            .small()
                            .on_click(cx.listener(|this, _, _, cx| {
                                this.close_workspace_modal(cx);
                            })),
                    ),
            )
            .child(
                div()
                    .text_sm()
                    .text_color(cx.theme().muted_foreground)
                    .child(format!(
                        "Your changes to the following files would be overwritten by checkout of {target}:"
                    )),
            )
            .child(if paths.is_empty() {
                div()
                    .p_3()
                    .rounded_lg()
                    .border_1()
                    .border_color(cx.theme().border)
                    .bg(cx.theme().background)
                    .text_sm()
                    .text_color(cx.theme().muted_foreground)
                    .child(
                        "Git did not return a file list. Review all uncommitted changes before retrying.",
                    )
                    .into_any_element()
            } else {
                v_flex()
                    .max_h(px(240.0))
                    .overflow_y_scrollbar()
                    .rounded_lg()
                    .border_1()
                    .border_color(cx.theme().border)
                    .bg(cx.theme().background)
                    .children(paths.into_iter().enumerate().map(|(index, path)| {
                        h_flex()
                            .id(SharedString::from(format!(
                                "branch-conflict-path-{index}"
                            )))
                            .min_h(px(34.0))
                            .px_3()
                            .border_b_1()
                            .border_color(cx.theme().border.opacity(0.65))
                            .font_family(cx.theme().mono_font_family.clone())
                            .text_xs()
                            .child(display_path(&path))
                    }))
                    .into_any_element()
            })
            .when(conflict.truncated, |panel| {
                panel.child(
                    div()
                        .text_xs()
                        .text_color(cx.theme().warning)
                        .child(format!(
                            "Showing the first {path_count} conflicting paths."
                        )),
                )
            })
            .child(
                h_flex()
                    .justify_end()
                    .gap_2()
                    .child(
                        Button::new("cancel-branch-conflict")
                            .label("Cancel")
                            .on_click(cx.listener(|this, _, _, cx| {
                                this.close_workspace_modal(cx);
                            })),
                    )
                    .child(
                        Button::new("review-branch-conflict")
                            .label("Review changes")
                            .primary()
                            .on_click(cx.listener(|this, _, _, cx| {
                                this.close_workspace_modal(cx);
                                this.navigate(MainRoute::Tasks, cx);
                                this.dispatch(Action::ShowInspector(InspectorPane::Changes), cx);
                            })),
                    ),
            )
            .into_any_element()
    }

