    fn render_git_commit_modal(&mut self, cx: &mut Context<Self>) -> AnyElement {
        let commit_pending = self.state.git.pending_commit.is_some();
        let include_unstaged = self.state.git_include_unstaged;
        let commit_message = self.commit_message.read(cx).value().to_string();
        let has_commit_changes = self.state.git.changed_files > 0;
        let selected_changes = if include_unstaged {
            has_commit_changes
        } else {
            self.state.git.staged_files > 0
        };
        let generation_available =
            !commit_message.trim().is_empty() || self.state.connection == ConnectionStatus::Online;
        let commit_disabled = commit_pending
            || !selected_changes
            || commit_message.chars().count() > MAX_GIT_COMMIT_MESSAGE_CHARS
            || commit_message.contains('\0')
            || !generation_available;
        let push_disabled = commit_pending || self.state.git.ahead == 0;
        let (additions, deletions) =
            self.state
                .git
                .files
                .iter()
                .fold((0_u64, 0_u64), |(additions, deletions), file| {
                    let staged_additions = u64::from(file.staged_additions);
                    let staged_deletions = u64::from(file.staged_deletions);
                    if include_unstaged {
                        (
                            additions
                                .saturating_add(staged_additions)
                                .saturating_add(u64::from(file.unstaged_additions)),
                            deletions
                                .saturating_add(staged_deletions)
                                .saturating_add(u64::from(file.unstaged_deletions)),
                        )
                    } else {
                        (
                            additions.saturating_add(staged_additions),
                            deletions.saturating_add(staged_deletions),
                        )
                    }
                });
        let header = self.render_git_commit_header(
            self.state
                .git
                .branch
                .clone()
                .unwrap_or_else(|| "-".to_owned()),
            additions,
            deletions,
            cx,
        );
        let fields = has_commit_changes
            .then(|| self.render_git_commit_fields(include_unstaged, commit_pending, cx));
        let error = self.state.git.commit_error.clone().map(|error| {
            div()
                .px_3()
                .pb_3()
                .text_sm()
                .text_color(cx.theme().danger)
                .child(error)
                .into_any_element()
        });
        let actions = self.render_git_commit_actions(commit_disabled, push_disabled, cx);

        v_flex()
            .w(px(modal_surface_width(self.shell_viewport_width, 420.0)))
            .max_w(px(560.0))
            .rounded(px(12.0))
            .bg(cx.theme().popover)
            .shadow_xl()
            .occlude()
            .overflow_hidden()
            .on_any_mouse_down(|_, _, cx| cx.stop_propagation())
            .child(header)
            .when_some(fields, |panel, fields| panel.child(fields))
            .when_some(error, |panel, error| panel.child(error))
            .child(actions)
            .into_any_element()
    }

