fn composer_slash_command_for_prefix(
    prefix: &str,
    has_selected_task: bool,
    init_available: bool,
    chat_available: bool,
) -> Option<&'static str> {
    if prefix.is_empty() {
        return None;
    }
    const COMMANDS: [&str; 13] = [
        "/chat",
        "/compact",
        "/feedback",
        "/fork",
        "/goal",
        "/init",
        "/mcp",
        "/model",
        "/new",
        "/plan",
        "/project",
        "/reasoning",
        "/status",
    ];
    let mut matches = COMMANDS
        .into_iter()
        .filter(|command| {
            if *command == "/chat" {
                chat_available
            } else if matches!(*command, "/mcp" | "/project" | "/status") {
                true
            } else if *command == "/init" {
                init_available
            } else {
                has_selected_task
            }
        })
        .filter(|command| command.starts_with(prefix));
    let first = matches.next()?;
    if prefix == first || prefix == "/" || matches.next().is_none() {
        Some(first)
    } else {
        None
    }
}

fn project_trigger_matches(query: &str) -> bool {
    let query = query.trim().to_ascii_lowercase();
    query.is_empty()
        || "project".starts_with(&query)
        || "work-in-a-project".starts_with(&query.replace(' ', "-"))
}

fn project_workspace_options(
    new_chat_cwd: Option<&Path>,
    selected_task_id: Option<&str>,
    tasks: &[TaskSummary],
) -> Vec<PathBuf> {
    let mut paths = Vec::with_capacity(MAX_COMPOSER_OPTIONS.min(tasks.len().saturating_add(1)));
    let mut seen = HashSet::new();
    let mut push = |path: &Path| {
        if paths.len() >= MAX_COMPOSER_OPTIONS || !path.is_absolute() {
            return;
        }
        let display = display_path(path);
        let key = if cfg!(windows) {
            display.to_lowercase()
        } else {
            display
        };
        if seen.insert(key) {
            paths.push(path.to_path_buf());
        }
    };

    if let Some(path) = new_chat_cwd {
        push(path);
    }
    if let Some(selected_task_id) = selected_task_id
        && let Some(task) = tasks.iter().find(|task| task.id == selected_task_id)
    {
        push(&task.cwd);
    }
    for task in tasks {
        push(&task.cwd);
    }
    paths
}

fn composer_file_query(value: &str, cursor: usize) -> Option<ComposerFileQuery> {
    let mut cursor = cursor.min(value.len());
    while !value.is_char_boundary(cursor) {
        cursor = cursor.saturating_sub(1);
    }
    let prefix = &value[..cursor];
    let start = prefix.rfind('@')?;
    let preceding = prefix[..start].chars().next_back();
    if preceding.is_some_and(|character| {
        !character.is_whitespace() && !matches!(character, '(' | '[' | '{')
    }) {
        return None;
    }
    let query = &prefix[start + 1..];
    if query.len() > MAX_FUZZY_FILE_QUERY_BYTES || query.chars().any(char::is_whitespace) {
        return None;
    }
    let end = value[cursor..]
        .char_indices()
        .find_map(|(offset, character)| character.is_whitespace().then_some(cursor + offset))
        .unwrap_or(value.len());
    Some(ComposerFileQuery {
        range: start..end,
        query: query.to_owned(),
    })
}

fn replace_composer_file_query(
    value: &str,
    range: &Range<usize>,
    replacement: &str,
) -> (String, usize) {
    if range.start > range.end
        || range.end > value.len()
        || !value.is_char_boundary(range.start)
        || !value.is_char_boundary(range.end)
    {
        return (value.to_owned(), value.len());
    }
    let prefix = &value[..range.start];
    let mut suffix = &value[range.end..];
    if replacement.is_empty()
        && prefix.chars().next_back().is_some_and(char::is_whitespace)
        && suffix.chars().next().is_some_and(char::is_whitespace)
        && let Some(first) = suffix.chars().next()
    {
        suffix = &suffix[first.len_utf8()..];
    }
    let mut output = String::with_capacity(
        prefix
            .len()
            .saturating_add(replacement.len() + suffix.len()),
    );
    output.push_str(prefix);
    output.push_str(replacement);
    let cursor = output.len();
    output.push_str(suffix);
    (output, cursor)
}

fn input_position_for_offset(value: &str, offset: usize) -> Position {
    let mut offset = offset.min(value.len());
    while !value.is_char_boundary(offset) {
        offset = offset.saturating_sub(1);
    }
    let prefix = &value[..offset];
    let line = prefix.bytes().filter(|byte| *byte == b'\n').count();
    let character = prefix
        .rsplit_once('\n')
        .map_or(prefix, |(_, line)| line)
        .chars()
        .count();
    Position::new(line as u32, character as u32)
}

fn relative_file_search_display(path: &Path) -> String {
    path.components()
        .filter_map(|component| match component {
            std::path::Component::Normal(value) => Some(value.to_string_lossy().into_owned()),
            _ => None,
        })
        .collect::<Vec<_>>()
        .join("/")
}

fn section_label(label: &'static str, cx: &App) -> AnyElement {
    div()
        .text_xs()
        .font_weight(gpui::FontWeight::SEMIBOLD)
        .text_color(cx.theme().muted_foreground)
        .child(label)
        .into_any_element()
}

fn detail_row(label: &str, value: &str, cx: &App) -> AnyElement {
    h_flex()
        .gap_3()
        .justify_between()
        .child(
            div()
                .text_xs()
                .text_color(cx.theme().muted_foreground)
                .child(label.to_owned()),
        )
        .child(
            div()
                .min_w_0()
                .truncate()
                .text_xs()
                .font_weight(gpui::FontWeight::MEDIUM)
                .child(value.to_owned()),
        )
        .into_any_element()
}

fn metric_badge(label: &str, value: usize, cx: &App) -> AnyElement {
    v_flex()
        .flex_1()
        .min_w_0()
        .p_2()
        .rounded_md()
        .border_1()
        .border_color(cx.theme().border)
        .bg(cx.theme().background)
        .child(
            div()
                .text_xs()
                .text_color(cx.theme().muted_foreground)
                .truncate()
                .child(label.to_owned()),
        )
        .child(
            div()
                .text_sm()
                .font_weight(gpui::FontWeight::SEMIBOLD)
                .child(value.to_string()),
        )
        .into_any_element()
}

fn default_branch_name(title: &str, prefix: &str) -> String {
    let mut slug = title
        .chars()
        .flat_map(char::to_lowercase)
        .map(|character| {
            if character.is_ascii_alphanumeric() || matches!(character, '-' | '_') {
                character
            } else {
                '-'
            }
        })
        .take(64)
        .collect::<String>();
    while slug.contains("--") {
        slug = slug.replace("--", "-");
    }
    let slug = slug.trim_matches('-');
    format!(
        "{}{}",
        prefix,
        if slug.is_empty() { "new-branch" } else { slug }
    )
}

fn default_worktree_path(root: &Path, branch: &str) -> PathBuf {
    let repository = root
        .file_name()
        .and_then(|name| name.to_str())
        .filter(|name| !name.is_empty())
        .unwrap_or("repo");
    let mut slug = branch
        .chars()
        .map(|character| {
            if character.is_ascii_alphanumeric() || matches!(character, '-' | '_') {
                character
            } else {
                '-'
            }
        })
        .take(80)
        .collect::<String>();
    while slug.contains("--") {
        slug = slug.replace("--", "-");
    }
    let slug = slug.trim_matches('-');
    let slug = if slug.is_empty() { "worktree" } else { slug };
    root.parent()
        .unwrap_or_else(|| Path::new(""))
        .join(format!("{repository}-{slug}"))
}

fn display_path(path: &Path) -> String {
    let rendered = path.display().to_string();
    #[cfg(windows)]
    {
        if let Some(path) = rendered.strip_prefix(r"\\?\UNC\") {
            return format!(r"\\{path}");
        }
        if let Some(path) = rendered.strip_prefix(r"\\?\") {
            return path.to_owned();
        }
    }
    rendered
}

fn build_plugin_catalog_sections(
    plugins: &[PluginCard],
    raw_query: &str,
) -> Vec<PluginCatalogSection> {
    let matching_indices = plugins
        .iter()
        .enumerate()
        .filter(|(_, plugin)| plugin_matches_query(plugin, raw_query))
        .map(|(index, _)| index)
        .collect::<Vec<_>>();

    let mut sections = Vec::new();
    let mut featured = matching_indices
        .iter()
        .copied()
        .filter(|index| plugins[*index].featured)
        .collect::<Vec<_>>();
    featured.sort_by_key(|index| (plugins[*index].featured_rank.unwrap_or(usize::MAX), *index));
    if !featured.is_empty() {
        sections.push(PluginCatalogSection {
            filter: MarketplaceSectionFilter::Featured,
            title: "Featured".to_owned(),
            plugin_indices: featured,
        });
    }

    let mut categories = Vec::<(String, Vec<usize>)>::new();
    for index in matching_indices {
        let category = plugins[index]
            .category
            .as_deref()
            .map(str::trim)
            .filter(|category| !category.is_empty())
            .unwrap_or("Other");
        if let Some((_, indices)) = categories
            .iter_mut()
            .find(|(existing, _)| existing.eq_ignore_ascii_case(category))
        {
            indices.push(index);
        } else {
            categories.push((category.to_owned(), vec![index]));
        }
    }
    categories.sort_by(|(left, _), (right, _)| {
        left.eq_ignore_ascii_case("Other")
            .cmp(&right.eq_ignore_ascii_case("Other"))
            .then_with(|| left.to_lowercase().cmp(&right.to_lowercase()))
    });
    sections.extend(
        categories
            .into_iter()
            .map(|(title, plugin_indices)| PluginCatalogSection {
                filter: MarketplaceSectionFilter::Category(title.clone()),
                title,
                plugin_indices,
            }),
    );
    sections
}

fn plugin_matches_query(plugin: &PluginCard, raw_query: &str) -> bool {
    let query = raw_query.trim().to_lowercase();
    query.is_empty()
        || plugin.name.to_lowercase().contains(&query)
        || plugin.description.to_lowercase().contains(&query)
        || plugin
            .category
            .as_deref()
            .is_some_and(|category| category.to_lowercase().contains(&query))
        || plugin
            .developer
            .as_deref()
            .is_some_and(|developer| developer.to_lowercase().contains(&query))
}

const fn skill_scope_label(scope: SkillScope) -> &'static str {
    match scope {
        SkillScope::User => "User",
        SkillScope::Repo => "Project",
        SkillScope::System => "Built-in",
        SkillScope::Admin => "Managed",
    }
}

fn effort_label(effort: &str) -> String {
    match effort {
        "low" => "Low".to_owned(),
        "medium" => "Medium".to_owned(),
        "high" => "High".to_owned(),
        "xhigh" => "Extra high".to_owned(),
        "max" => "Max".to_owned(),
        "ultra" => "Ultra".to_owned(),
        other => humanize_identifier(other),
    }
}

fn mcp_auth_status_label(status: McpAuthStatus) -> Option<&'static str> {
    match status {
        McpAuthStatus::Unknown => None,
        McpAuthStatus::Unsupported => Some("Auth unsupported"),
        McpAuthStatus::NotLoggedIn => Some("Not authenticated"),
        McpAuthStatus::BearerToken => Some("Authenticated (API key)"),
        McpAuthStatus::OAuth => Some("Authenticated (OAuth)"),
    }
}

fn is_stable_composer_photo(path: &Path) -> bool {
    path.extension()
        .and_then(|extension| extension.to_str())
        .is_some_and(|extension| {
            matches!(
                extension.to_ascii_lowercase().as_str(),
                "png" | "jpg" | "jpeg" | "gif" | "webp"
            )
        })
}

fn reasoning_effort_target<'a>(
    efforts: &'a [ReasoningEffortOption],
    selected: &str,
    step: ReasoningEffortStep,
) -> Option<&'a str> {
    let selected_index = efforts.iter().position(|effort| effort.id == selected)?;
    let target_index = match step {
        ReasoningEffortStep::Increase => (selected_index + 1).min(efforts.len() - 1),
        ReasoningEffortStep::Decrease => selected_index.saturating_sub(1),
        ReasoningEffortStep::Cycle => {
            if selected_index + 1 == efforts.len() {
                0
            } else {
                selected_index + 1
            }
        }
    };
    let target = efforts.get(target_index)?.id.as_str();
    (target != selected).then_some(target)
}

fn service_tier_label(id: &str, name: &str) -> String {
    let normalized_name = name.trim().to_ascii_lowercase();
    match (id, normalized_name.as_str()) {
        ("priority" | "fast", _) | (_, "fast" | "priority") => "Fast".to_owned(),
        ("ultrafast", _) | (_, "ultrafast") => "Ultrafast".to_owned(),
        _ => name.to_owned(),
    }
}

fn composer_catalog_match_score(query: &str, values: impl IntoIterator<Item = String>) -> usize {
    values
        .into_iter()
        .map(|value| value.to_lowercase())
        .map(|value| {
            if value == query {
                3
            } else if value.starts_with(query) {
                2
            } else if value.contains(query) {
                1
            } else {
                0
            }
        })
        .max()
        .unwrap_or_default()
}

fn composer_file_search_max_height(viewport_height: f32) -> f32 {
    (viewport_height - 400.0).clamp(160.0, 360.0)
}

fn composer_plugin_commands(query: &str, plugins: &[PluginCard]) -> Vec<ComposerCatalogMention> {
    let search = query.trim().to_lowercase();
    let mut matches = plugins
        .iter()
        .filter(|plugin| composer_plugin_is_mentionable(plugin))
        .filter_map(|plugin| {
            let title = composer_plugin_display_name(plugin);
            if plugin.id.is_empty() || title.is_empty() {
                return None;
            }
            let score = composer_catalog_match_score(
                &search,
                [
                    plugin.install_name.clone(),
                    plugin.name.clone(),
                    title.clone(),
                    format!("@{title}"),
                ],
            );
            (search.is_empty() || score > 0).then(|| {
                (
                    score,
                    ComposerCatalogMention {
                        id: plugin.id.clone(),
                        title,
                        description: if plugin.description.trim().is_empty() {
                            plugin.marketplace.clone()
                        } else {
                            plugin.description.clone()
                        },
                        kind: ComposerCatalogMentionKind::Plugin,
                    },
                )
            })
        })
        .collect::<Vec<_>>();
    if !search.is_empty() {
        matches.sort_by(|(left_score, left), (right_score, right)| {
            right_score
                .cmp(left_score)
                .then_with(|| left.title.to_lowercase().cmp(&right.title.to_lowercase()))
                .then_with(|| left.id.cmp(&right.id))
        });
    }
    let mut seen = HashSet::new();
    matches
        .into_iter()
        .map(|(_, command)| command)
        .filter(|command| seen.insert(command.id.clone()))
        .take(MAX_COMPOSER_OPTIONS)
        .collect()
}

fn normalized_app_plugin_key(value: &str) -> String {
    value
        .trim()
        .chars()
        .filter(|character| character.is_ascii_alphanumeric())
        .flat_map(char::to_lowercase)
        .collect()
}

fn composer_app_commands(
    query: &str,
    apps: &[AppCard],
    plugins: &[PluginCard],
) -> Vec<ComposerCatalogMention> {
    let search = query.trim().to_lowercase();
    let plugin_keys = plugins
        .iter()
        .filter(|plugin| composer_plugin_is_mentionable(plugin))
        .flat_map(|plugin| {
            [
                normalized_app_plugin_key(&plugin.install_name),
                normalized_app_plugin_key(&plugin.name),
            ]
        })
        .filter(|key| !key.is_empty())
        .collect::<HashSet<_>>();
    let mut matches = apps
        .iter()
        .filter(|app| {
            app.is_accessible && app.enabled && !app.id.is_empty() && !app.name.is_empty()
        })
        .filter(|app| {
            std::iter::once(&app.name)
                .chain(app.plugin_display_names.iter())
                .map(|name| normalized_app_plugin_key(name))
                .all(|key| key.is_empty() || !plugin_keys.contains(&key))
        })
        .filter_map(|app| {
            let score = composer_catalog_match_score(
                &search,
                std::iter::once(app.name.clone())
                    .chain(std::iter::once(format!("@{}", app.name)))
                    .chain(app.plugin_display_names.iter().cloned()),
            );
            (search.is_empty() || score > 0).then(|| {
                (
                    score,
                    ComposerCatalogMention {
                        id: app.id.clone(),
                        title: app.name.clone(),
                        description: app.description.clone(),
                        kind: ComposerCatalogMentionKind::App,
                    },
                )
            })
        })
        .collect::<Vec<_>>();
    if !search.is_empty() {
        matches.sort_by(|(left_score, left), (right_score, right)| {
            right_score
                .cmp(left_score)
                .then_with(|| left.title.to_lowercase().cmp(&right.title.to_lowercase()))
                .then_with(|| left.id.cmp(&right.id))
        });
    }
    let limit = if search.is_empty() {
        3
    } else {
        MAX_COMPOSER_OPTIONS
    };
    let mut seen = HashSet::new();
    matches
        .into_iter()
        .map(|(_, command)| command)
        .filter(|command| seen.insert(command.id.clone()))
        .take(limit)
        .collect()
}

fn composer_desktop_app_commands(
    query: &str,
    applications: &[ComputerApplicationState],
    plugins: &[PluginCard],
) -> Vec<ComposerCatalogMention> {
    let search = query.trim().to_lowercase();
    if search.is_empty()
        || !plugins.iter().any(|plugin| {
            plugin.install_name.eq_ignore_ascii_case("computer-use")
                && composer_plugin_is_mentionable(plugin)
        })
    {
        return Vec::new();
    }
    let mut matches = applications
        .iter()
        .filter_map(|application| {
            let title = application
                .display_name
                .as_deref()
                .unwrap_or(&application.id)
                .trim();
            (!application.id.is_empty()
                && !title.is_empty()
                && title
                    .to_lowercase()
                    .split_whitespace()
                    .any(|word| word.starts_with(&search)))
            .then(|| ComposerCatalogMention {
                id: application.id.clone(),
                title: title.to_owned(),
                description: "Computer use".to_owned(),
                kind: ComposerCatalogMentionKind::DesktopApp,
            })
        })
        .collect::<Vec<_>>();
    matches.sort_by(|left, right| {
        left.title
            .to_lowercase()
            .cmp(&right.title.to_lowercase())
            .then_with(|| left.id.cmp(&right.id))
    });
    matches.truncate(8);
    matches
}

fn render_composer_catalog_section(
    title: &'static str,
    id_prefix: &'static str,
    commands: Vec<ComposerCatalogMention>,
    selection_offset: usize,
    selected: usize,
    cx: &mut Context<WorkspaceView>,
) -> Option<AnyElement> {
    if commands.is_empty() {
        return None;
    }
    let rows = commands
        .into_iter()
        .enumerate()
        .map(|(index, command)| {
            let selection_index = selection_offset + index;
            let icon = match command.kind {
                ComposerCatalogMentionKind::Plugin => IconName::Bot,
                ComposerCatalogMentionKind::DesktopApp => IconName::Frame,
                ComposerCatalogMentionKind::App => IconName::Globe,
            };
            let description = command.description;
            h_flex()
                .id(SharedString::from(format!("{id_prefix}-{index}")))
                .w_full()
                .p_2()
                .gap_3()
                .items_center()
                .rounded_md()
                .when(pointer_cursors_enabled(cx), |element| {
                    element.cursor_pointer()
                })
                .when(selection_index == selected, |row| {
                    row.bg(cx.theme().list_active)
                })
                .hover(|style| style.bg(cx.theme().list_hover))
                .child(
                    Icon::new(icon)
                        .small()
                        .text_color(cx.theme().muted_foreground),
                )
                .child(
                    v_flex()
                        .min_w_0()
                        .flex_1()
                        .child(div().text_sm().truncate().child(command.title))
                        .when(!description.is_empty(), |content| {
                            content.child(
                                div()
                                    .text_xs()
                                    .truncate()
                                    .text_color(cx.theme().muted_foreground)
                                    .child(description),
                            )
                        }),
                )
                .on_click(cx.listener(move |this, _, window, cx| {
                    this.select_composer_file_result(selection_index, window, cx);
                }))
                .into_any_element()
        })
        .collect::<Vec<_>>();
    Some(
        v_flex()
            .w_full()
            .gap_1()
            .child(
                div()
                    .px_2()
                    .pt_1()
                    .text_xs()
                    .font_weight(gpui::FontWeight::SEMIBOLD)
                    .text_color(cx.theme().muted_foreground)
                    .child(title),
            )
            .children(rows)
            .into_any_element(),
    )
}

fn composer_skill_commands(query: &str, skills: &[SkillCard]) -> Vec<ComposerSkillCommand> {
    let Some(search) = query.strip_prefix('/') else {
        return Vec::new();
    };
    let search = search.to_lowercase();
    let mut matches = skills
        .iter()
        .filter(|skill| {
            skill.enabled
                && skill.path.is_absolute()
                && !skill.name.is_empty()
                && !skill.display_name.is_empty()
        })
        .filter(|skill| {
            let command_id = format!("skill:{}", skill.path.display()).to_lowercase();
            search.is_empty()
                || skill.name.to_lowercase().contains(&search)
                || skill.display_name.to_lowercase().contains(&search)
                || command_id.contains(&search)
        })
        .collect::<Vec<_>>();
    matches.sort_by(|left, right| {
        left.name
            .to_lowercase()
            .cmp(&right.name.to_lowercase())
            .then_with(|| left.path.cmp(&right.path))
    });
    let mut seen = HashSet::new();
    matches
        .into_iter()
        .filter(|skill| seen.insert(skill.path.clone()))
        .take(MAX_COMPOSER_OPTIONS)
        .map(|skill| ComposerSkillCommand {
            path: skill.path.clone(),
            title: skill.display_name.clone(),
            description: skill.description.clone(),
            scope: skill.scope,
        })
        .collect()
}

fn composer_at_skill_commands(query: &str, skills: &[SkillCard]) -> Vec<ComposerSkillCommand> {
    let search = query.trim().to_lowercase();
    if search.is_empty() {
        return Vec::new();
    }
    let slash_query = format!("/{search}");
    composer_skill_commands(&slash_query, skills)
}

fn composer_skill_command_for_query(query: &str, skills: &[SkillCard]) -> Option<String> {
    let search = query.strip_prefix('/')?.to_lowercase();
    let mut matches = skills.iter().filter(|skill| {
        let command_id = format!("skill:{}", skill.path.display()).to_lowercase();
        let name = skill.name.to_lowercase();
        let title = skill.display_name.to_lowercase();
        skill.enabled
            && skill.path.is_absolute()
            && !skill.name.is_empty()
            && (search == command_id
                || search == name
                || search == title
                || search == title.replace(' ', "-"))
    });
    let skill = matches.next()?;
    matches
        .next()
        .is_none()
        .then(|| format!("/skill:{}", skill.path.display()))
}

fn composer_service_tier_commands(
    query: &str,
    tiers: &[ServiceTierOption],
    selected_tier: Option<&str>,
) -> Vec<ComposerServiceTierCommand> {
    let Some(search) = query.strip_prefix('/') else {
        return Vec::new();
    };
    let search = search.to_ascii_lowercase();
    tiers
        .iter()
        .filter(|tier| !tier.id.is_empty())
        .filter_map(|tier| {
            let title = service_tier_label(&tier.id, &tier.name);
            let command_id = format!("service-tier:{}", tier.id);
            let matches = search.is_empty()
                || command_id.to_ascii_lowercase().starts_with(&search)
                || title.to_ascii_lowercase().starts_with(&search);
            matches.then(|| {
                let selected = selected_tier == Some(tier.id.as_str());
                ComposerServiceTierCommand {
                    tier_id: tier.id.clone(),
                    description: if selected {
                        format!("Turn off {title} and return to standard speed")
                    } else {
                        tier.description.clone()
                    },
                    title,
                    selected,
                }
            })
        })
        .take(MAX_COMPOSER_OPTIONS)
        .collect()
}

fn composer_service_tier_command_for_query(
    query: &str,
    tiers: &[ServiceTierOption],
) -> Option<String> {
    let search = query.strip_prefix('/')?.to_ascii_lowercase();
    let mut matches = tiers.iter().filter(|tier| {
        let command_id = format!("service-tier:{}", tier.id).to_ascii_lowercase();
        let title = service_tier_label(&tier.id, &tier.name).to_ascii_lowercase();
        !tier.id.is_empty()
            && (search == command_id || search == title || search == title.replace(' ', "-"))
    });
    let tier = matches.next()?;
    matches
        .next()
        .is_none()
        .then(|| format!("/service-tier:{}", tier.id))
}

fn humanize_identifier(value: &str) -> String {
    let mut label = value.replace(['-', '_'], " ");
    if let Some(first) = label.get_mut(0..1) {
        first.make_ascii_uppercase();
    }
    label
}

#[derive(Debug, Default, PartialEq, Eq)]
struct ThreadFindMatches {
    item_indices: Vec<usize>,
    is_capped: bool,
}

fn bounded_thread_find_query(value: &str) -> String {
    if value.len() <= MAX_THREAD_FIND_QUERY_BYTES {
        return value.to_owned();
    }
    let mut end = MAX_THREAD_FIND_QUERY_BYTES;
    while end > 0 && !value.is_char_boundary(end) {
        end -= 1;
    }
    value[..end].to_owned()
}

fn bounded_settings_search_query(value: &str) -> String {
    if value.len() <= MAX_SETTINGS_SEARCH_QUERY_BYTES {
        return value.to_owned();
    }
    let mut end = MAX_SETTINGS_SEARCH_QUERY_BYTES;
    while end > 0 && !value.is_char_boundary(end) {
        end -= 1;
    }
    value[..end].to_owned()
}

fn bounded_keyboard_shortcut_search_query(value: &str) -> String {
    if value.len() <= MAX_KEYBOARD_SHORTCUT_SEARCH_QUERY_BYTES {
        return value.to_owned();
    }
    let mut end = MAX_KEYBOARD_SHORTCUT_SEARCH_QUERY_BYTES;
    while end > 0 && !value.is_char_boundary(end) {
        end -= 1;
    }
    value[..end].to_owned()
}

#[cfg(test)]
fn keyboard_shortcut_search_matches(item: &KeyboardShortcutItem, raw_query: &str) -> bool {
    let query = bounded_keyboard_shortcut_search_query(raw_query);
    let query = query.trim().to_lowercase();
    if query.is_empty() {
        return true;
    }
    [item.id, item.title, item.description]
        .into_iter()
        .map(str::to_lowercase)
        .any(|candidate| {
            query
                .split_whitespace()
                .all(|term| candidate.contains(term) || is_fuzzy_subsequence(term, &candidate))
        })
}

fn keyboard_shortcut_settings_matches(
    item: &KeyboardShortcutItem,
    shortcuts: &[String],
    raw_query: &str,
    search_by_keys: bool,
) -> bool {
    let query = bounded_keyboard_shortcut_search_query(raw_query);
    let query = query.trim().to_lowercase();
    if query.is_empty() {
        return true;
    }
    if search_by_keys {
        return shortcuts.iter().any(|shortcut| {
            let label = keyboard_shortcut_label(shortcut).trim().to_lowercase();
            label == query || label.starts_with(&format!("{query} "))
        });
    }
    let mut candidates = shortcuts
        .iter()
        .map(|shortcut| {
            keyboard_shortcut_label(shortcut)
                .replace(['+', ' '], " ")
                .to_lowercase()
        })
        .collect::<Vec<_>>();
    candidates.extend(
        [item.id, item.title, item.description]
            .into_iter()
            .map(str::to_lowercase),
    );
    let query_terms = query.replace(['+', ' '], " ");
    let query_terms = query_terms.split_whitespace().collect::<Vec<_>>();
    candidates.into_iter().any(|candidate| {
        query_terms
            .iter()
            .all(|term| candidate.contains(term) || is_fuzzy_subsequence(term, &candidate))
    })
}

fn is_fuzzy_subsequence(needle: &str, haystack: &str) -> bool {
    if needle.is_empty() {
        return true;
    }
    let mut needle = needle.chars();
    let mut expected = needle.next();
    for candidate in haystack.chars() {
        if expected == Some(candidate) {
            expected = needle.next();
            if expected.is_none() {
                return true;
            }
        }
    }
    false
}

fn keyboard_shortcut_label(shortcut: &str) -> String {
    if cfg!(target_os = "macos") {
        shortcut.replace("CmdOrCtrl", "Command")
    } else {
        shortcut.replace("CmdOrCtrl", "Ctrl")
    }
}

const FIXED_KEYBOARD_SHORTCUTS: &[(&str, &str)] =
    &[("Find Next", "F3"), ("Find Previous", "Shift+F3")];

fn canonical_shortcut_key(raw_key: &str) -> Option<String> {
    let raw_key = raw_key.trim();
    if raw_key.is_empty() || raw_key.len() > 32 || raw_key.chars().any(char::is_control) {
        return None;
    }
    let lower = raw_key.to_ascii_lowercase();
    let key = match lower.as_str() {
        "escape" | "esc" => "Esc",
        " " | "space" | "spacebar" => "Space",
        "+" | "plus" => "Plus",
        "up" | "arrowup" => "Up",
        "down" | "arrowdown" => "Down",
        "left" | "arrowleft" => "Left",
        "right" | "arrowright" => "Right",
        "pageup" => "PageUp",
        "pagedown" => "PageDown",
        "enter" | "return" => "Enter",
        "backspace" => "Backspace",
        "delete" | "del" => "Delete",
        "tab" => "Tab",
        "home" => "Home",
        "end" => "End",
        "insert" => "Insert",
        "bracketleft" | "х" => "[",
        "bracketright" | "ъ" => "]",
        "backquote" | "grave" => "`",
        "comma" => ",",
        "period" => ".",
        "slash" => "/",
        "backslash" => "\\",
        "semicolon" => ";",
        "quote" => "'",
        "minus" => "-",
        "equal" => "=",
        "control" | "ctrl" | "shift" | "alt" | "option" | "command" | "cmd" | "meta" | "super"
        | "win" | "windows" | "function" | "fn" => return None,
        _ if lower
            .strip_prefix('f')
            .and_then(|number| number.parse::<u8>().ok())
            .is_some_and(|number| (1..=24).contains(&number)) =>
        {
            return Some(lower.to_ascii_uppercase());
        }
        _ if lower.len() == 4 && lower.starts_with("key") => {
            return canonical_shortcut_key(&lower[3..]);
        }
        _ if lower.len() == 6 && lower.starts_with("digit") => {
            return canonical_shortcut_key(&lower[5..]);
        }
        _ => {
            let mut characters = raw_key.chars();
            let character = characters.next()?;
            if characters.next().is_some() || character.is_control() {
                return None;
            }
            return Some(if character.is_ascii_alphabetic() {
                character.to_ascii_uppercase().to_string()
            } else {
                character.to_string()
            });
        }
    };
    Some(key.to_owned())
}

fn normalized_shortcut_chord(raw_chord: &str) -> Option<String> {
    let mut control = false;
    let mut platform = false;
    let mut alt = false;
    let mut shift = false;
    let mut function = false;
    let mut key = None;
    for token in raw_chord.split('+') {
        let token = token.trim();
        match token.to_ascii_lowercase().as_str() {
            "cmdorctrl" => {
                if cfg!(target_os = "macos") {
                    platform = true;
                } else {
                    control = true;
                }
            }
            "control" | "ctrl" => control = true,
            "command" | "cmd" | "meta" | "super" | "win" | "windows" => platform = true,
            "alt" | "option" => alt = true,
            "shift" => shift = true,
            "function" | "fn" => function = true,
            _ => {
                if key.is_some() {
                    return None;
                }
                key = canonical_shortcut_key(token);
            }
        }
    }
    let key = key?;
    let mut tokens = Vec::with_capacity(6);
    if control {
        tokens.push("Ctrl".to_owned());
    }
    if platform {
        tokens.push(
            if cfg!(target_os = "macos") {
                "Command"
            } else {
                "Super"
            }
            .to_owned(),
        );
    }
    if alt {
        tokens.push("Alt".to_owned());
    }
    if shift {
        tokens.push("Shift".to_owned());
    }
    if function {
        tokens.push("Fn".to_owned());
    }
    tokens.push(key);
    Some(tokens.join("+"))
}

fn normalized_accelerator(value: &str) -> Option<Vec<String>> {
    let value = value.trim();
    if value.is_empty() || value.len() > MAX_KEYBOARD_SHORTCUT_ACCELERATOR_BYTES {
        return None;
    }
    let chords = value
        .split_whitespace()
        .map(normalized_shortcut_chord)
        .collect::<Option<Vec<_>>>()?;
    (!chords.is_empty() && chords.len() <= 2).then_some(chords)
}

fn accelerator_from_keystroke(keystroke: &gpui::Keystroke) -> Option<String> {
    let key = canonical_shortcut_key(&keystroke.key)?;
    let modifiers = keystroke.modifiers;
    let mut tokens = Vec::with_capacity(6);
    if modifiers.control {
        tokens.push("Ctrl".to_owned());
    }
    if modifiers.platform {
        tokens.push(
            if cfg!(target_os = "macos") {
                "Command"
            } else {
                "Super"
            }
            .to_owned(),
        );
    }
    if modifiers.alt {
        tokens.push("Alt".to_owned());
    }
    if modifiers.shift {
        tokens.push("Shift".to_owned());
    }
    if modifiers.function {
        tokens.push("Fn".to_owned());
    }
    tokens.push(key);
    Some(tokens.join("+"))
}

fn accelerators_conflict(left: &str, right: &str) -> bool {
    let (Some(left), Some(right)) = (normalized_accelerator(left), normalized_accelerator(right))
    else {
        return false;
    };
    left.iter().zip(&right).all(|(left, right)| left == right)
}

fn accelerator_is_strict_prefix(prefix: &str, accelerator: &str) -> bool {
    let (Some(prefix), Some(accelerator)) = (
        normalized_accelerator(prefix),
        normalized_accelerator(accelerator),
    ) else {
        return false;
    };
    prefix.len() < accelerator.len()
        && prefix
            .iter()
            .zip(accelerator.iter())
            .all(|(prefix, accelerator)| prefix == accelerator)
}

fn archived_project_label(path: &Path) -> String {
    path.file_name()
        .and_then(|name| name.to_str())
        .filter(|name| !name.trim().is_empty())
        .map_or_else(|| display_path(path), str::to_owned)
}

fn archived_chat_projects(tasks: &[TaskSummary]) -> Vec<PathBuf> {
    let mut seen = HashSet::new();
    let mut projects = tasks
        .iter()
        .filter(|task| !task.cwd.as_os_str().is_empty())
        .filter_map(|task| seen.insert(task.cwd.clone()).then_some(task.cwd.clone()))
        .collect::<Vec<_>>();
    projects.sort_by(|left, right| {
        archived_project_label(left)
            .to_lowercase()
            .cmp(&archived_project_label(right).to_lowercase())
            .then_with(|| display_path(left).cmp(&display_path(right)))
    });
    projects
}

fn archived_chat_groups(
    tasks: &[TaskSummary],
    kind_filter: ArchivedChatKindFilter,
    project_filter: &ArchivedChatProjectFilter,
    search_query: &str,
    sort_key: ArchivedChatSortKey,
) -> Vec<ArchivedChatGroup> {
    if kind_filter == ArchivedChatKindFilter::Cloud {
        return Vec::new();
    }
    let query = bounded_settings_search_query(search_query);
    let query = query.trim().to_lowercase();
    let mut filtered = tasks
        .iter()
        .filter(|task| match project_filter {
            ArchivedChatProjectFilter::All => true,
            ArchivedChatProjectFilter::Project(project) => task.cwd == *project,
            ArchivedChatProjectFilter::Chats => task.cwd.as_os_str().is_empty(),
        })
        .filter(|task| {
            if query.is_empty() {
                return true;
            }
            let candidate = format!(
                "{} {} {}",
                task.title,
                task.preview,
                display_path(&task.cwd)
            )
            .to_lowercase();
            query
                .split_whitespace()
                .all(|term| candidate.contains(term) || is_fuzzy_subsequence(term, &candidate))
        })
        .cloned()
        .collect::<Vec<_>>();
    filtered.sort_by(|left, right| archived_chat_task_order(left, right, sort_key));
    if filtered.is_empty() {
        return Vec::new();
    }
    if *project_filter != ArchivedChatProjectFilter::All {
        return vec![ArchivedChatGroup {
            project: None,
            tasks: filtered,
        }];
    }

    let mut group_indexes = HashMap::<Option<PathBuf>, usize>::new();
    let mut groups = Vec::<ArchivedChatGroup>::new();
    for task in filtered {
        let project = (!task.cwd.as_os_str().is_empty()).then(|| task.cwd.clone());
        if let Some(index) = group_indexes.get(&project).copied() {
            groups[index].tasks.push(task);
        } else {
            group_indexes.insert(project.clone(), groups.len());
            groups.push(ArchivedChatGroup {
                project,
                tasks: vec![task],
            });
        }
    }
    groups.sort_by(|left, right| archived_chat_group_order(left, right, sort_key));
    groups
}

fn archived_chat_task_order(
    left: &TaskSummary,
    right: &TaskSummary,
    sort_key: ArchivedChatSortKey,
) -> Ordering {
    let title_order = || {
        left.title
            .to_lowercase()
            .cmp(&right.title.to_lowercase())
            .then_with(|| left.id.cmp(&right.id))
    };
    match sort_key {
        ArchivedChatSortKey::Updated => right
            .updated_at
            .cmp(&left.updated_at)
            .then_with(title_order),
        ArchivedChatSortKey::Created => right
            .created_at
            .cmp(&left.created_at)
            .then_with(title_order),
        ArchivedChatSortKey::Alphabetical => {
            title_order().then_with(|| right.updated_at.cmp(&left.updated_at))
        }
    }
}

fn archived_chat_group_order(
    left: &ArchivedChatGroup,
    right: &ArchivedChatGroup,
    sort_key: ArchivedChatSortKey,
) -> Ordering {
    if sort_key == ArchivedChatSortKey::Alphabetical {
        let sort_label = |group: &ArchivedChatGroup| {
            group
                .project
                .as_deref()
                .map_or_else(String::new, archived_project_label)
        };
        return sort_label(left)
            .to_lowercase()
            .cmp(&sort_label(right).to_lowercase());
    }
    let timestamp = |group: &ArchivedChatGroup| {
        group
            .tasks
            .iter()
            .map(|task| match sort_key {
                ArchivedChatSortKey::Created => task.created_at,
                ArchivedChatSortKey::Updated | ArchivedChatSortKey::Alphabetical => task.updated_at,
            })
            .max()
            .unwrap_or_default()
    };
    timestamp(right)
        .cmp(&timestamp(left))
        .then_with(|| archived_chat_group_label(left).cmp(&archived_chat_group_label(right)))
}

fn archived_chat_group_label(group: &ArchivedChatGroup) -> String {
    group
        .project
        .as_deref()
        .map_or_else(|| "No project".to_owned(), archived_project_label)
}

fn archived_chat_description(task: &TaskSummary, show_project_name: bool) -> Option<String> {
    let timestamp = if task.updated_at > 0 {
        task.updated_at
    } else {
        task.created_at
    };
    let date_time = Local
        .timestamp_opt(timestamp, 0)
        .single()
        .map(|date_time| date_time.format("%b %-d, %Y, %-I:%M %p").to_string())?;
    if show_project_name && !task.cwd.as_os_str().is_empty() {
        Some(format!(
            "{date_time} • {}",
            archived_project_label(&task.cwd)
        ))
    } else {
        Some(date_time)
    }
}

