    #[test]
    fn process_manager_auto_refreshes_only_while_idle_and_open() {
        let mut manager = ProcessManagerState {
            status: LoadStatus::Ready,
            ..ProcessManagerState::default()
        };

        assert!(process_manager_auto_refresh_allowed(true, &manager));
        assert!(!process_manager_auto_refresh_allowed(false, &manager));

        manager.status = LoadStatus::Loading;
        assert!(!process_manager_auto_refresh_allowed(true, &manager));
        manager.status = LoadStatus::Ready;
        manager.terminating_process_ids.push("process-1".to_owned());
        assert!(!process_manager_auto_refresh_allowed(true, &manager));
        manager.terminating_process_ids.clear();
        manager.cleaning = true;
        assert!(!process_manager_auto_refresh_allowed(true, &manager));
    }

    #[test]
    fn conversation_markdown_matches_the_stable_supported_contract() {
        let mut user = timeline_item(TimelineKind::User, "ship it\nnow", None);
        user.attachments.push(ComposerAttachment {
            path: PathBuf::from(r"C:\repo\src\lib.rs"),
            name: "src/lib.rs".to_owned(),
            kind: ComposerAttachmentKind::Mention,
        });
        let items = vec![
            user,
            timeline_item(
                TimelineKind::Agent,
                "Done.\n\n::git-stage{cwd=\"C:\\repo\"}",
                None,
            ),
            timeline_item(TimelineKind::Reasoning, "private reasoning", None),
            timeline_item(
                TimelineKind::Command,
                "Ran cargo test",
                Some("$ cargo test\nok"),
            ),
            timeline_item(TimelineKind::Plan, "1. Verify\n2. Ship", None),
        ];

        let Some(markdown) = render_conversation_markdown(" Fix #42 ", &items, false) else {
            panic!("conversation should render");
        };
        assert_eq!(
            markdown,
            "# Fix \\#42\n\n\
             > ship it\n\
             > now\n\
             >\n\
             > User context\n\
             >\n\
             > Attachments:\n\
             > - Attachment src/lib.rs: `C:\\repo\\src\\lib.rs`\n\n\
             Done.\n\n\
             <details><summary>Ran cargo test</summary>\n\n\
             $ cargo test\n\
             ok\n\n\
             </details>\n\n\
             Plan\n\n\
             1. Verify\n\
             2. Ship\n"
        );
        assert!(!markdown.contains("private reasoning"));
        assert!(!markdown.contains("::git-stage"));
    }

