    #[test]
    fn appearance_share_strings_round_trip_raw_and_uri_encoded_payloads() {
        let mut palette = AppearancePalette::proof_light();
        palette.code_font = Some("JetBrains Mono".to_owned());
        palette.ui_font = Some("Inter".to_owned());
        let raw = appearance_theme_share_string(AppearanceVariant::Light, &palette);

        assert_eq!(
            parse_appearance_theme_share_string(&raw),
            Ok((AppearanceVariant::Light, palette.clone()))
        );

        let Some(payload) = raw.strip_prefix(APPEARANCE_THEME_SHARE_PREFIX) else {
            panic!("generated theme must use the share prefix");
        };
        let encoded_payload = payload
            .as_bytes()
            .iter()
            .map(|byte| format!("%{byte:02X}"))
            .collect::<String>();
        let encoded = format!("{APPEARANCE_THEME_SHARE_PREFIX}{encoded_payload}");
        assert_eq!(
            parse_appearance_theme_share_string(&encoded),
            Ok((AppearanceVariant::Light, palette))
        );
        assert!(parse_appearance_theme_share_string("codex-theme-v1:%GG").is_err());

        for color in [0x00_00_00, 0x33_9c_ff, 0xf5_f3_ed, 0xff_ff_ff] {
            assert_eq!(appearance_color_value(appearance_color(color)), Some(color));
        }
    }

