    #[test]
    fn service_tier_slash_commands_follow_the_stable_dynamic_contract() {
        let tiers = [
            ServiceTierOption {
                id: "priority".to_owned(),
                name: "priority".to_owned(),
                description: "Faster responses with priority processing".to_owned(),
            },
            ServiceTierOption {
                id: "ultrafast".to_owned(),
                name: "Ultrafast".to_owned(),
                description: "Fastest available processing".to_owned(),
            },
        ];

        let all = composer_service_tier_commands("/", &tiers, None);
        assert_eq!(all.len(), 2);
        assert_eq!(all[0].tier_id, "priority");
        assert_eq!(all[0].title, "Fast");
        assert_eq!(
            all[0].description,
            "Faster responses with priority processing"
        );
        assert!(!all[0].selected);

        let selected = composer_service_tier_commands("/fast", &tiers, Some("priority"));
        assert_eq!(selected.len(), 1);
        assert_eq!(
            selected[0].description,
            "Turn off Fast and return to standard speed"
        );
        assert!(selected[0].selected);
        assert_eq!(
            composer_service_tier_command_for_query("/fast", &tiers).as_deref(),
            Some("/service-tier:priority")
        );
        assert_eq!(
            composer_service_tier_command_for_query("/service-tier:ultrafast", &tiers).as_deref(),
            Some("/service-tier:ultrafast")
        );
        assert!(composer_service_tier_commands("fast", &tiers, None).is_empty());
    }

    #[test]
    fn skill_commands_follow_the_stable_dynamic_and_at_mention_contracts() {
        let path = if cfg!(windows) {
            PathBuf::from(r"C:\skills\review\SKILL.md")
        } else {
            PathBuf::from("/skills/review/SKILL.md")
        };
        let disabled_path = if cfg!(windows) {
            PathBuf::from(r"C:\skills\hidden\SKILL.md")
        } else {
            PathBuf::from("/skills/hidden/SKILL.md")
        };
        let skills = [
            SkillCard {
                name: "review".to_owned(),
                display_name: "Code review".to_owned(),
                description: "Review the current changes".to_owned(),
                path: path.clone(),
                scope: SkillScope::User,
                enabled: true,
            },
            SkillCard {
                name: "hidden".to_owned(),
                display_name: "Hidden workflow".to_owned(),
                description: "Unavailable".to_owned(),
                path: disabled_path,
                scope: SkillScope::System,
                enabled: false,
            },
        ];

        let all = composer_skill_commands("/", &skills);
        assert_eq!(all.len(), 1);
        assert_eq!(all[0].path, path);
        assert_eq!(all[0].title, "Code review");
        assert_eq!(all[0].description, "Review the current changes");
        assert_eq!(all[0].scope, SkillScope::User);
        assert_eq!(composer_skill_commands("/code", &skills), all);
        assert_eq!(composer_at_skill_commands("", &skills), []);
        assert_eq!(composer_at_skill_commands("review", &skills), all);
        assert_eq!(
            composer_skill_command_for_query("/code-review", &skills),
            Some(format!("/skill:{}", path.display()))
        );
        assert_eq!(
            composer_skill_command_for_query(&format!("/skill:{}", path.display()), &skills),
            Some(format!("/skill:{}", path.display()))
        );
        assert!(composer_skill_commands("review", &skills).is_empty());
    }

    #[test]
    fn app_plugin_and_desktop_mentions_follow_the_stable_sections_and_limits() {
        let mut computer = plugin(
            "computer-use@openai",
            "Computer Use",
            Some("Productivity"),
            None,
        );
        computer.install_name = "computer-use".to_owned();
        computer.installed = true;
        computer.enabled = true;
        let plugins = [computer];
        let app = |id: &str, name: &str, aliases: Vec<&str>| AppCard {
            id: id.to_owned(),
            name: name.to_owned(),
            description: format!("{name} description"),
            plugin_display_names: aliases.into_iter().map(str::to_owned).collect(),
            logo_url: None,
            logo_url_dark: None,
            install_url: None,
            is_accessible: true,
            enabled: true,
        };
        let apps = [
            app("computer-app", "Desktop Control", vec!["Computer Use"]),
            app("calendar", "Calendar", Vec::new()),
            app("drive", "Drive", Vec::new()),
            app("mail", "Mail", Vec::new()),
            app("notes", "Notes", Vec::new()),
        ];
        let desktop_apps = [ComputerApplicationState {
            id: r"C:\Windows\notepad.exe".to_owned(),
            display_name: Some("Notepad".to_owned()),
            last_used_date: None,
            use_count: None,
            is_running: true,
            window_count: 1,
        }];

        let plugin_commands = composer_plugin_commands("", &plugins);
        assert_eq!(plugin_commands.len(), 1);
        assert_eq!(plugin_commands[0].title, "Computer");

        let app_commands = composer_app_commands("", &apps, &plugins);
        assert_eq!(app_commands.len(), 3);
        assert_eq!(
            app_commands
                .iter()
                .map(|command| command.title.as_str())
                .collect::<Vec<_>>(),
            ["Calendar", "Drive", "Mail"]
        );
        assert_eq!(
            composer_app_commands("notes", &apps, &plugins)[0].id,
            "notes"
        );

        assert!(composer_desktop_app_commands("", &desktop_apps, &plugins).is_empty());
        let desktop_commands = composer_desktop_app_commands("note", &desktop_apps, &plugins);
        assert_eq!(desktop_commands.len(), 1);
        assert_eq!(desktop_commands[0].title, "Notepad");
        assert_eq!(desktop_commands[0].description, "Computer use");
    }

