    #[test]
    fn approval_shortcuts_target_only_the_selected_chat_request() {
        let approval = |request_id: &str, task_id: &str| ApprovalRequest {
            request_id: request_id.to_owned(),
            task_id: task_id.to_owned(),
            turn_id: Some("turn-1".to_owned()),
            kind: ApprovalKind::DynamicTool,
            title: "Allow Computer Use?".to_owned(),
            detail: "Control the selected app".to_owned(),
            context: ApprovalContext::DynamicTool,
        };
        let mut state = AppState {
            selected_task_id: Some("thread-2".to_owned()),
            approvals: [
                approval("approval-background", "thread-1"),
                approval("approval-selected", "thread-2"),
            ]
            .into_iter()
            .collect(),
            ..AppState::default()
        };

        assert_eq!(
            selected_approval_request(&state).map(|request| request.request_id.as_str()),
            Some("approval-selected")
        );
        state.selected_task_id = Some("thread-3".to_owned());
        assert!(selected_approval_request(&state).is_none());
    }

    #[test]
    fn task_copy_shortcuts_use_only_the_selected_chat() {
        let mut state = AppState {
            selected_task_id: Some("thread-2".to_owned()),
            tasks: vec![
                task("thread-1", "C:\\repo-one"),
                task("thread-2", "C:\\repo-two"),
            ],
            ..AppState::default()
        };

        assert_eq!(
            selected_task_copy_value(&state, TaskCopyKind::Deeplink).as_deref(),
            Some("codex://threads/thread-2")
        );
        assert_eq!(
            selected_task_copy_value(&state, TaskCopyKind::SessionId).as_deref(),
            Some("thread-2")
        );
        assert_eq!(
            selected_task_copy_value(&state, TaskCopyKind::WorkingDirectory).as_deref(),
            Some("C:\\repo-two")
        );

        state.selected_task_id = Some("thread-missing".to_owned());
        assert_eq!(
            selected_task_copy_value(&state, TaskCopyKind::SessionId).as_deref(),
            Some("thread-missing")
        );
        assert!(selected_task_copy_value(&state, TaskCopyKind::WorkingDirectory).is_none());
        state.selected_task_id = None;
        assert!(selected_task_copy_value(&state, TaskCopyKind::Deeplink).is_none());
    }

    #[test]
    fn linked_pull_request_merge_requires_the_authored_mergeable_pr() {
        let url = "https://github.com/Kiwunaka/codexRS/pull/42";
        let detail = PullRequestDetail {
            summary: PullRequestSummary {
                identity: PullRequestIdentity {
                    hostname: "github.com".to_owned(),
                    owner: "Kiwunaka".to_owned(),
                    repository: "codexRS".to_owned(),
                    number: 42,
                },
                node_id: "PR_fixture".to_owned(),
                title: "Native Git commands".to_owned(),
                url: url.to_owned(),
                state: PullRequestState::Open,
                is_draft: false,
                author_login: Some("Kiwunaka".to_owned()),
                base_branch: "main".to_owned(),
                head_branch: "codex/native-git-commands".to_owned(),
                additions: 12,
                deletions: 3,
                created_at: "2026-07-25T00:00:00Z".to_owned(),
                updated_at: "2026-07-25T01:00:00Z".to_owned(),
                ci_status: PullRequestCiStatus::Passing,
                is_author: true,
            },
            body: String::new(),
            head_revision: "0123456789abcdef".to_owned(),
            review_decision: None,
            mergeable: Some("MERGEABLE".to_owned()),
            merge_state_status: Some("CLEAN".to_owned()),
            checks: Vec::new(),
            activity: Vec::new(),
            checks_partial: false,
            activity_partial: false,
        };
        assert!(pull_request_merge_submission_enabled(&detail, None));
        assert!(!pull_request_merge_submission_enabled(
            &detail,
            Some(PullRequestMutationKind::Merge)
        ));

        let mut state = AppState::default();
        state.git.pull_request = Some(GitPullRequestState {
            number: Some(42),
            title: detail.summary.title.clone(),
            url: url.to_owned(),
            base_branch: detail.summary.base_branch.clone(),
            head_branch: detail.summary.head_branch.clone(),
            is_draft: false,
        });
        state.pull_requests.detail = Some(detail.clone());
        assert!(linked_pull_request_merge_command_enabled(&state));

        let Some(detail) = state.pull_requests.detail.as_mut() else {
            panic!("fixture detail must exist");
        };
        detail.summary.is_author = false;
        assert!(!linked_pull_request_merge_command_enabled(&state));
        let Some(detail) = state.pull_requests.detail.as_ref() else {
            panic!("fixture detail must exist");
        };
        assert!(!pull_request_merge_submission_enabled(detail, None));
    }

    #[test]
    fn composer_reasoning_shortcuts_follow_the_stable_order_and_bounds() {
        let efforts = ["low", "medium", "high"]
            .into_iter()
            .map(|id| ReasoningEffortOption {
                id: id.to_owned(),
                description: String::new(),
            })
            .collect::<Vec<_>>();

        assert_eq!(
            reasoning_effort_target(&efforts, "medium", ReasoningEffortStep::Increase),
            Some("high")
        );
        assert_eq!(
            reasoning_effort_target(&efforts, "medium", ReasoningEffortStep::Decrease),
            Some("low")
        );
        assert_eq!(
            reasoning_effort_target(&efforts, "high", ReasoningEffortStep::Increase),
            None
        );
        assert_eq!(
            reasoning_effort_target(&efforts, "low", ReasoningEffortStep::Decrease),
            None
        );
        assert_eq!(
            reasoning_effort_target(&efforts, "high", ReasoningEffortStep::Cycle),
            Some("low")
        );
        assert_eq!(
            reasoning_effort_target(&efforts, "missing", ReasoningEffortStep::Cycle),
            None
        );
    }

    #[test]
    fn composer_photo_shortcut_uses_the_stable_image_extensions() {
        for path in [
            "C:\\repo\\screen.png",
            "C:\\repo\\screen.JPG",
            "C:\\repo\\screen.jpeg",
            "C:\\repo\\screen.gif",
            "C:\\repo\\screen.webp",
        ] {
            assert!(is_stable_composer_photo(Path::new(path)), "{path}");
        }
        for path in [
            "C:\\repo\\screen.avif",
            "C:\\repo\\screen.bmp",
            "C:\\repo\\screen.svg",
            "C:\\repo\\notes.md",
            "C:\\repo\\image",
        ] {
            assert!(!is_stable_composer_photo(Path::new(path)), "{path}");
        }
    }

