    #[test]
    fn editable_keyboard_shortcuts_normalize_search_and_prefix_conflicts() {
        let expected_primary = if cfg!(target_os = "macos") {
            "Command+Shift+K"
        } else {
            "Ctrl+Shift+K"
        };
        assert_eq!(
            normalized_accelerator("CmdOrCtrl+Shift+k"),
            Some(vec![expected_primary.to_owned()])
        );
        assert_eq!(
            normalized_accelerator("Ctrl+K Ctrl+S"),
            Some(vec!["Ctrl+K".to_owned(), "Ctrl+S".to_owned()])
        );
        assert!(accelerators_conflict("Ctrl+K", "Ctrl+K Ctrl+S"));
        assert!(accelerators_conflict("Ctrl+K Ctrl+S", "ctrl+k ctrl+s"));
        assert!(!accelerators_conflict("Ctrl+K", "Ctrl+L"));
        assert!(normalized_accelerator("Ctrl+Alt").is_none());

        let Some(command_menu) = ACTIVE_KEYBOARD_SHORTCUTS
            .iter()
            .find(|item| item.id == "openCommandMenu")
        else {
            panic!("openCommandMenu must remain editable");
        };
        let bindings = vec![expected_primary.to_owned()];
        assert!(keyboard_shortcut_settings_matches(
            command_menu,
            &bindings,
            "command menu",
            false,
        ));
        assert!(keyboard_shortcut_settings_matches(
            command_menu,
            &bindings,
            expected_primary,
            true,
        ));
        assert!(!keyboard_shortcut_settings_matches(
            command_menu,
            &["Ctrl+PageDown".to_owned()],
            "Ctrl+N",
            true,
        ));
        assert!(!keyboard_shortcut_settings_matches(
            command_menu,
            &bindings,
            "billing",
            false,
        ));
    }

