    #[test]
    fn navigation_history_is_bounded_and_truncates_the_forward_branch() {
        let location = |route, task_id: Option<&str>| NavigationLocation {
            route,
            selected_task_id: task_id.map(str::to_owned),
        };
        let initial = location(MainRoute::Tasks, None);
        let mut history = NavigationHistory::new(initial.clone());
        history.record(location(MainRoute::Repository, None));
        history.record(location(MainRoute::Settings, None));
        history.index = 1;
        history.record(location(MainRoute::Marketplace, None));

        assert_eq!(
            history.entries,
            [
                initial,
                location(MainRoute::Repository, None),
                location(MainRoute::Marketplace, None),
            ]
        );
        assert_eq!(history.index, 2);

        for index in 0..(MAX_NAVIGATION_HISTORY_ENTRIES + 10) {
            history.record(location(MainRoute::Tasks, Some(&format!("task-{index}"))));
        }
        assert_eq!(history.entries.len(), MAX_NAVIGATION_HISTORY_ENTRIES);
        assert_eq!(history.index, MAX_NAVIGATION_HISTORY_ENTRIES - 1);
        assert_eq!(
            history.entries.last(),
            Some(&location(
                MainRoute::Tasks,
                Some(&format!("task-{}", MAX_NAVIGATION_HISTORY_ENTRIES + 9)),
            ))
        );
    }

    #[test]
    fn thread_find_is_unicode_safe_case_insensitive_and_bounded() {
        let item = |id: usize, text: &str, detail: Option<&str>| TimelineItem {
            id: format!("item-{id}"),
            turn_id: format!("turn-{id}"),
            kind: TimelineKind::Agent,
            text: text.to_owned(),
            detail: detail.map(str::to_owned),
            process_id: None,
            memory_citations: Vec::new(),
            sources: Vec::new(),
            attachments: Vec::new(),
            output_artifacts: Vec::new(),
            edit_supported: false,
            completed: true,
        };
        let items = vec![
            item(0, "Привет из Codex", None),
            item(1, "Ran command", Some("src/lib.rs:10")),
            item(2, "No match", None),
        ];

        assert_eq!(find_timeline_matches(&items, "ПРИВЕТ").item_indices, [0]);
        assert_eq!(find_timeline_matches(&items, "SRC/LIB").item_indices, [1]);
        let bounded = bounded_thread_find_query(&"я".repeat(600));
        assert!(bounded.len() <= super::MAX_THREAD_FIND_QUERY_BYTES);
        assert!(bounded.is_char_boundary(bounded.len()));

        let capped_items = (0..=MAX_THREAD_FIND_MATCHES)
            .map(|id| item(id, "needle", None))
            .collect::<Vec<_>>();
        let matches = find_timeline_matches(&capped_items, "needle");
        assert_eq!(matches.item_indices.len(), MAX_THREAD_FIND_MATCHES);
        assert!(matches.is_capped);
    }

