    #[test]
    fn archived_chat_controls_follow_the_stable_filter_group_and_sort_defaults() {
        let mut alpha = task("Alpha", "C:\\code\\alpha");
        alpha.preview = "native desktop".to_owned();
        alpha.created_at = 20;
        alpha.updated_at = 40;
        let mut beta = task("Beta", "C:\\code\\beta");
        beta.created_at = 30;
        beta.updated_at = 50;
        let mut older_alpha = task("Older", "C:\\code\\alpha");
        older_alpha.created_at = 10;
        older_alpha.updated_at = 15;
        let mut projectless = task("Chat", "");
        projectless.created_at = 60;
        projectless.updated_at = 25;
        let tasks = vec![alpha, beta, older_alpha, projectless];

        let projects = archived_chat_projects(&tasks);
        assert_eq!(
            projects,
            [
                PathBuf::from("C:\\code\\alpha"),
                PathBuf::from("C:\\code\\beta")
            ]
        );

        let updated = archived_chat_groups(
            &tasks,
            ArchivedChatKindFilter::All,
            &ArchivedChatProjectFilter::All,
            "",
            ArchivedChatSortKey::Updated,
        );
        assert_eq!(updated.len(), 3);
        assert_eq!(updated[0].project, Some(PathBuf::from("C:\\code\\beta")));
        assert_eq!(updated[1].project, Some(PathBuf::from("C:\\code\\alpha")));
        assert!(updated[2].project.is_none());
        assert_eq!(updated[1].tasks[0].id, "Alpha");

        let created = archived_chat_groups(
            &tasks,
            ArchivedChatKindFilter::Local,
            &ArchivedChatProjectFilter::Project(PathBuf::from("C:\\code\\alpha")),
            "ntve dsk",
            ArchivedChatSortKey::Created,
        );
        assert_eq!(created.len(), 1);
        assert!(created[0].project.is_none());
        assert_eq!(created[0].tasks[0].id, "Alpha");

        let alphabetical = archived_chat_groups(
            &tasks,
            ArchivedChatKindFilter::All,
            &ArchivedChatProjectFilter::All,
            "",
            ArchivedChatSortKey::Alphabetical,
        );
        assert!(alphabetical[0].project.is_none());
        assert_eq!(
            alphabetical[1].project,
            Some(PathBuf::from("C:\\code\\alpha"))
        );
        assert!(
            archived_chat_groups(
                &tasks,
                ArchivedChatKindFilter::Cloud,
                &ArchivedChatProjectFilter::All,
                "",
                ArchivedChatSortKey::Updated,
            )
            .is_empty()
        );
    }

    #[test]
    fn archived_delete_confirmation_copy_matches_the_stable_scopes() {
        assert_eq!(
            archived_delete_confirmation_copy(ArchivedChatDeleteScope::Single, 1),
            (
                "Delete archived chat?",
                "This permanently deletes the archived chat".to_owned()
            )
        );
        assert_eq!(
            archived_delete_confirmation_copy(ArchivedChatDeleteScope::Project, 1),
            (
                "Delete all in project?",
                "This permanently deletes 1 local archived chat in this project".to_owned()
            )
        );
        assert_eq!(
            archived_delete_confirmation_copy(ArchivedChatDeleteScope::Project, 3),
            (
                "Delete all in project?",
                "This permanently deletes 3 local archived chats in this project".to_owned()
            )
        );
        assert_eq!(
            archived_delete_confirmation_copy(ArchivedChatDeleteScope::All, 3),
            (
                "Delete all archived local chats?",
                "This permanently deletes all local archived chats".to_owned()
            )
        );
    }

    #[test]
    fn adjacent_chat_navigation_follows_the_visible_sidebar_order_without_wrapping() {
        let tasks = vec![
            task("project-a-new", r"C:\project-a"),
            task("project-b", r"C:\project-b"),
            task("project-a-old", r"C:\project-a"),
            task("pinned", r"C:\project-c"),
        ];
        let pinned = vec!["pinned".to_owned()];

        assert_eq!(
            adjacent_task_id(&tasks, &pinned, None, true).as_deref(),
            Some("pinned")
        );
        assert_eq!(
            adjacent_task_id(&tasks, &pinned, None, false).as_deref(),
            Some("project-b")
        );
        assert_eq!(
            adjacent_task_id(&tasks, &pinned, Some("pinned"), true).as_deref(),
            Some("project-a-new")
        );
        assert_eq!(
            adjacent_task_id(&tasks, &pinned, Some("project-a-new"), true).as_deref(),
            Some("project-a-old")
        );
        assert_eq!(
            adjacent_task_id(&tasks, &pinned, Some("project-a-old"), true).as_deref(),
            Some("project-b")
        );
        assert_eq!(
            adjacent_task_id(&tasks, &pinned, Some("project-b"), false).as_deref(),
            Some("project-a-old")
        );
        assert_eq!(
            adjacent_task_id(&tasks, &pinned, Some("pinned"), false),
            None
        );
        assert_eq!(
            adjacent_task_id(&tasks, &pinned, Some("project-b"), true),
            None
        );
        assert_eq!(task_slot_id(&tasks, &pinned, 1).as_deref(), Some("pinned"));
        assert_eq!(
            task_slot_id(&tasks, &pinned, 2).as_deref(),
            Some("project-a-new")
        );
        assert_eq!(
            task_slot_id(&tasks, &pinned, 4).as_deref(),
            Some("project-b")
        );
        assert_eq!(task_slot_id(&tasks, &pinned, 0), None);
        assert_eq!(task_slot_id(&tasks, &pinned, 5), None);
        assert_eq!(command_task_slot("thread1"), Some(1));
        assert_eq!(command_task_slot("thread9"), Some(9));
        assert_eq!(command_task_slot("thread0"), None);
        assert_eq!(command_task_slot("thread10"), None);
    }

    #[test]
    fn composer_file_query_is_cursor_aware_and_replaces_only_the_active_mention() {
        let value = "inspect @src/lib now";
        let cursor = "inspect @src/lib".len();
        let query = match composer_file_query(value, cursor) {
            Some(query) => query,
            None => panic!("active mention should parse"),
        };
        assert_eq!(query.query, "src/lib");
        assert_eq!(&value[query.range.clone()], "@src/lib");

        let (value, cursor) = replace_composer_file_query(value, &query.range, "");
        assert_eq!(value, "inspect now");
        assert_eq!(cursor, "inspect ".len());
        assert_eq!(
            input_position_for_offset("привет\nмир", "привет\nми".len()).line,
            1
        );
        assert_eq!(
            input_position_for_offset("привет\nмир", "привет\nми".len()).character,
            2
        );

        assert_eq!(
            composer_file_query("mail@example.com", "mail@example".len()),
            None
        );
        assert_eq!(
            composer_file_query("@", 1).map(|query| query.query),
            Some(String::new())
        );
    }

