    #[test]
    fn assistant_findings_follow_the_stable_code_comment_directive() {
        let markdown = "Проверил.\n\n::code-comment{title=\"[P1] Race\" body=\"Lock before write.\\nKeep the section atomic.\" file=\"crates/core.rs\" start=\"40\" end=\"42\" priority=\"1\"}\n\n```text\n::code-comment{title=\"keep\" body=\"inside code\" file=\"ignored.rs\"}\n```";
        let findings = extract_code_comment_findings(markdown);
        let Some(sanitized) = sanitize_assistant_markdown(markdown) else {
            panic!("valid markdown");
        };

        assert_eq!(
            findings,
            [AssistantFinding {
                title: "[P1] Race".to_owned(),
                body: "Lock before write.\nKeep the section atomic.".to_owned(),
                file: "crates/core.rs".to_owned(),
                line_start: 40,
                line_end: 42,
                priority: Some(1),
            }]
        );
        assert!(!sanitized.contains("file=\"crates/core.rs\""));
        assert!(sanitized.contains("```text\n::code-comment"));
    }

