    #[test]
    fn unified_diff_tracks_real_old_and_new_line_numbers() {
        let lines = parse_unified_diff(
            "diff --git a/a.rs b/a.rs\n@@ -10,3 +20,3 @@\n same\n-old\n+new\n end\n",
            100,
        );

        assert_eq!(lines[2].old_line, Some(10));
        assert_eq!(lines[2].new_line, Some(20));
        assert_eq!(lines[3].kind, DiffLineKind::Removed);
        assert_eq!(lines[3].old_line, Some(11));
        assert_eq!(lines[3].new_line, None);
        assert_eq!(lines[4].kind, DiffLineKind::Added);
        assert_eq!(lines[4].old_line, None);
        assert_eq!(lines[4].new_line, Some(21));
        assert_eq!(lines[5].old_line, Some(12));
        assert_eq!(lines[5].new_line, Some(22));
    }

    #[test]
    fn split_diff_pairs_replacement_blocks() {
        let lines = parse_unified_diff("@@ -1,2 +1,2 @@\n-old\n+new\n same\n", 100);
        let rows = split_diff_rows(&lines);

        assert_eq!(rows.len(), 3);
        assert!(rows[1].left.is_some());
        assert!(rows[1].right.is_some());
        assert_eq!(
            rows[1].left.as_ref().map(|line| line.text.as_str()),
            Some("old")
        );
        assert_eq!(
            rows[1].right.as_ref().map(|line| line.text.as_str()),
            Some("new")
        );
    }

    #[test]
    fn plugin_catalog_keeps_featured_order_and_category_membership() {
        let plugins = vec![
            plugin("alpha", "Alpha", Some("Coding"), Some(1)),
            plugin("beta", "Beta", Some("Productivity"), Some(0)),
            plugin("gamma", "Gamma", Some("Coding"), None),
            plugin("other", "Other plugin", None, None),
        ];

        let sections = build_plugin_catalog_sections(&plugins, "");
        assert_eq!(
            sections
                .iter()
                .map(|section| section.title.as_str())
                .collect::<Vec<_>>(),
            ["Featured", "Coding", "Productivity", "Other"]
        );
        assert_eq!(sections[0].plugin_indices, [1, 0]);
        assert_eq!(sections[1].plugin_indices, [0, 2]);

        let searched = build_plugin_catalog_sections(&plugins, "gamma");
        assert_eq!(searched.len(), 1);
        assert_eq!(searched[0].title, "Coding");
        assert_eq!(searched[0].plugin_indices, [2]);
    }

    #[test]
    fn plugin_logos_accept_only_bounded_https_raster_assets() {
        assert!(is_supported_plugin_logo_url(
            "https://files.openai.com/plugin.png"
        ));
        assert!(!is_supported_plugin_logo_url("http://127.0.0.1/plugin.png"));
        assert!(!is_supported_plugin_logo_url("file:///tmp/plugin.png"));
        assert!(fetch_plugin_logo_blocking("file:///tmp/plugin.png").is_err());

        let hero = include_bytes!("../assets/plugin-directory-hero.webp");
        assert_eq!(
            plugin_logo_format(None, hero),
            Some(gpui::ImageFormat::Webp)
        );
        assert!(validate_plugin_logo_dimensions(gpui::ImageFormat::Webp, hero).is_ok());
        assert!(plugin_logo_format(Some("image/svg+xml"), b"<svg/>").is_some());
        assert!(validate_plugin_logo_dimensions(gpui::ImageFormat::Svg, b"<svg/>").is_err());
    }

