    #[test]
    fn browser_surface_coordinates_account_for_contain_letterboxing() {
        let bounds = gpui::Bounds {
            origin: gpui::point(gpui::px(10.0), gpui::px(20.0)),
            size: gpui::size(gpui::px(400.0), gpui::px(400.0)),
        };
        assert_eq!(
            browser_surface_coordinates(
                bounds,
                gpui::point(gpui::px(210.0), gpui::px(220.0)),
                800,
                400,
            ),
            Some((400, 200))
        );
        assert_eq!(
            browser_surface_coordinates(
                bounds,
                gpui::point(gpui::px(210.0), gpui::px(80.0)),
                800,
                400,
            ),
            None
        );
    }
